  function openEquipamentoModal(existing){
    var isEdit = !!existing;
    var e = existing || {codigo:'',tipo:'',status:'EM_OBRA',observacao:''};
    var depreciacaoHtml = '';
    if(e.denominacao || e.valorDiaDepreciacao){
      depreciacaoHtml = '<div class="shared-note" style="display:block;margin-bottom:14px;">' +
        '<b>Referência do Rateio de Depreciação</b><br>' +
        (e.denominacao ? 'Denominação: '+esc(e.denominacao)+'<br>' : '') +
        (e.tag ? 'Tag: '+esc(e.tag)+' · ' : '') +
        (e.capacidade ? 'Capacidade: '+esc(e.capacidade)+' · ' : '') +
        (e.tipoTecnico ? 'Tipo técnico: '+esc(e.tipoTecnico)+' · ' : '') +
        (e.categoriaImobilizado ? 'Categoria: '+esc(e.categoriaImobilizado) : '') +
        (e.valorDiaDepreciacao ? '<br>Valor/dia (depreciação): R$ '+brNum(e.valorDiaDepreciacao,2) : '') +
      '</div>';
    }
    if(e.descricaoFrota){
      depreciacaoHtml += '<div class="shared-note" style="display:block;margin-bottom:14px;">' +
        '<b>Descrição de frota (banco de dados)</b><br>'+esc(e.descricaoFrota) +
      '</div>';
    }
    openModal(
      '<h3>'+(isEdit?'Editar equipamento':'Novo equipamento')+'</h3>' +
      '<div id="eqFormError"></div>' +
      depreciacaoHtml +
      '<div class="field-row">' +
        '<div class="field"><label>Código</label><input type="text" id="fCodigo" value="'+esc(e.codigo)+'" placeholder="Ex: ESC-77"></div>' +
        '<div class="field"><label>Tipo</label><input type="text" id="fTipo" value="'+esc(e.tipo)+'" placeholder="Ex: ESCAVADEIRA VOLVO EC360"></div>' +
      '</div>' +
      '<div class="field"><label>Observação</label><textarea id="fObs" rows="2">'+esc(e.observacao||'')+'</textarea></div>' +
      '<p style="font-size:12px;color:var(--text-muted);">A obra/ordem de trabalho não é mais fixa no cadastro — ela é definida a cada lançamento de apropriação, já que o equipamento pode circular entre ordens.</p>' +
      '<div class="modal-actions">' +
        '<button class="btn btn-outline" id="eqCancel">Cancelar</button>' +
        '<button class="btn btn-primary" id="eqSave">Salvar</button>' +
      '</div>'
    );
    document.getElementById('eqCancel').onclick = closeModal;
    document.getElementById('eqSave').onclick = async function(){
      var codigo = normalizarEspacos(document.getElementById('fCodigo').value).toUpperCase();
      var errBox = document.getElementById('eqFormError');
      if(!codigo){ errBox.innerHTML = '<div class="form-error">Informe o código do equipamento.</div>'; return; }
      var dup = state.equipamentos.some(function(x){ return x.codigo.toLowerCase()===codigo.toLowerCase() && (!isEdit || x.id!==e.id); });
      if(dup){ errBox.innerHTML = '<div class="form-error">Já existe um equipamento com esse código.</div>'; return; }
      var record = Object.assign({}, e, {
        id: isEdit ? e.id : uid(), codigo: codigo,
        tipo: normalizarTituloCase(document.getElementById('fTipo').value),
        observacao: normalizarEspacos(document.getElementById('fObs').value)
      });
      if(isEdit){ state.equipamentos = state.equipamentos.map(function(x){ return x.id===record.id ? record : x; }); }
      else { state.equipamentos.push(record); }
      var ok = await saveList('equipamentos_v6', state.equipamentos);
      closeModal();
      toast(ok ? 'Equipamento salvo.' : 'Equipamento salvo localmente — houve um problema ao sincronizar.');
      renderAll();
    };
  }
