  /* ---- Gestão de Sugestões: editar/remover as listas de autocomplete ---- */
  /* ---- Exportação/Importação em lote das Descrições Completas (Tarifa/Medição) ---- */
  function tarifaVigenteAgoraPorCodigo(servicoCodigo, tipo){
    var hoje = todayISO();
    var lista = tipo==='verba' ? state.tarifasVerba : state.tarifasProducao;
    var candidatas = lista.filter(function(t){
      return t.servicoCodigo===servicoCodigo && (!t.vigenciaInicio || t.vigenciaInicio<=hoje) && (!t.vigenciaFim || t.vigenciaFim>=hoje);
    });
    if(candidatas.length===0) return null;
    candidatas.sort(function(a,b){ return (b.vigenciaInicio||'').localeCompare(a.vigenciaInicio||''); });
    return candidatas[0];
  }

  // Tabela única de Serviços: nasce das Tarifas (que já têm valor e vigência) — não mais da lista
  // separada em Ordem. Apelido (descrição curta, usada em Produção) e Meta passam a viver na própria
  // tarifa, junto com a descrição completa (usada em Tarifa/Medição) e o valor.
  // ---- Meta mensal com histórico (por serviço/código), igual ao valor da tarifa com vigência ----
  // Cada registro vale a partir do mês informado, até ser substituído por um mais recente — não
  // precisa cadastrar todo mês, só quando a meta muda; os meses sem registro próprio herdam a
  // meta do mês anterior mais recente (ou a meta "padrão" gravada na própria tarifa, se nunca mudou).
  function metaVigenteNoMes(servicoCodigo, mesRef){
    if(!servicoCodigo) return null;
    var historico = state.metasMensais.filter(function(m){ return m.servicoCodigo===servicoCodigo && m.mesRef<=mesRef; });
    if(historico.length===0) return null;
    historico.sort(function(a,b){ return b.mesRef.localeCompare(a.mesRef); });
    return historico[0].meta;
  }
  async function definirMetaAPartirDoMes(servicoCodigo, mesRef, meta){
    var existente = state.metasMensais.filter(function(m){ return m.servicoCodigo===servicoCodigo && m.mesRef===mesRef; })[0];
    if(existente){ existente.meta = meta; }
    else { state.metasMensais.push({id:uid(), servicoCodigo:servicoCodigo, mesRef:mesRef, meta:meta}); }
    await saveList('metas_mensais_v1', state.metasMensais);
  }

  function tarifaEhAVigenteHoje(t, todasDoMesmoCodigo){
    var hoje = todayISO();
    if((!t.vigenciaInicio || t.vigenciaInicio<=hoje) && (!t.vigenciaFim || t.vigenciaFim>=hoje)) return true;
    // se nenhuma bater exatamente com hoje, considera a mais recente do grupo como referência
    var maisRecente = todasDoMesmoCodigo.slice().sort(function(a,b){ return (b.vigenciaInicio||'').localeCompare(a.vigenciaInicio||''); })[0];
    return t===maisRecente;
  }
  function gerarTabelaServicosUnica(){
    var porChave = {};
    var grupos = [
      {lista: state.tarifasProducao, tipoTag:null},
      {lista: state.tarifasHora, tipoTag:'hora'},
      {lista: state.tarifasVerba, tipoTag:'verba'}
    ];
    grupos.forEach(function(g){
      g.lista.forEach(function(t){
        var chave = (t.codigoTarifa || t.servicoCodigo || t.id) + '|' + t.ordemId;
        if(!porChave[chave]) porChave[chave] = {versoes:[], tipoTag:g.tipoTag};
        porChave[chave].versoes.push(t);
      });
    });
    var linhas = [];
    Object.keys(porChave).forEach(function(chave){
      var grupo = porChave[chave];
      var versoes = grupo.versoes;
      var vigente = versoes.filter(function(t){ return tarifaEhAVigenteHoje(t, versoes); })[0] || versoes[0];
      var ordem = getOrdem(vigente.ordemId);
      var tipo = grupo.tipoTag || tipoRealTarifaProducao(vigente);
      linhas.push({
        t: vigente,
        ordem: ordem,
        tipo: tipo
      });
    });
    return linhas;
  }

  // Colunas de lançamento de Produção pra uma ordem, direto da tabela única de Serviços (Tarifa) —
  // usa o Apelido (descrição curta) como rótulo, já que a descrição completa não cabe na grade diária.
  // Importante: "Tarifas por Hora" (Medição → Horas, soma horímetro das Apropriações automaticamente)
  // NÃO entra aqui — só serviços do tipo Hora dentro de Tarifas de Produção, que são lançados manualmente.
  function colunasProducaoDaOrdem(ordemId, mesRef){
    var linhas = gerarTabelaServicosUnica().filter(function(x){ return x.ordem && x.ordem.id===ordemId && x.t.valorHora===undefined; });
    var porTipo = {pesagem:[], hora:[], verba:[]};
    linhas.forEach(function(x){
      var codigo = x.t.codigoTarifa || x.t.servicoCodigo || '';
      var metaDoMes = mesRef ? metaVigenteNoMes(x.t.servicoCodigo||codigo, mesRef) : null;
      porTipo[x.tipo].push({
        nome: x.t.apelido || x.t.servico || codigo,
        meta: metaDoMes!==null ? metaDoMes : (x.t.meta || 0),
        codigoTarifa: codigo,
        servicoCodigo: x.t.servicoCodigo || codigo
      });
    });
    return porTipo;
  }

  function exportarDescricoesCompletas(){
    var linhas = gerarTabelaServicosUnica();
    if(linhas.length===0){ toast('Nenhuma tarifa cadastrada ainda.'); return; }
    var dados = linhas.map(function(x){
      return {
        'Código': x.t.codigoTarifa || x.t.servicoCodigo || '',
        'Nº Ordem': x.ordem ? (x.ordem.numero||'') : '',
        'Cliente': x.ordem ? x.ordem.cliente : '',
        'Descrição completa': x.t.servico || '',
        'Apelido': x.t.apelido || '',
        'Unidade': x.t.unidade || (x.t.valorHora!==undefined ? 'H' : ''),
        'Meta Mensal': x.t.meta || 0,
        'Valor (R$)': x.t.valor!==undefined ? x.t.valor : (x.t.valorHora||'')
      };
    });
    var ws = XLSX.utils.json_to_sheet(dados);
    ws['!cols'] = [{wch:11},{wch:9},{wch:22},{wch:55},{wch:22},{wch:9},{wch:12},{wch:14}];
    var wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Serviços');
    XLSX.writeFile(wb, 'sispoc_tabela_unica_servicos.xlsx');
    toast('Planilha exportada. Preencha Descrição completa, Apelido, Meta e Valor, e importe de volta.');
  }

  async function importarDescricoesCompletas(file){
    var resultadoEl = document.getElementById('importarDescricoesResultado');
    resultadoEl.innerHTML = '<div class="muted-tag">Lendo planilha…</div>';
    try{
      var linhas = await lerPlanilhaComoLinhas(file);
      var atualizadas = 0, naoEncontrados = [];
      linhas.forEach(function(l){
        var codigo = normalizarEspacos(valorColuna(l, ['codigo']));
        var numeroOrdem = normalizarEspacos(valorColuna(l, ['n ordem','numero da ordem','n° ordem']));
        var descCompleta = normalizarEspacos(valorColuna(l, ['descricao completa']));
        var apelido = normalizarEspacos(valorColuna(l, ['apelido']));
        var unidade = normalizarEspacos(valorColuna(l, ['unidade']));
        var metaTxt = normalizarEspacos(valorColuna(l, ['meta mensal']));
        var valorTxt = normalizarEspacos(valorColuna(l, ['valor (r$)','valor']));
        if(!codigo){ return; }
        var ordem = numeroOrdem ? state.ordens.filter(function(o){ return String(o.numero||'')===numeroOrdem; })[0] : null;

        var alvo = null, listaAlvo = null;
        [state.tarifasProducao, state.tarifasHora, state.tarifasVerba].forEach(function(lista){
          if(alvo) return;
          var achado = lista.filter(function(t){ return (t.codigoTarifa===codigo || t.servicoCodigo===codigo) && (!ordem || t.ordemId===ordem.id); })[0];
          if(achado){ alvo = achado; listaAlvo = lista; }
        });
        if(!alvo){ naoEncontrados.push('Código '+codigo+' (ordem '+numeroOrdem+') não encontrado'); return; }

        if(descCompleta) alvo.servico = descCompleta;
        if(apelido) alvo.apelido = apelido;
        if(unidade && alvo.unidade!==undefined) alvo.unidade = unidade;
        var metaNum = parseFloat((metaTxt||'').replace(',','.'));
        if(!isNaN(metaNum)) alvo.meta = metaNum;
        var valorNum = parseFloat((valorTxt||'').replace(',','.'));
        if(!isNaN(valorNum) && valorNum>0){
          if(alvo.valorHora!==undefined) alvo.valorHora = valorNum; else alvo.valor = valorNum;
        }
        atualizadas++;
      });
      await saveList('tarifas_hora_v2', state.tarifasHora);
      await saveList('tarifas_producao_v3', state.tarifasProducao);
      await saveList('tarifas_verba_v1', state.tarifasVerba);
      resultadoEl.innerHTML = '<div class="shared-note" style="display:block;margin-top:10px;">' +
        '<b>'+atualizadas+'</b> serviço(s) atualizado(s).' +
        (naoEncontrados.length ? '<br>'+naoEncontrados.length+' linha(s) não encontrada(s): '+naoEncontrados.slice(0,8).join('; ')+(naoEncontrados.length>8?'…':'') : '') +
        '</div>';
      toast('Planilha importada com sucesso.');
      renderCadastroHub();
      renderTabelaServicosUnica();
    }catch(erro){
      resultadoEl.innerHTML = '<div class="form-error">Não foi possível ler a planilha. Confira se é um .xlsx válido.</div>';
    }
  }

  function renderTabelaServicosUnica(){
    var body = document.getElementById('tabelaServicosUnicaBody');
    if(!body) return;
    var linhas = gerarTabelaServicosUnica();
    if(linhas.length===0){ body.innerHTML = '<tr class="empty-row"><td colspan="7">Nenhuma tarifa cadastrada ainda.</td></tr>'; return; }
    linhas.sort(function(a,b){
      var c = (a.ordem?a.ordem.cliente:'').localeCompare(b.ordem?b.ordem.cliente:'','pt-BR');
      if(c!==0) return c;
      return (a.t.codigoTarifa||'').localeCompare(b.t.codigoTarifa||'');
    });
    body.innerHTML = linhas.map(function(x){
      var valor = x.t.valor!==undefined ? x.t.valor : x.t.valorHora;
      var codigo = x.t.codigoTarifa || x.t.servicoCodigo || '';
      var mesAtual = todayISO().slice(0,7);
      var metaAtiva = metaVigenteNoMes(codigo, mesAtual);
      var metaExibida = metaAtiva!==null ? metaAtiva : (x.t.meta||0);
      return '<tr><td><span class="plate">'+esc(codigo||'—')+'</span></td>' +
        '<td>'+(x.ordem?esc(ordemLabel(x.ordem)):'<span class="muted-tag">(removida)</span>')+'</td>' +
        '<td>'+esc(x.t.servico||'')+'</td><td>'+esc(x.t.apelido||'<span class="muted-tag">—</span>')+'</td>' +
        '<td>'+esc(x.t.unidade||(x.t.valorHora!==undefined?'H':''))+'</td>' +
        '<td class="num">'+brNum(metaExibida,2)+'</td><td class="num">'+brNum(valor||0,2)+'</td></tr>';
    }).join('');
  }

  function valoresColunaMeta(x){
    var codigo = x.t.codigoTarifa || x.t.servicoCodigo || '';
    var mesAtual = todayISO().slice(0,7);
    var historico = state.metasMensais.filter(function(m){ return m.servicoCodigo===codigo; }).sort(function(a,b){ return b.mesRef.localeCompare(a.mesRef); });
    var vigente = historico.filter(function(m){ return m.mesRef<=mesAtual; })[0];
    var metaVigente = vigente ? vigente.meta : (x.t.meta||0);
    var desde = vigente ? vigente.mesRef : 'padrão da tarifa';
    return { codigo: codigo||'—', ordem: x.ordem?ordemLabel(x.ordem):'(removida)', servico: x.t.apelido||x.t.servico||'—', meta: brNum(metaVigente,2), desde: desde };
  }
  function getItensMetas(){ return gerarTabelaServicosUnica().filter(function(x){ return x.t.valorHora===undefined; }); }
  function renderMetasTab(){
    var body = document.getElementById('metasBody');
    if(!body) return;
    var buscaCodigo = normalizarEspacos((document.getElementById('filtroMetaCodigo')||{}).value||'').toLowerCase();
    var buscaOrdem = normalizarEspacos((document.getElementById('filtroMetaOrdem')||{}).value||'').toLowerCase();
    var linhas = getItensMetas();
    linhas = linhas.filter(function(x){
      var codigo = (x.t.codigoTarifa||x.t.servicoCodigo||'').toLowerCase();
      if(buscaCodigo && codigo.indexOf(buscaCodigo)===-1) return false;
      if(buscaOrdem){
        var alvo = ((x.ordem?ordemLabel(x.ordem):'')+' '+(x.t.servico||'')).toLowerCase();
        if(alvo.indexOf(buscaOrdem)===-1) return false;
      }
      return true;
    });
    linhas = aplicaColFiltrosTabela('metas', linhas);
    marcarBotoesFiltroAtivos('metas');
    if(linhas.length===0){ body.innerHTML = '<tr class="empty-row"><td colspan="6">Nenhum serviço encontrado.</td></tr>'; return; }
    var mesAtual = todayISO().slice(0,7);
    linhas.sort(function(a,b){ return (a.t.codigoTarifa||a.t.servicoCodigo||'').localeCompare(b.t.codigoTarifa||b.t.servicoCodigo||''); });
    body.innerHTML = linhas.map(function(x){
      var codigo = x.t.codigoTarifa || x.t.servicoCodigo || '';
      var historico = state.metasMensais.filter(function(m){ return m.servicoCodigo===codigo; }).sort(function(a,b){ return b.mesRef.localeCompare(a.mesRef); });
      var vigente = historico.filter(function(m){ return m.mesRef<=mesAtual; })[0];
      var metaVigente = vigente ? vigente.meta : (x.t.meta||0);
      var desde = vigente ? vigente.mesRef : '<span class="muted-tag">padrão da tarifa</span>';
      return '<tr><td><span class="plate">'+esc(codigo||'—')+'</span></td>' +
        '<td>'+(x.ordem?esc(ordemLabel(x.ordem)):'<span class="muted-tag">(removida)</span>')+'</td>' +
        '<td>'+esc(x.t.apelido||x.t.servico||'')+'</td>' +
        '<td class="num">'+brNum(metaVigente,2)+'</td>' +
        '<td>'+desde+'</td>' +
        '<td><button type="button" class="btn btn-outline btn-sm" data-ver-historico="'+esc(codigo)+'" data-label="'+esc((x.ordem?ordemLabel(x.ordem)+' · ':'')+(x.t.apelido||x.t.servico||''))+'">Ver / editar ('+historico.length+')</button></td></tr>';
    }).join('');
    body.querySelectorAll('[data-ver-historico]').forEach(function(btn){
      btn.addEventListener('click', function(){
        abrirHistoricoMetaModal(btn.getAttribute('data-ver-historico'), btn.getAttribute('data-label'));
      });
    });
    var totalEl = document.getElementById('hubCountMetas');
    if(totalEl) totalEl.textContent = gerarTabelaServicosUnica().filter(function(x){ return x.t.valorHora===undefined; }).length;
  }

  function abrirHistoricoMetaModal(servicoCodigo, label){
    function listaHistoricoHtml(){
      var historico = state.metasMensais.filter(function(m){ return m.servicoCodigo===servicoCodigo; }).sort(function(a,b){ return b.mesRef.localeCompare(a.mesRef); });
      if(historico.length===0) return '<div class="empty-state" style="padding:14px;">Nenhum histórico próprio ainda — usando a meta padrão cadastrada na tarifa.</div>';
      return '<div class="table-wrap"><table><thead><tr><th>Vigente a partir de</th><th class="num">Meta</th><th>Ações</th></tr></thead><tbody>' +
        historico.map(function(m){
          return '<tr><td>'+esc(m.mesRef)+'</td><td class="num">'+brNum(m.meta,2)+'</td>' +
            '<td><button type="button" class="btn-danger-ghost btn-sm" data-del-meta="'+m.id+'">Remover</button></td></tr>';
        }).join('') + '</tbody></table></div>';
    }
    openModal('<h3>Histórico de meta</h3>'+
      '<div class="shared-note" style="display:block;margin-bottom:12px;">'+esc(label)+' · código <b>'+esc(servicoCodigo)+'</b></div>'+
      '<div id="metaHistoricoLista">'+listaHistoricoHtml()+'</div>'+
      '<div class="field-row" style="margin-top:14px;">'+
        '<div class="field"><label>Nova meta a partir do mês</label><input type="month" id="fMetaMes" value="'+esc(todayISO().slice(0,7))+'"></div>'+
        '<div class="field"><label>Valor da meta</label><input type="number" step="0.01" id="fMetaValor" placeholder="Ex: 3000"></div>'+
      '</div>'+
      '<div id="metaFormError"></div>'+
      '<div class="modal-actions"><button class="btn btn-outline" id="metaCancel">Fechar</button><button class="btn btn-primary" id="metaSave">Adicionar</button></div>'
    );
    document.getElementById('metaCancel').onclick = closeModal;
    function religar(){
      document.querySelectorAll('[data-del-meta]').forEach(function(btn){
        btn.onclick = function(){
          var id = btn.getAttribute('data-del-meta');
          confirmModal('Remover meta', 'Remover esse registro de meta do histórico? O mês volta a herdar a meta do registro anterior (ou a meta padrão da tarifa).', async function(){
            state.metasMensais = state.metasMensais.filter(function(m){ return m.id!==id; });
            await saveList('metas_mensais_v1', state.metasMensais);
            document.getElementById('metaHistoricoLista').innerHTML = listaHistoricoHtml();
            religar();
            renderMetasTab();
            toast('Meta removida do histórico.');
          });
        };
      });
    }
    religar();
    document.getElementById('metaSave').onclick = async function(){
      var mesRef = document.getElementById('fMetaMes').value;
      var meta = parseFloat(document.getElementById('fMetaValor').value);
      var errBox = document.getElementById('metaFormError');
      if(!mesRef){ errBox.innerHTML = '<div class="form-error">Escolha o mês a partir do qual a meta vale.</div>'; return; }
      if(isNaN(meta) || meta<0){ errBox.innerHTML = '<div class="form-error">Informe uma meta válida.</div>'; return; }
      await definirMetaAPartirDoMes(servicoCodigo, mesRef, meta);
      document.getElementById('metaHistoricoLista').innerHTML = listaHistoricoHtml();
      religar();
      renderMetasTab();
      toast('Meta definida a partir de '+mesRef+'.');
      document.getElementById('fMetaValor').value = '';
    };
  }

  function abrirNovaMetaModal(){
    var servicos = gerarTabelaServicosUnica().filter(function(x){ return x.t.valorHora===undefined; });
    var labels = servicos.map(function(x){ return (x.ordem?ordemLabel(x.ordem)+' · ':'')+(x.t.apelido||x.t.servico||'')+' ['+(x.t.codigoTarifa||x.t.servicoCodigo)+']'; });
    openModal('<h3>Nova meta</h3>'+
      '<div id="novaMetaError"></div>'+
      '<div class="field"><label>Serviço</label><div class="combo-wrap"><input type="text" id="fNovaMetaServico" autocomplete="off" placeholder="Digite pra buscar…"><div class="combo-list" id="fNovaMetaServicoList"></div></div></div>'+
      '<div class="field-row">'+
        '<div class="field"><label>A partir do mês</label><input type="month" id="fNovaMetaMes" value="'+esc(todayISO().slice(0,7))+'"></div>'+
        '<div class="field"><label>Valor da meta</label><input type="number" step="0.01" id="fNovaMetaValor" placeholder="Ex: 3000"></div>'+
      '</div>'+
      '<div class="modal-actions"><button class="btn btn-outline" id="novaMetaCancel">Cancelar</button><button class="btn btn-primary" id="novaMetaSave">Salvar</button></div>'
    );
    wireComboBox('fNovaMetaServico', 'fNovaMetaServicoList', function(){ return labels; });
    document.getElementById('novaMetaCancel').onclick = closeModal;
    document.getElementById('novaMetaSave').onclick = async function(){
      var texto = document.getElementById('fNovaMetaServico').value.trim();
      var idx = labels.indexOf(texto);
      var mesRef = document.getElementById('fNovaMetaMes').value;
      var meta = parseFloat(document.getElementById('fNovaMetaValor').value);
      var errBox = document.getElementById('novaMetaError');
      if(idx<0){ errBox.innerHTML = '<div class="form-error">Escolha um serviço da lista.</div>'; return; }
      if(!mesRef){ errBox.innerHTML = '<div class="form-error">Escolha o mês a partir do qual a meta vale.</div>'; return; }
      if(isNaN(meta) || meta<0){ errBox.innerHTML = '<div class="form-error">Informe uma meta válida.</div>'; return; }
      var codigo = servicos[idx].t.codigoTarifa || servicos[idx].t.servicoCodigo;
      await definirMetaAPartirDoMes(codigo, mesRef, meta);
      closeModal();
      toast('Meta definida a partir de '+mesRef+'.');
      renderMetasTab();
    };
  }

  function renderSugestoesTab(){
    var grupos = [
      {lista: MATERIAIS_PESAGEM, body: 'sugestoesPesagemBody', storageKey: 'materiais_pesagem_v1', nomeGrupo: 'material'},
      {lista: SERVICOS_HORA, body: 'sugestoesHoraBody', storageKey: 'servicos_hora_v1', nomeGrupo: 'serviço'},
      {lista: SERVICOS_VERBA, body: 'sugestoesVerbaBody', storageKey: 'servicos_verba_v1', nomeGrupo: 'serviço'},
    ];
    grupos.forEach(function(g){
      var el = document.getElementById(g.body);
      if(!el) return;
      if(g.lista.length===0){
        el.innerHTML = '<div class="empty-state" style="padding:14px;">Nenhum '+g.nomeGrupo+' sugerido ainda.</div>';
        return;
      }
      el.innerHTML = g.lista.map(function(nome, idx){
        return '<div class="field-row" style="margin-bottom:6px;align-items:center;">' +
          '<input type="text" data-idx="'+idx+'" value="'+esc(nome)+'" style="flex:1;">' +
          '<button type="button" class="btn-ghost" data-idx-del="'+idx+'" title="Remover" style="padding:6px 10px;">✕</button>' +
        '</div>';
      }).join('');
      el.querySelectorAll('input[data-idx]').forEach(function(input){
        input.addEventListener('change', async function(){
          var idx = parseInt(this.getAttribute('data-idx'),10);
          var novoNome = normalizarTituloCase(this.value);
          if(!novoNome){ this.value = g.lista[idx]; return; }
          g.lista[idx] = novoNome;
          g.lista.sort(function(a,b){ return a.localeCompare(b,'pt-BR'); });
          await saveList(g.storageKey, g.lista);
          toast('Sugestão atualizada.');
          renderSugestoesTab();
        });
      });
      el.querySelectorAll('button[data-idx-del]').forEach(function(btn){
        btn.addEventListener('click', function(){
          var idx = parseInt(this.getAttribute('data-idx-del'),10);
          var nome = g.lista[idx];
          confirmModal('Remover sugestão', 'Remover "'+nome+'" da lista de sugestões? Isso não afeta nada já lançado, só some da sugestão automática.', async function(){
            g.lista.splice(idx,1);
            await saveList(g.storageKey, g.lista);
            toast('Sugestão removida.');
            renderSugestoesTab();
          });
        });
      });
    });
    var totalEl = document.getElementById('hubCountSugestoes');
    if(totalEl) totalEl.textContent = MATERIAIS_PESAGEM.length + SERVICOS_HORA.length + SERVICOS_VERBA.length;
  }

  /** Opções do dropdown "Local" da Ordem — vem da lista compartilhada
   *  Locais (state.locais, mesma do Frota/Checklist). Se a ordem já tinha um
   *  valor de texto livre (de antes desta tela virar dropdown) que não bate
   *  com nenhum local cadastrado, mantém ele como opção extra pra não sumir
   *  silenciosamente do registro. */
  function ordemLocalOptions(selecionado){
    var nomes = (state.locais||[]).map(function(l){ return l.nome; }).sort(function(a,b){ return a.localeCompare(b,'pt-BR'); });
    var out = '<option value="">Nenhum</option>';
    if(selecionado && nomes.indexOf(selecionado)===-1){
      out += '<option value="'+esc(selecionado)+'" selected>'+esc(selecionado)+' (fora da lista de Locais)</option>';
    }
    out += optionsList(nomes, selecionado);
    return out;
  }
  function openOrdemModal(existing){
    var isEdit = !!existing;
    var o = existing || {nome:'', numero:'', cliente:CLIENTES[0], local:'', vendedor:'', modeloContrato:'', cnpj:'', vigenciaContratoInicio:'', vigenciaContratoFim:'', medicaoPesagem:false, medicaoHora:false};
    openModal(
      '<h3>'+(isEdit?'Editar ordem':'Nova ordem')+'</h3>' +
      '<div id="ordFormError"></div>' +
      '<div class="field"><label>Cliente</label><select id="fOrdCliente">'+addNovoClienteOption(optionsList(CLIENTES, o.cliente))+'</select>' +
        '<div id="clienteNumeroWrap" style="margin-top:6px;">' +
          (CLIENTE_NUMEROS[o.cliente] ? '<div class="muted-tag">Nº cliente: '+esc(CLIENTE_NUMEROS[o.cliente])+' (gerencie em Cadastro → Clientes)</div>' : '<div class="muted-tag">Cliente sem número cadastrado ainda — gerencie em Cadastro → Clientes.</div>') +
        '</div>' +
        '<div id="novoClienteWrap" style="display:none;margin-top:8px;">' +
          '<div class="field-row">' +
            '<div class="field"><label>Nome do novo cliente</label><input type="text" id="novoClienteInput" placeholder="Nome do cliente"></div>' +
            '<div class="field"><label>Número do cliente</label><input type="text" id="novoClienteNumero" placeholder="Ex: 10004960"></div>' +
          '</div>' +
          '<button type="button" class="btn btn-outline btn-sm" id="novoClienteBtn">Adicionar cliente</button>' +
        '</div>' +
      '</div>' +
      '<div class="field-row">' +
        '<div class="field"><label>Número da ordem</label><input type="text" id="fOrdNumero" value="'+esc(o.numero||'')+'" placeholder="Ex: 500002"></div>' +
        '<div class="field"><label>Nome da ordem</label><input type="text" id="fOrdNome" value="'+esc(o.nome)+'" placeholder="Ex: Mina de Cauê"></div>' +
      '</div>' +
      '<div class="field-row">' +
        '<div class="field"><label>Local</label><select id="fOrdLocal">'+ordemLocalOptions(o.local)+'</select>' +
          '<div class="shared-note" style="display:block;margin-top:6px;">Mesma lista de locais do Checklist/Frota — cadastre um local novo por lá se não encontrar aqui.</div>' +
        '</div>' +
        '<div class="field"><label>Segmento</label><input type="text" id="fOrdVendedor" value="'+esc(o.vendedor||'')+'" placeholder="Ex: Siderurgia, Descomissionamento"></div>' +
      '</div>' +
      '<div class="field"><label>Modelo de contrato</label><input type="text" id="fOrdModelo" value="'+esc(o.modeloContrato||'')+'" placeholder="Ex: Hora"></div>' +
      '<div class="field"><label>CNPJ</label><input type="text" id="fOrdCnpj" value="'+esc(o.cnpj||'')+'" placeholder="Ex: 17.469.701/0104-82"></div>' +
      '<div class="field-row">' +
        '<div class="field"><label>Vigência do contrato — início</label><input type="date" id="fOrdVigenciaInicio" value="'+esc(o.vigenciaContratoInicio||'')+'"></div>' +
        '<div class="field"><label>Vigência do contrato — fim</label><input type="date" id="fOrdVigenciaFim" value="'+esc(o.vigenciaContratoFim||'')+'"></div>' +
      '</div>' +
      '<div class="field">' +
        '<label>Caracterização da Medição</label>' +
        '<div style="display:flex;gap:20px;padding:10px 12px;border:1px solid var(--border);border-radius:7px;background:#fff;">' +
          '<label style="display:flex;align-items:center;gap:8px;font-weight:600;color:var(--text);margin-bottom:0;cursor:pointer;"><input type="checkbox" id="fOrdMedPesagem" style="width:auto;"'+(o.medicaoPesagem?' checked':'')+'> Pesagem (toneladas)</label>' +
          '<label style="display:flex;align-items:center;gap:8px;font-weight:600;color:var(--text);margin-bottom:0;cursor:pointer;"><input type="checkbox" id="fOrdMedHora" style="width:auto;"'+(o.medicaoHora?' checked':'')+'> Hora</label>' +
          '<label style="display:flex;align-items:center;gap:8px;font-weight:600;color:var(--text);margin-bottom:0;cursor:pointer;"><input type="checkbox" id="fOrdMedVerba" style="width:auto;"'+(o.medicaoVerba?' checked':'')+'> Verba (evento)</label>' +
        '</div>' +
        '<div id="ordMedicaoError"></div>' +
        '<div class="shared-note" style="display:block;margin-top:8px;">Marque aqui só os tipos de medição desta ordem. O código, a descrição, o apelido, a meta mensal e o valor de cada serviço são cadastrados em <b>Cadastro → Tarifas</b> — é de lá que Produção e Medição leem tudo.</div>' +
      '</div>' +
      '<div class="modal-actions">' +
        '<button class="btn btn-outline" id="ordCancel">Cancelar</button>' +
        '<button class="btn btn-primary" id="ordSave">Salvar</button>' +
      '</div>'
    );
    // O nome de um Local já costuma vir no formato "Nome - Nome - Número"
    // (ex.: "AMT - Sucata - 500010") — se ainda não preencheram Número/Nome
    // da ordem na mão, aproveita e sugere os dois a partir do Local
    // escolhido (a pessoa pode ajustar/apagar à vontade depois).
    document.getElementById('fOrdLocal').addEventListener('change', function(){
      if(isEdit) return;
      var partes = this.value.split(' - ').map(function(p){ return p.trim(); }).filter(Boolean);
      if(partes.length < 2) return;
      var possivelNumero = partes[partes.length-1];
      if(!/^\d+$/.test(possivelNumero)) return; // só sugere se o último pedaço for mesmo um número
      var campoNumero = document.getElementById('fOrdNumero');
      var campoNome = document.getElementById('fOrdNome');
      if(!campoNumero.value.trim()) campoNumero.value = possivelNumero;
      if(!campoNome.value.trim()) campoNome.value = partes.slice(0,-1).join(' - ');
    });
    document.getElementById('fOrdCliente').addEventListener('change', function(){
      var isNovo = this.value==='__novo__';
      document.getElementById('novoClienteWrap').style.display = isNovo ? 'block' : 'none';
      if(isNovo){
        document.getElementById('novoClienteInput').focus();
      } else {
        var numeroAtual = CLIENTE_NUMEROS[this.value];
        document.getElementById('clienteNumeroWrap').innerHTML = numeroAtual
          ? '<div class="muted-tag">Nº cliente: '+esc(numeroAtual)+' (gerencie em Cadastro → Clientes)</div>'
          : '<div class="muted-tag">Cliente sem número cadastrado ainda — gerencie em Cadastro → Clientes.</div>';
      }
    });
    document.getElementById('novoClienteBtn').addEventListener('click', async function(){
      var nome = document.getElementById('novoClienteInput').value.trim();
      var numero = document.getElementById('novoClienteNumero').value.trim();
      if(!nome) return;
      await addNovoCliente(nome, numero);
      var sel = document.getElementById('fOrdCliente');
      sel.innerHTML = addNovoClienteOption(optionsList(CLIENTES, nome));
      document.getElementById('novoClienteWrap').style.display = 'none';
      document.getElementById('clienteNumeroWrap').style.display = 'block';
      document.getElementById('clienteNumeroInput').value = numero;
      toast('Cliente adicionado.');
    });
    document.getElementById('ordCancel').onclick = closeModal;
    document.getElementById('ordSave').onclick = async function(){
      var nome = normalizarEspacos(document.getElementById('fOrdNome').value);
      var numero = normalizarEspacos(document.getElementById('fOrdNumero').value);
      var cliente = document.getElementById('fOrdCliente').value;
      var local = normalizarEspacos(document.getElementById('fOrdLocal').value);
      var vendedor = normalizarTituloCase(document.getElementById('fOrdVendedor').value);
      var modeloContrato = normalizarTituloCase(document.getElementById('fOrdModelo').value);
      var cnpj = normalizarEspacos(document.getElementById('fOrdCnpj').value);
      var vigenciaContratoInicio = document.getElementById('fOrdVigenciaInicio').value || '';
      var vigenciaContratoFim = document.getElementById('fOrdVigenciaFim').value || '';
      var medicaoPesagem = document.getElementById('fOrdMedPesagem').checked;
      var medicaoHora = document.getElementById('fOrdMedHora').checked;
      var medicaoVerba = document.getElementById('fOrdMedVerba').checked;
      var errBox = document.getElementById('ordFormError');
      if(cliente==='__novo__'){ errBox.innerHTML = '<div class="form-error">Adicione o novo cliente antes de salvar, ou selecione um cliente existente.</div>'; return; }
      if(!nome){ errBox.innerHTML = '<div class="form-error">Informe o nome da ordem.</div>'; return; }
      if(!medicaoPesagem && !medicaoHora && !medicaoVerba){ errBox.innerHTML = '<div class="form-error">Selecione ao menos um tipo de medição (Pesagem, Hora e/ou Verba).</div>'; return; }
      var dup = state.ordens.some(function(x){ return x.nome.toLowerCase()===nome.toLowerCase() && x.cliente===cliente && (!isEdit || x.id!==o.id); });
      if(dup){ errBox.innerHTML = '<div class="form-error">Já existe uma ordem com esse nome para este cliente.</div>'; return; }
      var dupNumero = numero && state.ordens.some(function(x){ return (x.numero||'').trim()===numero.trim() && (!isEdit || x.id!==o.id); });
      if(dupNumero){ errBox.innerHTML = '<div class="form-error">Já existe uma ordem cadastrada com esse número (Nº '+esc(numero)+'). Verifique se não é duplicidade antes de salvar.</div>'; return; }
      var record = { id: isEdit ? o.id : uid(), nome: nome, numero: numero, cliente: cliente, local: local, vendedor: vendedor, modeloContrato: modeloContrato, cnpj: cnpj, vigenciaContratoInicio: vigenciaContratoInicio, vigenciaContratoFim: vigenciaContratoFim, medicaoPesagem: medicaoPesagem, medicaoHora: medicaoHora, medicaoVerba: medicaoVerba, materiaisPesagem: (isEdit?o.materiaisPesagem:undefined), materiaisHora: (isEdit?o.materiaisHora:undefined), materiaisVerba: (isEdit?o.materiaisVerba:undefined) };
      if(isEdit){ state.ordens = state.ordens.map(function(x){ return x.id===record.id ? record : x; }); }
      else { state.ordens.push(record); }
      var ok = await saveList('ordens_v9', state.ordens);
      closeModal();
      toast(ok ? 'Ordem salva.' : 'Ordem salva localmente — houve um problema ao sincronizar.');
      renderAll();
    };
  }
  function deleteOrdem(id){
    var emUso = state.apropriacoes.some(function(a){ return a.ordemId===id; });
    if(emUso){
      confirmModal('Não é possível remover', 'Esta ordem possui lançamentos de apropriação vinculados e não pode ser removida.', function(){});
      return;
    }
    var ord = getOrdem(id);
    confirmModal('Remover ordem', 'Remover a ordem '+(ord?ord.nome:'')+'?', async function(){
      state.ordens = state.ordens.filter(function(x){ return x.id!==id; });
      await saveList('ordens_v9', state.ordens);
      toast('Ordem removida.');
      renderAll();
    });
  }

  /* ============ OPERADOR CRUD ============ */
  function getOperador(id){ for(var i=0;i<state.operadores.length;i++){ if(state.operadores[i].id===id) return state.operadores[i]; } return null; }

  function openOperadorModal(existing){
    var isEdit = !!existing;
    var op = existing || {matricula:'', nome:'', cargo:'', usuario:''};
    // Login do tablet (usuário/senha) agora aparece tanto pra criar quanto pra
    // editar, e faz parte do mesmo botão "Salvar" — antes só existia editando
    // um operador já salvo, com um botão à parte ("Definir login"), o que além
    // de exigir salvar duas vezes também escondia se o operador JÁ tinha um
    // usuário definido (o campo sempre abria em branco). Agora, se já tiver
    // login, o usuário atual vem preenchido — dá pra ver quem já está "dono"
    // daquele usuário sem precisar adivinhar.
    openModal(
      '<h3>'+(isEdit?'Editar operador':'Novo operador')+'</h3>' +
      '<div id="operFormError"></div>' +
      '<div class="field-row">' +
        '<div class="field"><label>Matrícula</label><input type="text" id="fOperMatricula" value="'+esc(op.matricula||'')+'" placeholder="Ex: 10639"></div>' +
        '<div class="field"><label>Nome</label><input type="text" id="fOperNome" value="'+esc(op.nome)+'" placeholder="Nome completo"></div>' +
      '</div>' +
      '<div class="field"><label>Cargo</label><input type="text" id="fOperCargo" value="'+esc(op.cargo||'')+'" placeholder="Ex: Operador Máquinas Móveis III"></div>' +
      (state.perfil==='admin' ? (
      '<div class="field" style="border-top:1px solid var(--border);padding-top:12px;margin-top:4px;">' +
        '<label>Login do tablet (Parte Diária)</label>' +
        '<div id="operSenhaWrap" style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;">' +
          '<div class="field" style="margin-bottom:0;"><label style="font-weight:400;font-size:11.5px;">Usuário</label><input type="text" id="fOperUsuario" value="'+esc(op.usuario||'')+'" placeholder="ex: joao.silva" style="width:160px;"></div>' +
          '<div class="field" style="margin-bottom:0;"><label style="font-weight:400;font-size:11.5px;">'+(op.usuario?'Nova senha':'Senha')+'</label><input type="password" id="fOperSenha" placeholder="Mínimo 6 caracteres" style="width:160px;"></div>' +
        '</div>' +
        '<div class="shared-note" style="display:block;margin-top:6px;">'+(op.usuario ?
          'Este operador já tem login com o usuário acima. Deixe a senha em branco se não quiser trocá-la agora.' :
          'Preencha usuário e senha aqui pra já criar o login do tablet junto — ou deixe em branco e defina depois, editando o operador.'
        )+'</div>' +
      '</div>') : '') +
      '<div class="modal-actions">' +
        '<button class="btn btn-outline" id="operCancel">Cancelar</button>' +
        '<button class="btn btn-primary" id="operSave">Salvar</button>' +
      '</div>'
    );
    document.getElementById('operCancel').onclick = closeModal;
    document.getElementById('operSave').onclick = async function(){
      var nome = capitalizarNomePessoa(document.getElementById('fOperNome').value);
      var matricula = normalizarEspacos(document.getElementById('fOperMatricula').value);
      var errBox = document.getElementById('operFormError');
      if(!nome){ errBox.innerHTML = '<div class="form-error">Informe o nome do operador.</div>'; return; }
      var dup = state.operadores.some(function(x){ return x.nome.toLowerCase()===nome.toLowerCase() && (!isEdit || x.id!==op.id); });
      if(dup){ errBox.innerHTML = '<div class="form-error">Já existe um operador cadastrado com esse nome.</div>'; return; }
      var fUsuario = document.getElementById('fOperUsuario');
      var fSenha = document.getElementById('fOperSenha');
      var usuarioLogin = fUsuario ? normalizarEspacos(fUsuario.value).toLowerCase() : '';
      var senhaLogin = fSenha ? fSenha.value : '';
      if(senhaLogin && senhaLogin.length < 6){ errBox.innerHTML = '<div class="form-error">A senha do login do tablet precisa ter pelo menos 6 caracteres.</div>'; return; }
      var record = {
        id: isEdit ? op.id : uid(), matricula: matricula, nome: nome,
        cargo: normalizarEspacos(document.getElementById('fOperCargo').value),
        ativo: true
      };
      if(isEdit){ state.operadores = state.operadores.map(function(x){ return x.id===record.id ? Object.assign({}, x, record) : x; }); }
      else { state.operadores.push(record); }
      var ok = await saveList('operadores_v4', state.operadores);
      var avisoLogin = '';
      if(ok && senhaLogin){
        // Só depois do saveList é que o operador (inclusive um recém-criado)
        // tem o id de verdade do SharePoint — saveList recarrega a lista fresca
        // pra equipamentos/operadores/locais logo depois de salvar (ver
        // comentário lá), então dá pra achar o registro salvo por nome aqui.
        var operadorSalvo = state.operadores.filter(function(x){ return x.nome.toLowerCase()===nome.toLowerCase(); })[0];
        if(operadorSalvo){
          try{
            await ctrlFetch('/api/ctrl/operadores/'+operadorSalvo.id+'/senha', { method:'PATCH', headers: ctrlCabecalhos(), body: JSON.stringify({ usuario: usuarioLogin, senha: senhaLogin }) });
            operadorSalvo.usuario = usuarioLogin || operadorSalvo.usuario;
            avisoLogin = ' Login do tablet definido/atualizado.';
          }catch(e){ avisoLogin = ' Porém não foi possível definir o login do tablet: '+e.message; }
        }
      }
      closeModal();
      toast((ok ? 'Operador salvo.' : 'Operador salvo localmente — houve um problema ao sincronizar.') + avisoLogin);
      renderOperadoresTab();
    };
  }

  // "Remover" um operador NUNCA apaga o registro de verdade — o backend só
  // marca Ativo="Não" na lista compartilhada do SharePoint (pra preservar
  // histórico/login já feito em nome dele, mesmo padrão que o Portal usa).
  // Antes disso não tinha nenhuma pista visual: o operador "removido" ficava
  // exatamente igual na lista, e a pessoa achava que a exclusão não tinha
  // funcionado. Agora ele aparece marcado como "(desativado)" e o botão vira
  // "Reativar" — dá pra desfazer, e fica claro o que realmente aconteceu.
  function deleteOperador(id){
    var op = getOperador(id);
    confirmModal('Remover operador', 'Remover '+(op?op.nome:'')+' do cadastro? Ele deixa de aparecer disponível para novos lançamentos e o login do tablet dele (se tiver) para de funcionar — mas o histórico de apropriações já feitas é mantido, e dá pra reativar depois.', async function(){
      state.operadores = state.operadores.filter(function(x){ return x.id!==id; });
      var ok = await saveList('operadores_v4', state.operadores);
      toast(ok ? 'Operador removido — ele fica marcado como desativado e some das listas de seleção, mas continua no cadastro pra manter o histórico.' : 'Não foi possível remover agora. Verifique a conexão e tente de novo.');
      renderOperadoresTab();
    });
  }

  function reativarOperador(id){
    var op = getOperador(id);
    confirmModal('Reativar operador', 'Reativar '+(op?op.nome:'')+'? Ele volta a aparecer disponível para novos lançamentos e o login do tablet dele (se já tinha um) volta a funcionar.', async function(){
      state.operadores = state.operadores.map(function(x){ return x.id===id ? Object.assign({}, x, {ativo:true}) : x; });
      var ok = await saveList('operadores_v4', state.operadores);
      toast(ok ? 'Operador reativado.' : 'Não foi possível reativar agora. Verifique a conexão e tente de novo.');
      renderOperadoresTab();
    });
  }

  function valoresColunaOperador(o){ return { matricula: o.matricula||'—', nome: o.nome||'—', cargo: o.cargo||'—' }; }
  function renderOperadoresTab(){
    var busca = document.getElementById('filtroOperadorBusca').value.trim().toLowerCase();
    var list = state.operadores.filter(function(o){
      if(busca && o.nome.toLowerCase().indexOf(busca)===-1) return false;
      return true;
    }).sort(function(a,b){
      // Desativados vão pro fim da lista, pra não misturar com quem está em uso.
      if((a.ativo===false) !== (b.ativo===false)) return a.ativo===false ? 1 : -1;
      return a.nome.localeCompare(b.nome,'pt-BR');
    });
    list = aplicaColFiltrosTabela('operadores', list);
    marcarBotoesFiltroAtivos('operadores');
    var body = document.getElementById('operadoresBody');
    if(list.length===0){
      body.innerHTML = '<tr class="empty-row"><td colspan="5">Nenhum operador encontrado.</td></tr>';
      return;
    }
    body.innerHTML = list.map(function(o){
      var inativo = o.ativo===false;
      return '<tr'+(inativo?' style="opacity:.55;"':'')+'><td><span class="plate">'+esc(o.matricula||'—')+'</span></td><td>'+esc(o.nome)+
        (inativo?' <span style="color:var(--danger);font-weight:700;font-size:11px;">(desativado)</span>':'')+'</td>' +
        '<td>'+esc(o.cargo||'—')+'</td>' +
        '<td>'+(o.usuario ? esc(o.usuario) : '<span class="muted-tag" style="opacity:.7;">sem login</span>')+'</td>' +
        '<td><button class="btn btn-ghost btn-sm" data-edit-oper="'+o.id+'" title="Editar"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg></button>' +
        (inativo ?
          '<button class="btn btn-outline btn-sm" data-reativar-oper="'+o.id+'" title="Reativar" style="margin-left:4px;">Reativar</button>' :
          '<button class="btn btn-danger-ghost btn-sm" data-del-oper="'+o.id+'" title="Remover"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg></button>'
        ) + '</td></tr>';
    }).join('');
    body.querySelectorAll('[data-edit-oper]').forEach(function(btn){ btn.onclick = function(){ openOperadorModal(getOperador(btn.getAttribute('data-edit-oper'))); }; });
    body.querySelectorAll('[data-del-oper]').forEach(function(btn){ btn.onclick = function(){ deleteOperador(btn.getAttribute('data-del-oper')); }; });
    body.querySelectorAll('[data-reativar-oper]').forEach(function(btn){ btn.onclick = function(){ reativarOperador(btn.getAttribute('data-reativar-oper')); }; });
  }

  /* ============ APROPRIAÇÃO FORM ============ */
  function paradaHoras(p){
    var h = diffHoras(p.inicio, p.termino);
    return h===null ? 0 : Math.round(h*100)/100;
  }
  // Detecta parada com início fora do turno do operador (antes da entrada, ou depois da saída
  // quando já preenchida). Usa diffHoras (que já lida com turno noturno virando o dia) em vez de
  // comparar os horários como texto — senão um turno das 22h às 06h marcaria toda parada da
  // madrugada como "antes da entrada" por engano.
  function paradaAntesDaEntrada(entrada, saida, paradaInicio){
    if(!entrada || !paradaInicio) return false;
    var elapsedParada = diffHoras(entrada, paradaInicio);
    if(elapsedParada===null) return false;
    var limite = saida ? diffHoras(entrada, saida) : 16; // sem saída ainda: teto generoso de 16h de turno
    if(limite===null) limite = 16;
    return elapsedParada > limite;
  }
  // Categorias pra escolha em 2 etapas: 1ª Motivo (a categoria), 2ª Serviço (a descrição
  // específica cadastrada dentro dela). "Manutenção Corretiva" pega tudo que já existia antes
  // (tipo Manutenção, sem ser preventiva).
  var CATEGORIAS_PARADA = ['Manutenção Corretiva', 'Manutenção Preventiva', 'Manutenção de Inspeção', 'Segurança', 'Operacional', 'Alimentação'];
  function categoriaDoMotivo(descricao){
    var m = state.motivosParada.filter(function(x){ return x.descricao===descricao; })[0];
    return m ? (m.categoria || '') : '';
  }
  function motivosDaCategoria(categoria){
    return state.motivosParada.filter(function(m){ return (m.categoria||'')===categoria; }).map(function(m){ return m.descricao; });
  }
  // Opções de Serviço (2ª etapa) dentro de uma categoria já escolhida — exclui as descrições que
  // são só o nome da própria categoria repetido (ex: "Manutenção Corretiva" cadastrada como seu
  // próprio serviço), que não fazem mais sentido como opção de Serviço já que a categoria já foi
  // escolhida na 1ª etapa. Não apaga esses cadastros (têm histórico real de horas por trás), só
  // tira da lista de opções pra novos lançamentos.
  function servicosDaCategoria(categoria){
    return motivosDaCategoria(categoria).filter(function(nome){ return nome!==categoria; });
  }
  // Opções de motivo restritas às 3 categorias de manutenção, agrupadas por categoria — usada na
  // confirmação manual de paradas de manutenção importadas de planilha sem tipo identificado.
  function opcoesMotivoManutencao(selected){
    return CATEGORIAS_PARADA.slice(0,3).map(function(cat){
      var motivos = motivosDaCategoria(cat);
      if(!motivos.length) return '';
      return '<optgroup label="'+esc(cat)+'">'+optionsList(motivos, selected)+'</optgroup>';
    }).join('');
  }

  function renderParadasEditor(){
    var el = document.getElementById('paradasEditor');
    if(!el) return;
    if(formParadas.length===0){
      el.innerHTML = '<div class="muted-tag" style="padding:4px 2px 8px 2px;">Nenhuma parada lançada.</div>';
      return;
    }
    el.innerHTML =
      formParadas.map(function(p, idx){
        var categoriaAtual = categoriaDoMotivo(p.motivo);
        return '<div class="parada-block">' +
          '<div class="field-row" style="margin-bottom:6px;">' +
            '<div class="field"><label>Motivo</label><select data-parada-categoria="'+idx+'">'+ '<option value="">Selecione o motivo…</option>' + optionsList(CATEGORIAS_PARADA, categoriaAtual) +'</select></div>' +
            '<div class="field"><label>Serviço</label><select data-parada-servico="'+idx+'">'+ (categoriaAtual ? optionsList(servicosDaCategoria(categoriaAtual), p.motivo) : '<option value="">Escolha o motivo primeiro…</option>') +'</select></div>' +
          '</div>' +
          '<div class="parada-tempos-row">' +
            '<div class="field"><label>Início</label><input type="time" value="'+(p.inicio||'')+'" data-parada-inicio="'+idx+'"></div>' +
            '<div class="field"><label>Término</label><input type="time" value="'+(p.termino||'')+'" data-parada-termino="'+idx+'"></div>' +
            '<div class="field" style="width:64px;"><label>Horas</label><span class="parada-horas" data-parada-horas-display="'+idx+'">'+brNum(p.horas,2)+'</span></div>' +
            '<button type="button" class="parada-remove" data-parada-remove="'+idx+'" title="Remover parada">×</button>' +
          '</div>' +
        '</div>';
      }).join('');
    el.querySelectorAll('[data-parada-categoria]').forEach(function(sel){
      sel.addEventListener('change', function(){
        var idx = +sel.getAttribute('data-parada-categoria');
        var categoria = sel.value;
        formParadas[idx].motivo = ''; // troca de motivo limpa o serviço específico escolhido antes
        var servicoSel = el.querySelector('[data-parada-servico="'+idx+'"]');
        servicoSel.innerHTML = categoria
          ? '<option value="">Selecione o serviço…</option>' + optionsList(servicosDaCategoria(categoria), '')
          : '<option value="">Escolha o motivo primeiro…</option>';
        updateConsolidacao();
      });
    });
    el.querySelectorAll('[data-parada-servico]').forEach(function(sel){
      sel.addEventListener('change', function(){
        var idx = +sel.getAttribute('data-parada-servico');
        formParadas[idx].motivo = sel.value;
        updateConsolidacao();
      });
    });
    function recompute(idx){
      var p = formParadas[idx];
      p.horas = paradaHoras(p);
      var disp = el.querySelector('[data-parada-horas-display="'+idx+'"]');
      if(disp) disp.textContent = brNum(p.horas,2);
      updateConsolidacao();
    }
    el.querySelectorAll('[data-parada-inicio]').forEach(function(inp){
      inp.addEventListener('input', function(){
        var idx = +inp.getAttribute('data-parada-inicio');
        formParadas[idx].inicio = inp.value;
        recompute(idx);
      });
    });
    el.querySelectorAll('[data-parada-termino]').forEach(function(inp){
      inp.addEventListener('input', function(){
        var idx = +inp.getAttribute('data-parada-termino');
        formParadas[idx].termino = inp.value;
        recompute(idx);
      });
    });
    el.querySelectorAll('[data-parada-remove]').forEach(function(btn){
      btn.onclick = function(){
        formParadas.splice(+btn.getAttribute('data-parada-remove'),1);
        renderParadasEditor();
        updateConsolidacao();
      };
    });
  }

  function updateConsolidacao(){
    var box = document.getElementById('consolBox');
    if(!box) return;
    var entrada = document.getElementById('apEntrada').value;
    var tipoIntervalo = document.getElementById('apTipoIntervalo').value;
    var intIni = document.getElementById('apIntIni').value;
    var intFim = document.getElementById('apIntFim').value;
    var saida = document.getElementById('apSaida').value;
    var hiRaw = document.getElementById('apHi').value;
    var hfRaw = document.getElementById('apHf').value;
    var hi = parseFloat(hiRaw);
    var hf = parseFloat(hfRaw);

    var warnEl = document.getElementById('apHorimetroWarn');
    if(warnEl){
      var avisos = [];
      if(hiRaw!=='' && hfRaw!=='' && !isNaN(hi) && !isNaN(hf) && hf < hi){
        avisos.push('Horímetro final não pode ser menor que o inicial.');
        document.getElementById('apHf').style.borderColor = 'var(--danger)';
      } else {
        document.getElementById('apHf').style.borderColor = '';
      }
      // Verifica se o horímetro inicial digitado é menor que o final do lançamento anterior do
      // mesmo equipamento — sinal de erro de digitação, já que o horímetro só sobe com o tempo.
      var equipTextoChk = document.getElementById('apEquip') ? document.getElementById('apEquip').value.trim() : '';
      var equipObjChk = equipTextoChk ? state.equipamentos.filter(function(e){ return equipLabel(e)===equipTextoChk; })[0] : null;
      var dataAtualChk = document.getElementById('apData') ? document.getElementById('apData').value : '';
      if(equipObjChk && dataAtualChk && hiRaw!=='' && !isNaN(hi)){
        var anterioresChk = state.apropriacoes.filter(function(a){
          return a.equipamentoId===equipObjChk.id && a.data <= dataAtualChk && a.id!==state.editingApropriacaoId;
        }).sort(function(a,b){ return a.data.localeCompare(b.data) || (a.entrada||'').localeCompare(b.entrada||''); });
        var ultimoAnteriorChk = anterioresChk[anterioresChk.length-1];
        if(ultimoAnteriorChk && typeof ultimoAnteriorChk.horimetroFinal==='number' && hi < ultimoAnteriorChk.horimetroFinal){
          avisos.push('O horímetro inicial ('+brNum(hi,1)+') está menor que o final do último lançamento desse equipamento em '+brDate(ultimoAnteriorChk.data)+' ('+brNum(ultimoAnteriorChk.horimetroFinal,1)+'). Confira se não houve erro de digitação.');
          document.getElementById('apHi').style.borderColor = 'var(--danger)';
        } else {
          document.getElementById('apHi').style.borderColor = '';
        }
      }
      var paradasEditorEl = document.getElementById('paradasEditor');
      formParadas.forEach(function(p, idx){
        var inicioEl = paradasEditorEl ? paradasEditorEl.querySelector('[data-parada-inicio="'+idx+'"]') : null;
        if(p.inicio && paradaAntesDaEntrada(entrada, saida, p.inicio)){
          avisos.push('Parada '+(idx+1)+': o início ('+esc(p.inicio)+') está fora do turno do operador ('+esc(entrada)+(saida?' às '+esc(saida):'')+'). Confira o horário digitado.');
          if(inicioEl) inicioEl.style.borderColor = 'var(--danger)';
        } else if(inicioEl){
          inicioEl.style.borderColor = '';
        }
      });
      warnEl.innerHTML = avisos.length ? avisos.map(function(a){ return '<div class="form-error" style="margin-top:-6px;">'+a+'</div>'; }).join('') : '';
    }

    var overnightEl = document.getElementById('apOvernightNote');
    if(overnightEl){
      var dataVal = document.getElementById('apData') ? document.getElementById('apData').value : '';
      if(entrada && saida && isOvernightShift(entrada, saida)){
        var dataFimVal = dataVal ? addDaysISO(dataVal, 1) : null;
        overnightEl.innerHTML = '<div class="muted-tag" style="margin-top:8px;color:#8A6A0E;">⤷ Turno vira o dia: entrada '+esc(entrada)+' ('+ (dataVal?brDate(dataVal):'—') +') · saída '+esc(saida)+' ('+ (dataFimVal?brDate(dataFimVal):'dia seguinte') +')</div>';
      } else {
        overnightEl.innerHTML = '';
      }
    }

    var horasOperador = computeHorasOperador(entrada, tipoIntervalo, intIni, intFim, saida);
    var horasHorimetro = (!isNaN(hi) && !isNaN(hf) && hf>=hi) ? Math.max(hf-hi,0) : null;
    var horasParada = formParadas.reduce(function(s,p){ return s+(p.horas||0); },0);

    var badgeEl = document.getElementById('apHProgBadge');
    if(badgeEl){
      badgeEl.textContent = horasOperador===null ? '—' : brNum(horasOperador,2).replace(',00','')+'h';
    }

    var linhaOperador = '<div class="consol-line"><span>Horas programadas</span><b>'+(horasOperador===null?'—':brNum(horasOperador,2))+'</b></div>';
    var linhaHorimetro = '<div class="consol-line"><span>Horas de horímetro</span><b>'+(horasHorimetro===null?'—':brNum(horasHorimetro,2))+'</b></div>';
    var linhaParada = '<div class="consol-line"><span>Horas de parada</span><b>'+brNum(horasParada,2)+'</b></div>';
    var linhaDiff = '';
    if(horasOperador!==null && horasHorimetro!==null){
      var diff = Math.round((horasOperador - horasHorimetro - horasParada)*100)/100;
      var cls = Math.abs(diff)<0.05 ? 'diff-ok' : (Math.abs(diff)<=1 ? 'diff-warn' : 'diff-bad');
      linhaDiff = '<div class="consol-line '+cls+'"><span>Diferença não apontada</span><b>'+brNum(diff,2)+'</b></div>';
    }
    var linhaValor = '';
    box.innerHTML = linhaOperador + linhaHorimetro + linhaParada + linhaDiff + linhaValor;
  }

  /* ============ LANÇAR APROPRIAÇÃO EM ETAPAS ============
     O identificador do lançamento passou a ser Operador + Data (não existe mais Número da Parte
     Diária). Perfil Campo cujo nome de login bate com um Operador cadastrado nem vê a tela de
     escolha: o sistema já procura sozinho se existe um lançamento (rascunho ou concluído) de hoje
     pra ele. Escritório/Administrador (ou Campo sem operador identificado) continuam com a tela de
     escolha manual, buscando por Operador + Data em vez de um número. */
  // Ignora maiúscula/minúscula, acentos e espaços duplicados — nomes digitados em cadastros
  // diferentes (Usuários x Operadores) raramente batem char-a-char.
  function normalizarNomeComparacao(s){
    return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
  }
  function operadorDoLoginAtual(){
    if(state.perfil!=='campo' || !state.usuarioLogado || !state.usuarioLogado.nome) return null;
    var alvo = normalizarNomeComparacao(state.usuarioLogado.nome);
    return state.operadores.filter(function(o){ return normalizarNomeComparacao(o.nome)===alvo; })[0] || null;
  }
  function horaAtualHHMM(){
    var d = new Date();
    return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
  }
  function renderApropriacaoEntry(){
    var wrap = document.getElementById('apropriacaoFormWrap');
    var operadorAuto = operadorDoLoginAtual();
    if(operadorAuto){
      var hoje = todayISO();
      var rascunhosHoje = state.apropriacoesRascunhos.filter(function(a){ return a.operador===operadorAuto.nome && a.data===hoje; });
      var concluidosHoje = state.apropriacoes.filter(function(a){ return a.operador===operadorAuto.nome && a.data===hoje; });
      // Nada lançado ainda: vai direto pro formulário, como sempre foi.
      if(rascunhosHoje.length===0 && concluidosHoje.length===0){ renderApropriacaoForm(); return; }
      // Caso de longe mais comum: um lançamento em andamento e nada concluído. Abre nele
      // direto, sem passo extra — é o caminho rápido do dia a dia do operador.
      if(rascunhosHoje.length===1 && concluidosHoje.length===0){ renderApropriacaoForm(rascunhosHoje[0], true); return; }
      // Operador trocou de equipamento no dia: mostra o que já existe e deixa continuar um
      // deles ou abrir outro. Corrigir lançamento concluído continua sendo da Controladoria.
      var linhasDoDia = rascunhosHoje.map(function(a){
        var eqR = getEquip(a.equipamentoId);
        return '<div class="consol-line" style="border-top:1px solid var(--border);padding-top:8px;margin-top:8px;">' +
          '<span><b>'+esc(eqR?eqR.codigo:'—')+'</b> · em andamento (rodada '+(a.rodadas||1)+' de até 4)</span>' +
          '<b><button type="button" class="btn btn-outline btn-sm ap-hoje-continuar" data-id="'+esc(a.id)+'">Continuar</button></b>' +
        '</div>';
      }).concat(concluidosHoje.map(function(a){
        var eqC = getEquip(a.equipamentoId);
        return '<div class="consol-line" style="border-top:1px solid var(--border);padding-top:8px;margin-top:8px;">' +
          '<span><b>'+esc(eqC?eqC.codigo:'—')+'</b> · concluído</span><b style="color:var(--text-muted);">✓</b>' +
        '</div>';
      })).join('');
      wrap.innerHTML =
        '<div class="consol-box" style="margin-bottom:14px;">' +
          '<div class="consol-line"><span><b>Seus lançamentos de '+brDate(hoje)+'</b></span></div>' + linhasDoDia +
        '</div>' +
        '<button type="button" class="btn btn-primary" id="apHojeNovoBtn">Lançar em outro equipamento</button>' +
        '<div style="font-size:12px;color:var(--text-muted);margin-top:8px;">Para corrigir um lançamento já concluído, peça à Controladoria.</div>';
      wrap.querySelectorAll('.ap-hoje-continuar').forEach(function(btn){
        btn.addEventListener('click', function(){
          var alvo = rascunhosHoje.filter(function(x){ return x.id===btn.getAttribute('data-id'); })[0];
          if(alvo) renderApropriacaoForm(alvo, true);
        });
      });
      document.getElementById('apHojeNovoBtn').addEventListener('click', function(){ renderApropriacaoForm(); });
      return;
    }
    function noEscopoPerfil(a){
      var clienteRestrito = (state.perfil==='campo' && state.operadorClienteRestrito) ? state.operadorClienteRestrito : null;
      var restrito = (state.perfil==='campo' && state.operadorOrdemId && !clienteRestrito);
      if(clienteRestrito){
        var ord = getOrdem(a.ordemId);
        if(!ord || ord.cliente!==clienteRestrito) return false;
      } else if(restrito && a.ordemId!==state.operadorOrdemId){
        return false;
      }
      return true;
    }
    wrap.innerHTML =
      '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px;">' +
        '<button type="button" class="btn btn-primary" id="apEntryNovoBtn">Iniciar novo lançamento</button>' +
        '<button type="button" class="btn btn-outline" id="apEntryContinuarBtn">Continuar lançamento</button>' +
      '</div>' +
      '<div id="apEntryContinuarBox" style="display:none;max-width:360px;">' +
        '<div class="field"><label>Operador</label><input type="text" id="apEntryBuscaOperador" list="datalistEntryOperadores" placeholder="Nome ou matrícula"><datalist id="datalistEntryOperadores">'+state.operadores.map(function(o){ return '<option value="'+esc(o.nome)+'">'; }).join('')+'</datalist></div>' +
        '<div class="field"><label>Data</label><input type="date" id="apEntryBuscaData" value="'+todayISO()+'"></div>' +
        '<button type="button" class="btn btn-outline" id="apEntryBuscarBtn">Buscar</button>' +
        '<div id="apEntryBuscaError" style="margin-top:8px;"></div>' +
      '</div>';
    document.getElementById('apEntryNovoBtn').addEventListener('click', function(){ renderApropriacaoForm(); });
    document.getElementById('apEntryContinuarBtn').addEventListener('click', function(){
      document.getElementById('apEntryContinuarBox').style.display = 'block';
      document.getElementById('apEntryBuscaOperador').focus();
    });
    function buscar(){
      var errBox = document.getElementById('apEntryBuscaError');
      errBox.innerHTML = '';
      var operadorTexto = normalizarEspacos(document.getElementById('apEntryBuscaOperador').value);
      var data = document.getElementById('apEntryBuscaData').value;
      if(!operadorTexto){ errBox.innerHTML = '<div class="form-error">Informe o operador.</div>'; return; }
      if(!data){ errBox.innerHTML = '<div class="form-error">Informe a data.</div>'; return; }
      var operadorObj = state.operadores.filter(function(o){
        return o.nome.toLowerCase()===operadorTexto.toLowerCase() || (o.matricula && o.matricula.toLowerCase()===operadorTexto.toLowerCase());
      })[0];
      var nomeAlvo = operadorObj ? operadorObj.nome : operadorTexto;
      var achados = state.apropriacoesRascunhos.filter(function(a){ return a.operador===nomeAlvo && a.data===data && noEscopoPerfil(a); })
        .map(function(a){ return {reg:a, rascunho:true}; })
        .concat(state.apropriacoes.filter(function(a){ return a.operador===nomeAlvo && a.data===data && noEscopoPerfil(a); })
        .map(function(a){ return {reg:a, rascunho:false}; }));
      if(achados.length===1){ renderApropriacaoForm(achados[0].reg, achados[0].rascunho); return; }
      if(achados.length>1){
        // Mesmo operador, mesmo dia, equipamentos diferentes — precisa escolher qual abrir.
        errBox.innerHTML = '<div style="font-size:12.5px;margin-bottom:6px;">Foram encontrados '+achados.length+' lançamentos nessa data. Escolha qual abrir:</div>' +
          achados.map(function(item, i){
            var eqB = getEquip(item.reg.equipamentoId);
            return '<button type="button" class="btn btn-outline btn-sm ap-busca-escolher" data-i="'+i+'" style="display:block;width:100%;text-align:left;margin-bottom:6px;">' +
              esc(eqB?eqB.codigo:'—')+' · '+(item.rascunho?'em andamento':'concluído')+'</button>';
          }).join('');
        errBox.querySelectorAll('.ap-busca-escolher').forEach(function(btn){
          btn.addEventListener('click', function(){
            var item = achados[parseInt(btn.getAttribute('data-i'),10)];
            if(item) renderApropriacaoForm(item.reg, item.rascunho);
          });
        });
        return;
      }
      errBox.innerHTML = '<div class="form-error">Nenhum lançamento encontrado para esse operador nessa data. Confira os dados ou inicie um novo lançamento.</div>';
    }
    document.getElementById('apEntryBuscarBtn').addEventListener('click', buscar);
    document.getElementById('apEntryBuscaOperador').addEventListener('keydown', function(ev){ if(ev.key==='Enter'){ ev.preventDefault(); buscar(); } });
  }

  function renderApBannerEdicao(editRecord, isRascunho){
    var texto;
    if(isRascunho){
      var rodadaAtual = (editRecord.rodadas||0)+1;
      texto = 'Continuando lançamento em andamento de '+esc(editRecord.operador||'')+' — '+brDate(editRecord.data)+' — rodada '+rodadaAtual+' de até 4.';
      if((editRecord.rodadas||0)>=4) texto += ' <b>Esta é a última rodada permitida — finalize preenchendo Horímetro final e Saída.</b>';
    } else {
      texto = 'Editando lançamento de '+brDate(editRecord.data);
    }
    return '<div class="consol-box" style="background:#FFF3CD;border-color:#F1DDA0;margin-bottom:14px;"><div class="consol-line"><span>'+texto+'</span><b><button type="button" class="btn-ghost" id="cancelarEdicaoBtn" style="padding:2px 6px;">Cancelar edição</button></b></div></div>';
  }

  function renderApropriacaoForm(editRecord, isRascunho){
    var wrap = document.getElementById('apropriacaoFormWrap');
    if(state.equipamentos.length===0 || state.ordens.length===0){
      var falta = state.equipamentos.length===0 ? 'um equipamento' : 'uma ordem';
      wrap.innerHTML = '<div class="empty-state"><div class="big">Cadastro incompleto</div>Cadastre pelo menos '+falta+' antes de lançar apropriações.</div>';
      return;
    }
    state.editingApropriacaoId = editRecord && !isRascunho ? editRecord.id : null;
    state.editingRascunhoId = editRecord && isRascunho ? editRecord.id : null;
    formParadas = editRecord ? JSON.parse(JSON.stringify(editRecord.paradas||[])) : [];
    // Linha do tempo do lançamento em tempo real (modo operador simplificado, ver
    // modoOperadorSimplificado abaixo) — cada evento é {tipo:'atividade'|'parada',
    // situacao (só atividade), motivo (só parada), horimetroIni, horimetroFim,
    // inicio, fim}. Guardada à parte de formParadas/horários, que continuam sendo
    // a "fonte da verdade" pros cálculos — a linha do tempo só existe pra pilotar
    // esses campos e pra poder retomar um rascunho em andamento do jeito que a
    // pessoa parou.
    var apEventos = editRecord ? JSON.parse(JSON.stringify(editRecord.timelineEventos||[])) : [];
    var apTlTimerId = null; // contador ao vivo do evento em aberto (linha do tempo) — ver renderApTimeline
    var equipamentosOrdenados = state.equipamentos.slice().sort(function(a,b){ return a.codigo.localeCompare(b.codigo,'pt-BR'); });
    var ordensOrdenadas = state.ordens.slice().sort(function(a,b){
      var c = a.cliente.localeCompare(b.cliente,'pt-BR');
      return c!==0 ? c : a.nome.localeCompare(b.nome,'pt-BR');
    });
    var clienteRestrito = (state.perfil==='campo' && state.operadorClienteRestrito) ? state.operadorClienteRestrito : null;
    var restringirOrdem = (state.perfil==='campo' && state.operadorOrdemId && !clienteRestrito);
    if(clienteRestrito){
      ordensOrdenadas = ordensOrdenadas.filter(function(o){ return o.cliente===clienteRestrito; });
    } else if(restringirOrdem){
      ordensOrdenadas = ordensOrdenadas.filter(function(o){ return o.id===state.operadorOrdemId; });
    }
    // Campo só preenche Data/Entrada/Intervalo/Saída pelas automações (Escala/Turno, "Iniciar meu
    // turno", Saída ao sair do Horímetro final) — não pode digitar direto nesses campos. Se precisar
    // corrigir um horário/data, quem faz é o Escritório/Administrador (isControladoriaLevel()).
    var travarHorarios = !isControladoriaLevel();
    var operadorAuto = operadorDoLoginAtual();
    // Só trava o campo quando é uma apropriação do próprio operador (nova, ou uma que já é dele) —
    // nunca quando ele está editando o lançamento de outro colega (ex: via Histórico).
    var operadorTravado = !!operadorAuto && (!editRecord || editRecord.operador===operadorAuto.nome);
    // Modo simplificado (tablet): o próprio operador lançando o dia dele, em tempo
    // real — troca os campos de horário/horímetro por uma "linha do tempo" com
    // Iniciar/Adicionar parada/Finalizar, parecido com a Parte Diária antiga.
    // Escritório/Administrador (ou alguém editando o lançamento de outra pessoa)
    // continuam vendo o formulário de sempre, com todos os campos abertos.
    var modoOperadorSimplificado = travarHorarios && operadorTravado;
    // Texto usado no campo "Descrição Ordem" e em todo lugar que precisa reconhecer esse texto de
    // volta (auto-preenchimento, seleção de tarifa, rascunho da linha do tempo). No tablet mostra
    // só o Local/Obra (igual o Checklist); fora dele, o nome completo da Ordem com o cliente.
    var ordemLabelAtual = modoOperadorSimplificado ? ordemLocalLabel : ordemDescricao;
    var equipValorInicial = editRecord ? equipLabel(getEquip(editRecord.equipamentoId)) : equipLabel(equipamentosOrdenados[0]);
    var ordemValorInicial = editRecord ? ordemLabelAtual(getOrdem(editRecord.ordemId)) : (restringirOrdem && ordensOrdenadas[0] ? ordemLabelAtual(ordensOrdenadas[0]) : '');
    var ordemNumeroValorInicial = editRecord ? (getOrdem(editRecord.ordemId)||{}).numero||'' : (restringirOrdem && ordensOrdenadas[0] ? (ordensOrdenadas[0].numero||'') : '');
    var nClienteValorInicial = editRecord ? (CLIENTE_NUMEROS[(getOrdem(editRecord.ordemId)||{}).cliente]||'') : (clienteRestrito ? (CLIENTE_NUMEROS[clienteRestrito]||'') : (restringirOrdem && ordensOrdenadas[0] ? (CLIENTE_NUMEROS[ordensOrdenadas[0].cliente]||'') : ''));

    wrap.innerHTML =
      (editRecord ? renderApBannerEdicao(editRecord, isRascunho) : '') +
      '<div class="form-section form-section-ident">' +
        '<div class="form-section-title"><span class="dot"></span>Identificação</div>' +
        '<div class="field"><label>Equipamento</label><div style="display:flex;align-items:center;gap:10px;"><div id="apEquipFoto" style="width:40px;height:40px;flex-shrink:0;border-radius:8px;background:#eef1ee;display:flex;align-items:center;justify-content:center;font-size:18px;overflow:hidden;">🚜</div><div class="combo-wrap" style="flex:1;"><input type="text" id="apEquip" autocomplete="off" value="'+esc(equipValorInicial)+'" placeholder="Digite ou selecione o código…"><div class="combo-list" id="apEquipList"></div></div></div><div id="apEquipError"></div></div>' +
        '<div class="field-row-ordem">' +
          '<div class="field"><label>Nº Ordem</label><div class="combo-wrap"><input type="text" id="apOrdemNumero" autocomplete="off" value="'+esc(ordemNumeroValorInicial)+'"'+(restringirOrdem?' readonly':'')+' placeholder="Nº…"><div class="combo-list" id="apOrdemNumeroList"></div></div></div>' +
          '<div class="field"><label>Descrição Ordem</label><div class="combo-wrap"><input type="text" id="apOrdem" autocomplete="off" value="'+esc(ordemValorInicial)+'"'+(restringirOrdem?' readonly':'')+' placeholder="Digite ou selecione a ordem…"><div class="combo-list" id="apOrdemList"></div></div>'+(restringirOrdem?('<div class="muted-tag" style="margin-top:4px;">Você está restrito a esta ordem.'+(state.operadorOrdemAdminLock?'':' <button type="button" class="btn-ghost" id="trocarOrdemBtn" style="padding:0;">Trocar ordem</button>')+'</div>'):(clienteRestrito?'<div class="muted-tag" style="margin-top:4px;">Você está restrito ao cliente '+esc(clienteRestrito)+' — escolha entre as ordens dele acima.</div>':''))+'<div id="apOrdemError"></div></div>' +
          '<div class="field"><label>Nº Cliente</label><div class="combo-wrap"><input type="text" id="apNCliente" autocomplete="off" value="'+esc(nClienteValorInicial)+'"'+((restringirOrdem||clienteRestrito)?' readonly':'')+' placeholder="Nº…"><div class="combo-list" id="apNClienteList"></div></div></div>' +
        '</div>' +
        '<div class="field-row">' +
          '<div class="field" style="flex:0 1 118px;"><label>Data</label><input type="date" id="apData" value="'+todayISO()+'"'+(travarHorarios?' readonly':'')+' style="padding:6px 8px;">'+(travarHorarios?'<div class="muted-tag" style="margin-top:4px;">Hoje. Pra alterar, peça ao Escritório.</div>':'')+'</div>' +
          '<div class="field" style="flex:1 1 160px;"><label>Operador (obrigatório)</label><input type="text" id="apOperador" list="datalistOperadores" '+(operadorTravado?'readonly value="'+esc(operadorAuto.nome)+'"':'')+' placeholder="Nome ou matrícula"><datalist id="datalistOperadores">'+state.operadores.map(function(o){ return '<option value="'+esc(o.nome)+'">'; }).join('')+'</datalist>'+(operadorTravado?'<div class="muted-tag" style="margin-top:4px;">Identificado pelo seu login.</div>':'')+'</div>' +
          '<div class="field" style="flex:1 1 140px;"><label>Escala</label><select id="apEscala"><option value="">Selecione a escala…</option>'+state.escalas.map(function(e){ return '<option value="'+e.key+'">'+esc(e.label)+'</option>'; }).join('')+'</select></div>' +
        '</div>' +
        '<div class="field" id="apTurnoWrap" style="display:none;"><label>Turno</label><select id="apTurno"></select></div>' +
      '</div>' +

      (modoOperadorSimplificado ? (
      '<div class="form-section form-section-timeline">' +
        '<div class="form-section-title"><span class="dot"></span>Lançamento do dia</div>' +
        '<div id="apTimelineWrap"></div>' +
      '</div>') : '') +

      '<div class="form-section form-section-operador"'+(modoOperadorSimplificado?' style="display:none"':'')+'>' +
        '<div class="form-section-title"><span class="dot"></span>Horas do operador</div>' +
        '<div class="operador-subheader">OPERADOR</div>' +
        '<div class="field-row-timeline-wrap">' +
          '<div class="field-row-timeline">' +
            '<div class="field"><label>Entrada</label><div style="display:flex;gap:4px;"><input type="time" id="apEntrada" value="07:00" style="flex:1;"'+(travarHorarios?' readonly':'')+'><button type="button" class="btn-ghost" id="apEntradaAgoraBtn" title="Preencher com a hora atual" style="padding:4px 8px;white-space:nowrap;">Iniciar meu turno</button></div></div>' +
            '<div class="field"><label>Intervalo</label><select id="apTipoIntervalo">'+optionsList(TIPOS_INTERVALO,'Almoço')+'</select></div>' +
            '<div class="field" id="apIntIniWrap"><label>Início intervalo</label><input type="time" id="apIntIni" value="12:00"'+(travarHorarios?' readonly':'')+'></div>' +
            '<div class="field" id="apIntFimWrap"><label>Fim intervalo</label><input type="time" id="apIntFim" value="13:00"'+(travarHorarios?' readonly':'')+'></div>' +
            '<div class="field"><label>Saída</label><input type="time" id="apSaida" value="17:00"'+(travarHorarios?' readonly':'')+'></div>' +
          '</div>' +
          '<div class="hprog-badge"><div class="hprog-label">H. Prog</div><div class="hprog-value" id="apHProgBadge">—</div></div>' +
        '</div>' +
        (travarHorarios?'<div class="muted-tag" style="margin-top:4px;">Horários preenchidos automaticamente (Escala/Turno, "Iniciar meu turno", Horímetro final). Para alterar manualmente, peça ao Escritório.</div>':'') +
        '<div id="apOvernightNote"></div>' +
      '</div>' +

      '<div class="form-section form-section-paradas"'+(modoOperadorSimplificado?' style="display:none"':'')+'>' +
        '<div class="form-section-title"><span class="dot"></span>Paradas</div>' +
        '<div id="paradasEditor"></div>' +
        '<button type="button" class="add-parada-btn" id="addParadaBtn">+ Adicionar parada</button>' +
      '</div>' +

      '<div class="form-section form-section-equip"'+(modoOperadorSimplificado?' style="display:none"':'')+'>' +
        '<div class="form-section-title"><span class="dot"></span>Horas do equipamento</div>' +
        '<div class="field-row">' +
          '<div class="field"><label>Horímetro inicial</label><input type="number" step="0.1" id="apHi" placeholder="0,0"></div>' +
          '<div class="field"><label>Horímetro final</label><input type="number" step="0.1" id="apHf" placeholder="0,0"></div>' +
          '<div class="field"><label>Iniciou em</label><select id="apSituacaoInicial">'+optionsList(['Operação','À disposição'], (editRecord&&editRecord.situacaoInicial)||'Operação')+'</select></div>' +
        '</div>' +
        '<div id="apHorimetroWarn"></div>' +
        '<div class="field-row" id="apServicoRow" style="display:none;">' +
          '<div class="field" id="apServicoWrap"><label>Serviço (tarifa da ordem)</label><select id="apServico"></select></div>' +
        '</div>' +
        '<div class="field-row" id="apServicoHoraRow" style="display:none;">' +
          '<div class="field" id="apServicoHoraWrap"><label>Serviço de Hora (tarifa da ordem)</label><select id="apServicoHora"></select></div>' +
        '</div>' +
      '</div>' +

      '<div class="consol-box" id="consolBox"></div>' +
      '<div id="apFormError"></div>' +
      '<button class="btn btn-primary" id="apSalvarBtn"'+(modoOperadorSimplificado?' style="display:none"':'')+'>'+(editRecord ? 'Salvar alterações' : 'Salvar lançamento')+'</button>';

    if(editRecord){
      document.getElementById('apEquip').value = equipLabel(getEquip(editRecord.equipamentoId));
      document.getElementById('apOrdem').value = ordemLabelAtual(getOrdem(editRecord.ordemId));
      document.getElementById('apOrdemNumero').value = (getOrdem(editRecord.ordemId)||{}).numero||'';
      document.getElementById('apData').value = editRecord.data;
      if(!operadorTravado) document.getElementById('apOperador').value = editRecord.operador || '';
      if(editRecord.escala) document.getElementById('apEscala').value = editRecord.escala;
      document.getElementById('cancelarEdicaoBtn').onclick = function(){ state.editingApropriacaoId = null; state.editingRascunhoId = null; renderApropriacaoEntry(); };
    }

    renderParadasEditor();
    updateConsolidacao();
    if(modoOperadorSimplificado) renderApTimeline();
    wireComboBox('apEquip', 'apEquipList', function(){ return equipamentosOrdenados.map(function(e){ return equipLabel(e); }); });
    wireOrdemTrio('apOrdemNumero', 'apOrdem', 'apNCliente', function(){ return ordensOrdenadas; }, function(){ atualizarServicoTarifa(); atualizarServicoHora(); }, ordemLabelAtual);
    // Mesma ideia do Checklist do tablet: ao escolher o equipamento, já busca a
    // foto dele, e — já que cada Ordem tem um "Local" (a mesma lista Locais do
    // Frota) — acha sozinho a ordem cujo Local bate com onde esse equipamento
    // está alocado agora, preenchendo Nº Ordem/Descrição/Nº Cliente sozinho.
    // Só entra em ação numa ordem nova (não em edição) e só se a pessoa ainda
    // não tiver escolhido uma ordem na mão — nunca atropela uma escolha manual.
    var cacheFotoEquipamentoAp = {};
    async function buscarFotoEquipamentoAp(codigo){
      var chave = String(codigo||'').toUpperCase();
      if(!chave) return null;
      if(cacheFotoEquipamentoAp[chave]!==undefined) return cacheFotoEquipamentoAp[chave];
      try{
        var resp = await ctrlFetch('/api/foto-equipamento/'+encodeURIComponent(chave), { headers: ctrlCabecalhos() });
        cacheFotoEquipamentoAp[chave] = resp.url || null;
      }catch(e){ cacheFotoEquipamentoAp[chave] = null; }
      return cacheFotoEquipamentoAp[chave];
    }
    function atualizarFotoEquipamentoAp(codigo){
      var el = document.getElementById('apEquipFoto');
      if(!el) return;
      el.innerHTML = '🚜';
      if(!codigo) return;
      buscarFotoEquipamentoAp(codigo).then(function(url){
        if(document.getElementById('apEquip').value.indexOf(codigo)!==0) return; // trocou de novo enquanto buscava
        el.innerHTML = url ? '<img src="'+esc(url)+'" style="width:100%;height:100%;object-fit:cover;" alt="">' : '🚜';
      });
    }
    // Pega o número da Ordem embutido no final do texto do Local (ex.: "AMT - Boleamento  500008"
    // -> "500008"). É esse número que a gente usa pra reconhecer a Ordem de verdade — mais
    // confiável do que tentar bater o texto do Local igualzinho entre o cadastro do equipamento e
    // o cadastro da Ordem (que pode divergir por causa de como cada um foi digitado).
    function extrairNumeroOrdemDoLocal(localTexto){
      var m = String(localTexto||'').match(/(\d{3,})\s*$/);
      return m ? m[1] : '';
    }
    function autoPreencherPorEquipamentoAp(){
      var equipTexto = document.getElementById('apEquip').value.trim();
      var equipObj = state.equipamentos.filter(function(e){ return equipLabel(e)===equipTexto; })[0];
      atualizarFotoEquipamentoAp(equipObj ? equipObj.codigo : null);
      if(restringirOrdem) return; // já travado numa ordem específica — não mexe
      if(!equipObj || !equipObj.local) return;
      if(document.getElementById('apOrdem').value.trim()) return; // já tem valor — não atropela
      var localTexto = String(equipObj.local).trim();
      // No tablet, o campo (que mostra o Local, mesmo continuando rotulado "Descrição Ordem")
      // sempre mostra o Local do equipamento — igual o Checklist — não depende de achar uma Ordem
      // cadastrada com esse Local igualzinho.
      if(modoOperadorSimplificado) document.getElementById('apOrdem').value = localTexto;
      var numeroExtraido = extrairNumeroOrdemDoLocal(localTexto);
      // O Nº Ordem sempre preenche sozinho com o número que vier no final do Local — não espera
      // achar uma Ordem cadastrada com esse número pra mostrar isso ao operador.
      if(modoOperadorSimplificado && numeroExtraido) document.getElementById('apOrdemNumero').value = numeroExtraido;
      var achada = null;
      if(numeroExtraido){
        achada = state.ordens.filter(function(o){ return String(o.numero||'').trim()===numeroExtraido; })[0];
      }
      if(!achada){
        // Sem número reconhecível no Local — tenta do jeito antigo, casando o Local cadastrado na
        // própria Ordem (útil pra quem não segue essa convenção de terminar o Local com o número).
        var alvo = normalizarLocalParaComparar(localTexto);
        var candidatas = ordensOrdenadas.filter(function(o){ return normalizarLocalParaComparar(o.local)===alvo; });
        if(candidatas.length===1) achada = candidatas[0];
      }
      if(achada){
        document.getElementById('apOrdemNumero').value = achada.numero || '';
        if(!modoOperadorSimplificado) document.getElementById('apOrdem').value = ordemLabelAtual(achada);
        document.getElementById('apNCliente').value = CLIENTE_NUMEROS[achada.cliente] || '';
      }
      atualizarServicoTarifa(); atualizarServicoHora();
    }
    document.getElementById('apEquip').addEventListener('change', autoPreencherPorEquipamentoAp);
    if(!editRecord) autoPreencherPorEquipamentoAp();
    else { var equipInicialEdicao = getEquip(editRecord.equipamentoId); atualizarFotoEquipamentoAp(equipInicialEdicao ? equipInicialEdicao.codigo : null); }
    if(modoOperadorSimplificado){
      // No tablet, o campo (agora "Local") não é obrigado a bater com o texto que a própria Ordem
      // tem cadastrado — então quem realmente diz qual Ordem é essa é o Nº Ordem (preenchido
      // sozinho a partir do número no final do Local, ou escolhido na lista). Só cai pra reconhecer
      // pelo texto se não tiver um Nº Ordem preenchido (ex.: alguém digitou o Local na mão).
      document.getElementById('apEquip').addEventListener('blur', function(){
        var el = this;
        setTimeout(function(){
          var texto = el.value.trim();
          if(texto && !state.equipamentos.some(function(e){ return equipLabel(e)===texto; })){
            el.value = '';
            autoPreencherPorEquipamentoAp();
          }
        }, 200);
      });
    }
    function resolverOrdemAtual(){
      if(modoOperadorSimplificado){
        var numeroTexto = normalizarEspacos(document.getElementById('apOrdemNumero').value);
        if(numeroTexto){
          var porNumero = state.ordens.filter(function(o){ return String(o.numero||'').trim()===numeroTexto; })[0];
          if(porNumero) return porNumero;
        }
      }
      var ordemTexto = document.getElementById('apOrdem').value.trim();
      return state.ordens.filter(function(o){ return ordemLabelAtual(o)===ordemTexto; })[0];
    }
    document.getElementById('apOrdem').addEventListener('change', function(){ atualizarServicoTarifa(); atualizarServicoHora(); });
    document.getElementById('apServico').addEventListener('change', updateConsolidacao);
    document.getElementById('apServicoHora').addEventListener('change', updateConsolidacao);
    function atualizarServicoTarifa(){
      var ordemObj = resolverOrdemAtual();
      var tarifas = ordemObj ? tarifasDaOrdem(ordemObj.id) : [];
      var wrap = document.getElementById('apServicoRow');
      var sel = document.getElementById('apServico');
      if(tarifas.length===0 || !isControladoriaLevel()){
        wrap.style.display = 'none';
        sel.innerHTML = '';
      } else {
        wrap.style.display = 'grid';
        var servicoAtual = editRecord && editRecord.servicoTarifa;
        sel.innerHTML = tarifas.map(function(t,idx){ return '<option value="'+idx+'"'+(t.servico===servicoAtual?' selected':'')+'>'+esc(t.servico)+' (R$ '+brNum(t.valor,2)+'/'+esc(t.unidade)+')</option>'; }).join('');
      }
      updateConsolidacao();
    }
    // Diferente do Serviço (tarifa de Pesagem) acima, este campo fica visível pra todo mundo
    // (não só Controladoria) — quem conclui o lançamento (podendo ser o próprio operador em
    // campo) precisa poder responder, senão ninguém consegue fechar o lançamento numa ordem com
    // mais de uma Tarifa por Hora. Só aparece quando existe ambiguidade de verdade (2+ tarifas).
    function atualizarServicoHora(){
      var ordemObj = resolverOrdemAtual();
      var tarifasHoraOrdem = ordemObj ? state.tarifasHora.filter(function(t){ return t.ordemId===ordemObj.id; }) : [];
      var wrap = document.getElementById('apServicoHoraRow');
      var sel = document.getElementById('apServicoHora');
      if(tarifasHoraOrdem.length<2){
        wrap.style.display = 'none';
        sel.innerHTML = '';
      } else {
        wrap.style.display = 'grid';
        var servicoHoraAtual = editRecord && editRecord.servicoHora;
        sel.innerHTML = '<option value="">Selecione…</option>' + tarifasHoraOrdem.map(function(t,idx){ return '<option value="'+idx+'"'+(t.servico===servicoHoraAtual?' selected':'')+'>'+esc(t.servico)+' (R$ '+brNum(t.valorHora,2)+'/h)</option>'; }).join('');
      }
      updateConsolidacao();
    }
    atualizarServicoTarifa();
    atualizarServicoHora();
    if(restringirOrdem){
      var trocarBtn = document.getElementById('trocarOrdemBtn');
      if(trocarBtn) trocarBtn.addEventListener('click', function(){
        promptEscolherOrdem(async function(ordemId){
          await saveOperadorOrdem(ordemId);
          toast('Ordem atualizada.');
          renderApropriacaoForm();
          renderApropriacoesTable();
        });
      });
    }

    function toggleIntervalo(){
      var show = document.getElementById('apTipoIntervalo').value !== 'Sem intervalo';
      document.getElementById('apIntIniWrap').style.display = show ? 'block' : 'none';
      document.getElementById('apIntFimWrap').style.display = show ? 'block' : 'none';
      updateConsolidacao();
    }
    function applyEscala(){
      var escalaKey = document.getElementById('apEscala').value;
      var esc2 = getEscala(escalaKey);
      var turnoWrap = document.getElementById('apTurnoWrap');
      turnoWrap.style.display = (esc2 && esc2.turnos) ? 'block' : 'none';
      if(esc2 && esc2.turnos){
        document.getElementById('apTurno').innerHTML = esc2.turnos.map(function(t){ return '<option value="'+t.key+'">'+esc(t.label)+'</option>'; }).join('');
      }
      if(esc2 && esc2.turnos && editRecord && editRecord.turno){ document.getElementById('apTurno').value = editRecord.turno; }
      var turnoKey = esc2 && esc2.turnos ? document.getElementById('apTurno').value : null;
      if(editRecord && editRecord.escala===escalaKey){
        document.getElementById('apEntrada').value = editRecord.entrada;
        document.getElementById('apTipoIntervalo').value = editRecord.tipoIntervalo;
        document.getElementById('apIntIni').value = editRecord.intervaloInicio;
        document.getElementById('apIntFim').value = editRecord.intervaloFim;
        document.getElementById('apSaida').value = editRecord.saida;
      } else {
        var horario = getEscalaHorario(escalaKey, turnoKey);
        if(horario){
          document.getElementById('apEntrada').value = horario.entrada;
          document.getElementById('apTipoIntervalo').value = horario.tipoIntervalo;
          document.getElementById('apIntIni').value = horario.intervaloInicio;
          document.getElementById('apIntFim').value = horario.intervaloFim;
          document.getElementById('apSaida').value = horario.saida;
        }
      }
      toggleIntervalo();
    }
    applyEscala();
    if(editRecord){
      document.getElementById('apHi').value = editRecord.horimetroInicial;
      document.getElementById('apHf').value = (editRecord.horimetroFinal===null || editRecord.horimetroFinal===undefined) ? '' : editRecord.horimetroFinal;
      updateConsolidacao();
    }
    document.getElementById('apEscala').addEventListener('change', applyEscala);
    document.getElementById('apTurno').addEventListener('change', applyEscala);
    document.getElementById('apTipoIntervalo').addEventListener('change', toggleIntervalo);
    ['apEntrada','apSaida','apIntIni','apIntFim','apHi','apHf','apData'].forEach(function(id){
      document.getElementById(id).addEventListener('input', updateConsolidacao);
    });
    document.getElementById('addParadaBtn').addEventListener('click', function(){
      formParadas.push({motivo: '', inicio:'', termino:'', horas: 0, tipoServico:''});
      renderParadasEditor();
      updateConsolidacao();
    });
    document.getElementById('apEntradaAgoraBtn').addEventListener('click', function(){
      document.getElementById('apEntrada').value = horaAtualHHMM();
      updateConsolidacao();
      // Depois de marcar a entrada, leva o operador direto pro horímetro
      // inicial — é o próximo dado que ele precisa informar pra "iniciar"
      // de verdade (junto com a situação: Operação ou À disposição).
      var campoHi = document.getElementById('apHi');
      if(campoHi){ campoHi.scrollIntoView({behavior:'smooth', block:'center'}); campoHi.focus(); }
    });
    // Ao terminar de digitar o Horímetro final (saiu do campo), preenche a Saída com a hora atual
    // — o operador ainda pode ajustar manualmente depois, se precisar.
    document.getElementById('apHf').addEventListener('change', function(){
      if(this.value.trim()!==''){
        document.getElementById('apSaida').value = horaAtualHHMM();
        updateConsolidacao();
      }
    });

    document.getElementById('apSalvarBtn').onclick = async function(){
      var errBox = document.getElementById('apFormError');
      errBox.innerHTML = '';
      var equipTexto = document.getElementById('apEquip').value.trim();
      var equipObj = state.equipamentos.filter(function(e){ return equipLabel(e)===equipTexto; })[0];
      var equipamentoId = equipObj ? equipObj.id : null;
      var ordemObj = resolverOrdemAtual();
      if(ordemObj && state.perfil==='campo' && state.operadorClienteRestrito && ordemObj.cliente!==state.operadorClienteRestrito){
        errBox.innerHTML = '<div class="form-error">Essa ordem não pertence ao cliente ao qual você está restrito ('+esc(state.operadorClienteRestrito)+').</div>';
        return;
      }
      var ordemId = ordemObj ? ordemObj.id : null;
      var data = document.getElementById('apData').value;
      var operadorTexto = normalizarEspacos(document.getElementById('apOperador').value);
      var operadorRegistrado = state.operadores.filter(function(o){
        return o.nome.toLowerCase()===operadorTexto.toLowerCase() || (o.matricula && o.matricula.toLowerCase()===operadorTexto.toLowerCase());
      })[0];
      var operador = operadorRegistrado ? operadorRegistrado.nome : null;
      var escala = document.getElementById('apEscala').value;
      var escObj = getEscala(escala);
      var turno = (escObj && escObj.turnos) ? document.getElementById('apTurno').value : null;
      var entrada = document.getElementById('apEntrada').value;
      var tipoIntervalo = document.getElementById('apTipoIntervalo').value;
      var intIni = document.getElementById('apIntIni').value;
      var intFim = document.getElementById('apIntFim').value;
      var saida = document.getElementById('apSaida').value;
      var hi = parseFloat(document.getElementById('apHi').value);
      var hfTexto = document.getElementById('apHf').value.trim();
      var hf = hfTexto==='' ? null : parseFloat(hfTexto);
      var situacaoInicialEl = document.getElementById('apSituacaoInicial');
      var situacaoInicial = situacaoInicialEl ? situacaoInicialEl.value : 'Operação';
      // Lançamento em etapas: Identificação + Entrada + Horímetro inicial são sempre exigidos.
      // Saída + Horímetro final (e tudo que depende deles) só são exigidos quando os dois já
      // estão preenchidos juntos — isso "fecha" o lançamento — ou quando está editando um
      // lançamento que já foi concluído antes (esse nunca volta a ser rascunho parcial).
      var tentandoConcluir = !!(saida && hf!==null && !isNaN(hf));
      var editandoConcluido = !!state.editingApropriacaoId;
      var editandoRascunho = !!state.editingRascunhoId;
      var idEmEdicao = state.editingApropriacaoId || state.editingRascunhoId;
      var todosParaChecagem = state.apropriacoes.concat(state.apropriacoesRascunhos);

      if(!data){ errBox.innerHTML = '<div class="form-error">Informe a data.</div>'; return; }
      if(!equipamentoId){ errBox.innerHTML = '<div class="form-error">Equipamento não reconhecido — digite o código ou escolha um da lista.</div>'; return; }
      if(!ordemId){ errBox.innerHTML = '<div class="form-error">Ordem não reconhecida — digite o nome ou escolha uma da lista.</div>'; return; }
      var equipEmOutraOrdem = data ? todosParaChecagem.filter(function(a){
        return a.equipamentoId===equipamentoId && a.data===data && a.ordemId!==ordemId && a.id!==idEmEdicao;
      })[0] : null;
      if(equipEmOutraOrdem){
        var ordemConflito = getOrdem(equipEmOutraOrdem.ordemId);
        errBox.innerHTML = '<div class="form-error">Este equipamento já tem lançamento em '+brDate(data)+' na ordem '+esc(ordemConflito?ordemLabel(ordemConflito):'(removida)')+'. Um equipamento não pode estar em duas ordens diferentes na mesma data.</div>';
        return;
      }
      if(!operadorTexto){ errBox.innerHTML = '<div class="form-error">Informe o operador — este campo é obrigatório.</div>'; return; }
      if(!operadorRegistrado){ errBox.innerHTML = '<div class="form-error">Operador não encontrado no cadastro. Cadastre-o em Cadastros → Operadores antes de lançar esta apropriação.</div>'; return; }
      // Um operador pode lançar mais de uma vez no mesmo dia quando troca de equipamento.
      // O que continua barrado é repetir o MESMO equipamento no MESMO dia — esse é o caso do
      // salvamento duplicado sem querer, que entraria com horas dobradas no faturamento.
      // Bloqueio removido a pedido: antes não deixava lançar duas vezes o
      // mesmo operador + data + equipamento (pra cobrir, por exemplo, um
      // período em "Operação" e outro "À disposição" no mesmo dia, no
      // mesmo equipamento). Os outros lançamentos do dia continuam
      // aparecendo normalmente na tela "Seus lançamentos de hoje".
      if(!escala){ errBox.innerHTML = '<div class="form-error">Selecione a escala (jornada de trabalho) do operador.</div>'; return; }
      if(!entrada){ errBox.innerHTML = '<div class="form-error">Informe a entrada do operador.</div>'; return; }
      if(isNaN(hi)){ errBox.innerHTML = '<div class="form-error">Informe o horímetro inicial.</div>'; return; }
      var lancamentosAnterioresEquip = state.apropriacoes.filter(function(a){
        return a.equipamentoId===equipamentoId && a.data <= data && a.id!==state.editingApropriacaoId;
      }).sort(function(a,b){ return a.data.localeCompare(b.data) || (a.entrada||'').localeCompare(b.entrada||''); });
      var ultimoLancamentoEquip = lancamentosAnterioresEquip[lancamentosAnterioresEquip.length-1];
      if(ultimoLancamentoEquip && typeof ultimoLancamentoEquip.horimetroFinal==='number' && hi < ultimoLancamentoEquip.horimetroFinal){
        errBox.innerHTML = '<div class="form-error">O horímetro inicial ('+brNum(hi,1)+') não pode ser menor que o horímetro final do último lançamento desse equipamento, em '+brDate(ultimoLancamentoEquip.data)+' ('+brNum(ultimoLancamentoEquip.horimetroFinal,1)+'). O horímetro só é zerado em caso de troca de painel — se foi isso, me avise para ajustarmos manualmente.</div>';
        return;
      }
      // Salto de horímetro maior que 13h desde o último lançamento: passou a BLOQUEAR de vez —
      // não deixa salvar. Se for legítimo (troca de painel, por exemplo), precisa ajuste manual.
      var saltoHorimetro = null;
      if(ultimoLancamentoEquip && typeof ultimoLancamentoEquip.horimetroFinal==='number'){
        var gapHorimetro = hi - ultimoLancamentoEquip.horimetroFinal;
        if(gapHorimetro > 13){
          errBox.innerHTML = '<div class="form-error">O horímetro inicial ('+brNum(hi,1)+'h) está '+brNum(gapHorimetro,1)+'h à frente do último lançamento registrado desse equipamento ('+brNum(ultimoLancamentoEquip.horimetroFinal,1)+'h, em '+brDate(ultimoLancamentoEquip.data)+'). Saltos acima de 13h não são permitidos — confira o valor digitado. Se for uma troca de painel de verdade, fale com a Controladoria para ajuste manual.</div>';
          return;
        }
      }

      async function salvarComoRascunho(){
        var rascunhoExistente = editandoRascunho ? state.apropriacoesRascunhos.filter(function(x){ return x.id===idEmEdicao; })[0] : null;
        var record = {
          id: idEmEdicao || uid(), equipamentoId: equipamentoId, ordemId: ordemId, data: data,
          operador: operador, escala: escala, turno: turno,
          entrada: entrada, tipoIntervalo: tipoIntervalo,
          intervaloInicio: tipoIntervalo==='Sem intervalo' ? '' : intIni,
          intervaloFim: tipoIntervalo==='Sem intervalo' ? '' : intFim,
          saida: saida || '',
          horimetroInicial: hi, horimetroFinal: hf, situacaoInicial: situacaoInicial,
          paradas: formParadas.filter(function(p){ return p.horas>0; }), observacao: '',
          status: 'em_andamento',
          rodadas: rascunhoExistente ? (rascunhoExistente.rodadas||1)+1 : 1
        };
        if(editandoRascunho){
          state.apropriacoesRascunhos = state.apropriacoesRascunhos.map(function(x){ return x.id===record.id ? record : x; });
        } else {
          state.apropriacoesRascunhos.push(record);
        }
        var ok = await saveList('apropriacoes_rascunhos_v1', state.apropriacoesRascunhos);
        toast(ok ? ('Lançamento salvo em andamento (rodada '+record.rodadas+' de até 4) — '+operador+', '+brDate(data)+'.') : 'Salvo localmente — problema ao sincronizar.', 6000);
        renderApropriacaoForm(record, true);
      }

      if(!tentandoConcluir && !editandoConcluido){
        salvarComoRascunho();
        return;
      }

      // A partir daqui está fechando o lançamento (rascunho virando definitivo, ou edição de um
      // lançamento já concluído) — exige tudo, igual sempre foi antes de existir o rascunho.
      if(!saida){ errBox.innerHTML = '<div class="form-error">Informe a saída do operador.</div>'; return; }
      if(hf===null || isNaN(hf)){ errBox.innerHTML = '<div class="form-error">Informe o horímetro final.</div>'; return; }
      if(tipoIntervalo!=='Sem intervalo' && (!intIni || !intFim)){ errBox.innerHTML = '<div class="form-error">Informe o início e o fim do intervalo, ou selecione "Sem intervalo".</div>'; return; }
      var horasOperador = computeHorasOperador(entrada, tipoIntervalo, intIni, intFim, saida);
      if(horasOperador===null || horasOperador<=0){ errBox.innerHTML = '<div class="form-error">Verifique os horários informados — o intervalo não pode ser maior ou igual ao turno.</div>'; return; }
      // No lançamento por linha do tempo (tablet), o intervalo de almoço deixou de ser um campo à
      // parte — é só mais uma parada (motivo "Almoço"), igual qualquer outra. Por isso, só aqui,
      // as horas do operador saem do turno inteiro (entrada→saída) menos TODAS as paradas do dia
      // (Operação + À disposição − paradas, incluindo almoço). Fora desse modo nada muda: o
      // Escritório continua vendo paradas só como registro informativo, sem subtrair das horas.
      if(modoOperadorSimplificado){
        var totalHorasParadasTl = formParadas.filter(function(p){ return p.horas>0; }).reduce(function(s,p){ return s+p.horas; },0);
        horasOperador = Math.max(0, Math.round((horasOperador - totalHorasParadasTl)*100)/100);
      }
      if(hf < hi){ errBox.innerHTML = '<div class="form-error">Horímetro final não pode ser menor que o horímetro inicial — verifique os valores.</div>'; return; }
      var paradaForaDoTurno = formParadas.filter(function(p){ return p.horas>0; }).filter(function(p){
        return p.inicio && paradaAntesDaEntrada(entrada, saida, p.inicio);
      })[0];
      if(paradaForaDoTurno){
        errBox.innerHTML = '<div class="form-error">O início de uma parada ('+esc(paradaForaDoTurno.inicio)+') está fora do turno do operador (entrada '+esc(entrada)+', saída '+esc(saida)+'). Confira o horário digitado.</div>';
        return;
      }
      // Jornada acima de 12h continua não bloqueando — pede confirmação e fica marcada pra
      // Controladoria revisar depois (independente da escala), destacada na Parte Diária.
      // Como agora cabe mais de um lançamento por dia, o limite vale para a SOMA do dia do
      // operador — senão dois turnos de 7h em equipamentos diferentes passariam sem aviso
      // nenhum. Com um lançamento só no dia, a conta dá exatamente o mesmo de antes.
      var horasOutrosLancamentosDoDia = todosParaChecagem.filter(function(a){
        return a.operador===operador && a.data===data && a.id!==idEmEdicao;
      }).reduce(function(soma, a){
        return soma + (typeof a.horasOperador==='number' ? a.horasOperador : 0);
      }, 0);
      var horasDoDia = Math.round((horasOperador + horasOutrosLancamentosDoDia)*100)/100;
      var excedeuJornada = horasDoDia > 12 ? Math.round((horasDoDia-12)*100)/100 : null;
      var horasHorimetro = Math.round((hf-hi)*100)/100;
      if(horasHorimetro > horasOperador + 0.01){
        errBox.innerHTML = '<div class="form-error">Horas de horímetro ('+brNum(horasHorimetro,2)+') não podem ser maiores que as horas programadas ('+brNum(horasOperador,2)+').</div>';
        return;
      }
      var tarifasHoraOrdemChk = state.tarifasHora.filter(function(t){ return t.ordemId===ordemId; });
      if(tarifasHoraOrdemChk.length>1){
        var servicoHoraSelElChk = document.getElementById('apServicoHora');
        if(!servicoHoraSelElChk || servicoHoraSelElChk.value===''){
          errBox.innerHTML = '<div class="form-error">Esta ordem tem mais de uma Tarifa por Hora cadastrada — selecione a qual serviço essas horas pertencem, em "Serviço de Hora", pra não duplicar no Boletim de Medição.</div>';
          return;
        }
      }
      function finalizarSalvamentoApropriacao(){
      var servicoTarifa = '', valorUnitarioTarifa = 0, valorProducaoCalculado = 0;
      var tarifasOrdem = tarifasDaOrdem(ordemId);
      var servicoSelEl = document.getElementById('apServico');
      if(tarifasOrdem.length>0 && servicoSelEl && servicoSelEl.value!==''){
        var tSel = tarifasOrdem[+servicoSelEl.value];
        if(tSel){
          servicoTarifa = tSel.servico;
          valorUnitarioTarifa = tSel.valor;
        }
      }
      var servicoHora = '';
      var tarifasHoraOrdem = state.tarifasHora.filter(function(t){ return t.ordemId===ordemId; });
      var servicoHoraSelEl = document.getElementById('apServicoHora');
      if(tarifasHoraOrdem.length>1 && servicoHoraSelEl && servicoHoraSelEl.value!==''){
        var thSel = tarifasHoraOrdem[+servicoHoraSelEl.value];
        if(thSel) servicoHora = thSel.servico;
      }
      var record = {
        id: idEmEdicao || uid(), equipamentoId: equipamentoId, ordemId: ordemId, data: data,
        dataFim: isOvernightShift(entrada, saida) ? addDaysISO(data, 1) : data,
        operador: operador, escala: escala, turno: turno,
        entrada: entrada, tipoIntervalo: tipoIntervalo,
        intervaloInicio: tipoIntervalo==='Sem intervalo' ? '' : intIni,
        intervaloFim: tipoIntervalo==='Sem intervalo' ? '' : intFim,
        saida: saida, horasOperador: horasOperador,
        horimetroInicial: hi, horimetroFinal: hf, horasHorimetro: horasHorimetro, situacaoInicial: situacaoInicial,
        servicoTarifa: servicoTarifa, valorUnitarioTarifa: valorUnitarioTarifa, valorProducaoCalculado: valorProducaoCalculado,
        servicoHora: servicoHora,
        paradas: formParadas.filter(function(p){ return p.horas>0; }), observacao: '',
        status: 'concluido',
        saltoHorimetro: saltoHorimetro, excedeuJornada: excedeuJornada,
        timelineEventos: apEventos
      };
      return (async function(){
      var jaExisteEmApropriacoes = state.apropriacoes.some(function(x){ return x.id===record.id; });
      if(jaExisteEmApropriacoes){
        state.apropriacoes = state.apropriacoes.map(function(x){ return x.id===record.id ? record : x; });
      } else {
        state.apropriacoes.push(record);
      }
      var wasEditing = jaExisteEmApropriacoes;
      var ok = await saveList('apropriacoes_v7', state.apropriacoes);
      if(editandoRascunho){
        state.apropriacoesRascunhos = state.apropriacoesRascunhos.filter(function(x){ return x.id!==record.id; });
        await saveList('apropriacoes_rascunhos_v1', state.apropriacoesRascunhos);
      }
      var avisos = [];
      if(saltoHorimetro!==null) avisos.push('⚠ Salto de '+brNum(saltoHorimetro,1)+'h no horímetro desde o último lançamento');
      if(excedeuJornada!==null) avisos.push('⚠ Jornada '+brNum(excedeuJornada,1)+'h acima das 12h');
      if(avisos.length>0){
        toast((ok ? (wasEditing ? 'Parte diária atualizada. ' : 'Parte diária lançada. ') : 'Salvo localmente — problema ao sincronizar. ') + avisos.join(' · ')+' — a Controladoria foi sinalizada para revisar.', 7000);
      } else {
        toast(ok ? (wasEditing ? 'Parte diária atualizada.' : 'Parte diária lançada.') : 'Lançamento salvo localmente — houve um problema ao sincronizar.');
      }
      state.editingApropriacaoId = null;
      state.editingRascunhoId = null;
      renderApropriacaoEntry();
      renderApropriacoesTable();
      renderDashboard();
      renderCadastro();
      })();
      }
      if(saltoHorimetro!==null && excedeuJornada!==null){
        confirmModal(
          '⚠ Confirmar lançamento fora do padrão',
          'Dois pontos incomuns nesse lançamento:<br>' +
          '• O horímetro inicial ('+brNum(hi,1)+'h) está <b>'+brNum(saltoHorimetro,1)+'h à frente</b> do último lançamento desse equipamento ('+brNum(ultimoLancamentoEquip.horimetroFinal,1)+'h, em '+brDate(ultimoLancamentoEquip.data)+').<br>' +
          '• A jornada do dia ('+brNum(horasDoDia,1)+'h, somando os lançamentos deste operador em '+brDate(data)+') está <b>'+brNum(excedeuJornada,1)+'h acima</b> do limite de 12h.<br><br>' +
          '<b>É isso mesmo que você quer lançar?</b> O lançamento será salvo e sinalizado para a Controladoria revisar depois.',
          finalizarSalvamentoApropriacao
        );
        return;
      }
      if(saltoHorimetro!==null){
        confirmModal(
          '⚠ Confirmar salto de horímetro',
          'O horímetro inicial informado ('+brNum(hi,1)+'h) está <b>'+brNum(saltoHorimetro,1)+'h à frente</b> do último lançamento registrado desse equipamento ('+brNum(ultimoLancamentoEquip.horimetroFinal,1)+'h, em '+brDate(ultimoLancamentoEquip.data)+'). Isso é incomum — normalmente só acontece em troca de painel. <br><br><b>É isso mesmo que você quer lançar?</b> O lançamento será salvo e sinalizado para a Controladoria revisar depois.',
          finalizarSalvamentoApropriacao
        );
        return;
      }
      if(excedeuJornada!==null){
        confirmModal(
          '⚠ Confirmar jornada acima de 12h',
          'A jornada do dia ('+brNum(horasDoDia,1)+'h, somando os lançamentos deste operador em '+brDate(data)+') está <b>'+brNum(excedeuJornada,1)+'h acima</b> do limite de 12 horas de trabalho. <br><br><b>É isso mesmo que você quer lançar?</b> O lançamento será salvo e sinalizado para a Controladoria revisar depois.',
          finalizarSalvamentoApropriacao
        );
        return;
      }
      finalizarSalvamentoApropriacao();
    };

    // ================= LINHA DO TEMPO (modo operador simplificado) =================
    // Guarda o progresso como rascunho a cada passo (Iniciar/Adicionar parada/
    // Finalizar parada) — assim ninguém perde o que já fez se fechar a aba no
    // meio do turno. Lê os mesmos campos (escondidos) que o formulário normal
    // usa, então não precisa duplicar nenhuma regra de cálculo.
    async function persistirRascunhoTimeline(){
      try{
        var equipTextoTl = document.getElementById('apEquip').value.trim();
        var equipObjTl = state.equipamentos.filter(function(e){ return equipLabel(e)===equipTextoTl; })[0];
        var ordemObjTl = resolverOrdemAtual();
        if(!equipObjTl || !ordemObjTl) return; // ainda incompleto — não força salvar
        var operadorNomeTl = operadorAuto ? operadorAuto.nome : document.getElementById('apOperador').value.trim();
        var idAtualTl = state.editingRascunhoId || uid();
        state.editingRascunhoId = idAtualTl;
        var rascunhoExistenteTl = state.apropriacoesRascunhos.filter(function(x){ return x.id===idAtualTl; })[0];
        var primeiraAtividadeTl = apEventos.filter(function(e){ return e.tipo==='atividade'; })[0];
        var recordTl = {
          id: idAtualTl, equipamentoId: equipObjTl.id, ordemId: ordemObjTl.id, data: document.getElementById('apData').value,
          operador: operadorNomeTl,
          escala: document.getElementById('apEscala').value || null,
          turno: document.getElementById('apTurnoWrap').style.display!=='none' ? document.getElementById('apTurno').value : null,
          entrada: document.getElementById('apEntrada').value || '', tipoIntervalo: 'Sem intervalo', intervaloInicio: '', intervaloFim: '',
          saida: '',
          horimetroInicial: parseFloat(document.getElementById('apHi').value) || 0, horimetroFinal: null,
          situacaoInicial: primeiraAtividadeTl ? primeiraAtividadeTl.situacao : 'Operação',
          timelineEventos: apEventos,
          paradas: formParadas, observacao: '',
          status: 'em_andamento',
          rodadas: rascunhoExistenteTl ? (rascunhoExistenteTl.rodadas||1)+1 : 1
        };
        if(rascunhoExistenteTl){ state.apropriacoesRascunhos = state.apropriacoesRascunhos.map(function(x){ return x.id===recordTl.id ? recordTl : x; }); }
        else { state.apropriacoesRascunhos.push(recordTl); }
        await saveList('apropriacoes_rascunhos_v1', state.apropriacoesRascunhos);
      }catch(e){ console.error('Falha ao salvar rascunho da linha do tempo', e); }
    }

    // Contador compacto (ex.: "1h05") do tempo decorrido desde que o evento em aberto (atividade
    // ou parada) começou — só mostra, não recalcula nada: quem manda no valor salvo continua
    // sendo o horário de início/fim de cada evento, igual sempre foi.
    function formatarDuracaoTl(horasDecimal){
      var totalMin = Math.max(0, Math.round(horasDecimal*60));
      var h = Math.floor(totalMin/60), m = totalMin%60;
      return h+'h'+String(m).padStart(2,'0');
    }
    function renderApTimeline(){
      var wrapT = document.getElementById('apTimelineWrap');
      if(!wrapT) return;
      if(apTlTimerId){ clearInterval(apTlTimerId); apTlTimerId = null; }
      var ultimoTl = apEventos[apEventos.length-1];
      var abertoAtividadeTl = ultimoTl && ultimoTl.tipo==='atividade' && !ultimoTl.fim;
      var abertoParadaTl = ultimoTl && ultimoTl.tipo==='parada' && !ultimoTl.fim;

      function linhaFechadaTl(ev){
        if(ev.tipo==='atividade'){
          return '<div class="consol-line" style="border-top:1px solid var(--border);padding-top:6px;margin-top:6px;">' +
            '<span>🟢 '+esc(ev.situacao)+' · '+esc(ev.inicio)+'–'+esc(ev.fim||'…')+'</span>' +
            '<b>'+brNum(ev.horimetroIni,1)+' → '+(ev.horimetroFim!=null&&ev.horimetroFim!==''?brNum(ev.horimetroFim,1):'—')+'</b>' +
          '</div>';
        }
        return '<div class="consol-line" style="border-top:1px solid var(--border);padding-top:6px;margin-top:6px;">' +
          '<span>⏸ '+esc(ev.motivo)+' · '+esc(ev.inicio)+'–'+esc(ev.fim||'…')+(ev.observacao?' · <i>'+esc(ev.observacao)+'</i>':'')+'</span>' +
          '<b style="color:var(--text-muted);">parada</b>' +
        '</div>';
      }

      var historicoHtmlTl = apEventos.length
        ? '<div class="consol-box" style="margin-bottom:12px;">'+apEventos.map(linhaFechadaTl).join('')+'</div>'
        : '<div class="muted-tag" style="margin-bottom:8px;">Nada lançado ainda hoje neste equipamento.</div>';

      var acaoHtmlTl = '';
      if(!ultimoTl || ultimoTl.fim){
        acaoHtmlTl =
          '<div class="field-row">' +
            '<div class="field"><label>Horímetro</label><input type="number" step="0.1" id="apTlHorimetro" placeholder="0,0"></div>' +
            '<div class="field"><label>Iniciar em</label><select id="apTlSituacao">'+optionsList(['Operação','À disposição'],'Operação')+'</select></div>' +
          '</div>' +
          '<div id="apTlErro"></div>' +
          '<div style="display:flex;gap:8px;flex-wrap:wrap;">' +
            '<button type="button" class="btn btn-primary" style="flex:1" id="apTlIniciarBtn">Iniciar</button>' +
            '<button type="button" class="btn btn-outline" style="flex:1" id="apTlIniciarEmParadaBtn">+ Iniciar já em parada</button>' +
          '</div>' +
          '<div id="apTlParadaForm" style="display:none;margin-top:10px;padding-top:8px;border-top:1px solid var(--border);">' +
            '<div class="field-row">' +
              '<div class="field"><label>Motivo</label><select id="apTlParadaCategoria"><option value="">Selecione…</option>'+optionsList(CATEGORIAS_PARADA,'')+'</select></div>' +
              '<div class="field"><label>Serviço</label><select id="apTlParadaServico"><option value="">Escolha o motivo primeiro…</option></select></div>' +
              '<div class="field"><label>Horímetro</label><input type="number" step="0.1" id="apTlParadaHorimetro" placeholder="0,0"></div>' +
            '</div>' +
            '<div class="field"><label>Observação (opcional)</label><input type="text" id="apTlParadaObs" placeholder="Ex: aguardando liberação"></div>' +
            '<div id="apTlParadaErro"></div>' +
            '<button type="button" class="btn btn-outline btn-sm" id="apTlParadaIniciarBtn">Iniciar parada</button>' +
          '</div>';
      } else if(abertoAtividadeTl){
        acaoHtmlTl =
          '<div class="muted-tag" style="margin-bottom:8px;">Em '+esc(ultimoTl.situacao)+' desde '+esc(ultimoTl.inicio)+' (horímetro '+brNum(ultimoTl.horimetroIni,1)+') · <b id="apTlContador" style="color:var(--navy);">0h00</b></div>' +
          '<div id="apTlParadaForm" style="display:none;margin-bottom:10px;padding-top:8px;border-top:1px solid var(--border);">' +
            '<div class="field-row">' +
              '<div class="field"><label>Motivo</label><select id="apTlParadaCategoria"><option value="">Selecione…</option>'+optionsList(CATEGORIAS_PARADA,'')+'</select></div>' +
              '<div class="field"><label>Serviço</label><select id="apTlParadaServico"><option value="">Escolha o motivo primeiro…</option></select></div>' +
              '<div class="field"><label>Horímetro</label><input type="number" step="0.1" id="apTlParadaHorimetro" placeholder="0,0"></div>' +
            '</div>' +
            '<div class="field"><label>Observação (opcional)</label><input type="text" id="apTlParadaObs" placeholder="Ex: aguardando liberação"></div>' +
            '<div id="apTlParadaErro"></div>' +
            '<button type="button" class="btn btn-outline btn-sm" id="apTlParadaIniciarBtn">Iniciar parada</button>' +
          '</div>' +
          '<div id="apTlFinalForm" style="display:none;margin-bottom:10px;padding-top:8px;border-top:1px solid var(--border);">' +
            '<div class="field"><label>Horímetro final</label><input type="number" step="0.1" id="apTlHorimetroFinal" placeholder="0,0"></div>' +
            '<div id="apTlFinalErro"></div>' +
            '<button type="button" class="btn btn-primary btn-sm" id="apTlFinalConfirmarBtn">Salvar lançamento</button>' +
          '</div>' +
          '<div style="display:flex;gap:8px;flex-wrap:wrap;">' +
            '<button type="button" class="btn btn-outline" id="apTlAddParadaBtn">+ Adicionar parada</button>' +
            '<button type="button" class="btn btn-outline" id="apTlFinalizarBtn">Finalizar lançamento</button>' +
          '</div>';
      } else if(abertoParadaTl){
        acaoHtmlTl =
          '<div class="muted-tag" style="margin-bottom:8px;">Parado — '+esc(ultimoTl.motivo)+' — desde '+esc(ultimoTl.inicio)+' · <b id="apTlContador" style="color:var(--ru);">0h00</b></div>' +
          '<button type="button" class="btn btn-primary" id="apTlFinalizarParadaBtn">Finalizar parada</button>';
      }

      wrapT.innerHTML = historicoHtmlTl + acaoHtmlTl;

      // Contador ao vivo: atualiza a cada 15s enquanto houver uma atividade ou parada em
      // aberto. Pequeno de propósito (só o texto em negrito acima) — não é mais um campo,
      // só um retrato de "quanto tempo já passou" pra quem está lançando acompanhar.
      if(abertoAtividadeTl || abertoParadaTl){
        var atualizarContadorTl = function(){
          var el = document.getElementById('apTlContador');
          if(!el){ if(apTlTimerId){ clearInterval(apTlTimerId); apTlTimerId = null; } return; }
          var decorrido = diffHoras(ultimoTl.inicio, horaAtualHHMM());
          el.textContent = decorrido===null ? '—' : formatarDuracaoTl(decorrido);
        };
        atualizarContadorTl();
        apTlTimerId = setInterval(atualizarContadorTl, 15000);
      }

      if(!ultimoTl || ultimoTl.fim){
        document.getElementById('apTlIniciarBtn').onclick = function(){
          var hRaw = document.getElementById('apTlHorimetro').value;
          var h = parseFloat(hRaw);
          var erroEl = document.getElementById('apTlErro');
          if(hRaw===''||isNaN(h)){ erroEl.innerHTML = '<div class="form-error">Informe o horímetro.</div>'; return; }
          var situacaoTl = document.getElementById('apTlSituacao').value;
          var agoraTl = horaAtualHHMM();
          if(apEventos.length===0){
            document.getElementById('apEntrada').value = agoraTl;
            document.getElementById('apHi').value = h;
          }
          apEventos.push({ tipo:'atividade', situacao: situacaoTl, horimetroIni: h, inicio: agoraTl, fim: null, horimetroFim: null });
          persistirRascunhoTimeline();
          renderApTimeline();
          updateConsolidacao();
        };
        // "Iniciar já em parada" — pro caso do operador começar o dia (ou retomar depois de uma
        // parada anterior) já parado, sem precisar abrir uma atividade primeiro pra depois parar.
        document.getElementById('apTlIniciarEmParadaBtn').onclick = function(){
          document.getElementById('apTlParadaForm').style.display = 'block';
        };
        document.getElementById('apTlParadaCategoria').addEventListener('change', function(){
          var servSel = document.getElementById('apTlParadaServico');
          var categoria = this.value;
          servSel.innerHTML = categoria ? ('<option value="">Selecione…</option>'+optionsList(servicosDaCategoria(categoria),'')) : '<option value="">Escolha o motivo primeiro…</option>';
        });
        document.getElementById('apTlParadaIniciarBtn').onclick = function(){
          var servico = document.getElementById('apTlParadaServico').value;
          var hRaw = document.getElementById('apTlParadaHorimetro').value;
          var h = parseFloat(hRaw);
          var erroEl = document.getElementById('apTlParadaErro');
          if(!servico){ erroEl.innerHTML = '<div class="form-error">Selecione o motivo/serviço da parada.</div>'; return; }
          if(hRaw===''||isNaN(h)){ erroEl.innerHTML = '<div class="form-error">Informe o horímetro.</div>'; return; }
          var obsTl = normalizarEspacos(document.getElementById('apTlParadaObs').value);
          var agoraTl = horaAtualHHMM();
          if(apEventos.length===0){
            document.getElementById('apEntrada').value = agoraTl;
            document.getElementById('apHi').value = h;
          }
          apEventos.push({ tipo:'parada', motivo: servico, horimetroIni: h, inicio: agoraTl, fim: null, observacao: obsTl });
          formParadas.push({ motivo: servico, inicio: agoraTl, termino: '', horas: 0, tipoServico: '', observacao: obsTl });
          persistirRascunhoTimeline();
          renderApTimeline();
          updateConsolidacao();
        };
      } else if(abertoAtividadeTl){
        document.getElementById('apTlAddParadaBtn').onclick = function(){
          document.getElementById('apTlParadaForm').style.display = 'block';
          document.getElementById('apTlFinalForm').style.display = 'none';
        };
        document.getElementById('apTlFinalizarBtn').onclick = function(){
          document.getElementById('apTlFinalForm').style.display = 'block';
          document.getElementById('apTlParadaForm').style.display = 'none';
        };
        document.getElementById('apTlParadaCategoria').addEventListener('change', function(){
          var servSel = document.getElementById('apTlParadaServico');
          var categoria = this.value;
          servSel.innerHTML = categoria ? ('<option value="">Selecione…</option>'+optionsList(servicosDaCategoria(categoria),'')) : '<option value="">Escolha o motivo primeiro…</option>';
        });
        document.getElementById('apTlParadaIniciarBtn').onclick = function(){
          var servico = document.getElementById('apTlParadaServico').value;
          var hRaw = document.getElementById('apTlParadaHorimetro').value;
          var h = parseFloat(hRaw);
          var erroEl = document.getElementById('apTlParadaErro');
          if(!servico){ erroEl.innerHTML = '<div class="form-error">Selecione o motivo/serviço da parada.</div>'; return; }
          if(hRaw===''||isNaN(h)){ erroEl.innerHTML = '<div class="form-error">Informe o horímetro.</div>'; return; }
          var obsTl = normalizarEspacos(document.getElementById('apTlParadaObs').value);
          var agoraTl = horaAtualHHMM();
          ultimoTl.horimetroFim = h; ultimoTl.fim = agoraTl;
          apEventos.push({ tipo:'parada', motivo: servico, horimetroIni: h, inicio: agoraTl, fim: null, observacao: obsTl });
          formParadas.push({ motivo: servico, inicio: agoraTl, termino: '', horas: 0, tipoServico: '', observacao: obsTl });
          persistirRascunhoTimeline();
          renderApTimeline();
          updateConsolidacao();
        };
      } else if(abertoParadaTl){
        document.getElementById('apTlFinalizarParadaBtn').onclick = function(){
          var agoraTl = horaAtualHHMM();
          var horimetroRetomadaTl = ultimoTl.horimetroIni;
          ultimoTl.fim = agoraTl;
          var abertasFormParadasTl = formParadas.filter(function(p){ return !p.termino; });
          var alvoFormParadaTl = abertasFormParadasTl[abertasFormParadasTl.length-1];
          if(alvoFormParadaTl){
            alvoFormParadaTl.termino = agoraTl;
            alvoFormParadaTl.horas = paradaHoras(alvoFormParadaTl);
          }
          // Reinicia sozinha a atividade que tava rolando antes dessa parada — não precisa clicar
          // em "Iniciar" de novo. O horímetro não andou durante a parada, então retoma do mesmo
          // horímetro em que ela começou. Só não reinicia nada se essa parada foi o primeiro
          // lançamento do dia (não tinha atividade nenhuma antes dela) — nesse caso volta pra tela
          // de escolher "Iniciar" ou "Iniciar já em parada" de novo.
          var eventoAnteriorTl = apEventos[apEventos.length-2];
          if(eventoAnteriorTl && eventoAnteriorTl.tipo==='atividade'){
            apEventos.push({ tipo:'atividade', situacao: eventoAnteriorTl.situacao, horimetroIni: horimetroRetomadaTl, inicio: agoraTl, fim: null, horimetroFim: null });
          }
          persistirRascunhoTimeline();
          renderParadasEditor();
          renderApTimeline();
          updateConsolidacao();
        };
      }

      // O botão real de salvar (apSalvarBtn) fica escondido nesse modo, mas
      // continua existindo e com todas as regras de negócio de sempre — só
      // preenchemos os campos escondidos (Hf, Saída, Intervalo, Situação) e
      // disparamos o clique dele, em vez de duplicar a validação aqui.
      var finalConfirmarBtnTl = document.getElementById('apTlFinalConfirmarBtn');
      if(finalConfirmarBtnTl){
        finalConfirmarBtnTl.onclick = function(){
          var hRaw = document.getElementById('apTlHorimetroFinal').value;
          var h = parseFloat(hRaw);
          var erroEl = document.getElementById('apTlFinalErro');
          if(hRaw===''||isNaN(h)){ erroEl.innerHTML = '<div class="form-error">Informe o horímetro final.</div>'; return; }
          if(h < ultimoTl.horimetroIni){ erroEl.innerHTML = '<div class="form-error">O horímetro final não pode ser menor que o horímetro deste período em operação ('+brNum(ultimoTl.horimetroIni,1)+').</div>'; return; }
          var agoraTl = horaAtualHHMM();
          ultimoTl.horimetroFim = h; ultimoTl.fim = agoraTl;
          document.getElementById('apSaida').value = agoraTl;
          document.getElementById('apHf').value = h;
          document.getElementById('apTipoIntervalo').value = 'Sem intervalo';
          var primeiraAtividadeSalvarTl = apEventos.filter(function(e){ return e.tipo==='atividade'; })[0];
          if(primeiraAtividadeSalvarTl) document.getElementById('apSituacaoInicial').value = primeiraAtividadeSalvarTl.situacao;
          persistirRascunhoTimeline();
          document.getElementById('apSalvarBtn').click();
        };
      }
    }
  }

