  function vigenciaOrdemTexto(o, hoje){
    if(!o.vigenciaContratoFim) return '—';
    var diasRestantes = Math.round((new Date(o.vigenciaContratoFim+'T00:00:00') - new Date(hoje+'T00:00:00')) / 86400000);
    if(diasRestantes < 0) return 'Vencido em '+brDate(o.vigenciaContratoFim);
    if(diasRestantes <= 30) return 'Vence em '+diasRestantes+' dia'+(diasRestantes===1?'':'s');
    return 'até '+brDate(o.vigenciaContratoFim);
  }
  function valoresColunaOrdem(o){
    return {
      numero: o.numero||'—', nome: o.nome||'—', cliente: o.cliente||'—', local: o.local||'—',
      segmento: o.vendedor||'—', modelo: o.modeloContrato||'—', cnpj: o.cnpj||'—',
      vigencia: vigenciaOrdemTexto(o, todayISO())
    };
  }
