          if(!cliente || !nome){ semDados++; return; }
          var chave = nome.toLowerCase()+'||'+cliente.toLowerCase();
          if(state.ordens.some(function(o){ return o.nome.toLowerCase()===nome.toLowerCase() && o.cliente.toLowerCase()===cliente.toLowerCase(); }) || vistos[chave]){ duplicados++; return; }
