  /* ============ RENDER: APROPRIAÇÃO TABLE ============ */
  function populateApFilters(){
    var clienteRestrito = (state.perfil==='campo' && state.operadorClienteRestrito) ? state.operadorClienteRestrito : null;
    var restrito = (state.perfil==='campo' && state.operadorOrdemId && !clienteRestrito);
    var ordemInput = document.getElementById('filtroApOrdem');
    var ordemNumeroInput = document.getElementById('filtroApOrdemNumero');

    wireComboBox('filtroApOperador', 'filtroApOperadorList', function(){
      var nomes = new Set();
      state.operadores.forEach(function(o){ nomes.add(o.nome); });
      state.apropriacoes.forEach(function(a){ if(a.operador) nomes.add(a.operador); });
      return Array.from(nomes).sort(function(a,b){ return a.localeCompare(b,'pt-BR'); });
    }, null, null, 'Todos os operadores');

    wireComboBox('filtroApEquip', 'filtroApEquipList', function(){
      var ordemAtualId = restrito ? state.operadorOrdemId : resolverOrdemFiltro('filtroApOrdem');
      var equipamentosFiltrados = ordemAtualId
        ? state.equipamentos.filter(function(e){ return state.apropriacoes.some(function(a){ return a.ordemId===ordemAtualId && a.equipamentoId===e.id; }); })
        : state.equipamentos;
      return equipamentosFiltrados.slice().sort(function(a,b){ return a.codigo.localeCompare(b.codigo,'pt-BR'); }).map(function(e){ return e.codigo; });
    }, null, null, 'Todos os equipamentos');

    if(restrito){
      var ord = getOrdem(state.operadorOrdemId);
      ordemInput.value = ord ? ordemLabel(ord) : 'Ordem atual';
      ordemInput.readOnly = true;
      ordemNumeroInput.value = ord && ord.numero ? ord.numero : '';
      ordemNumeroInput.readOnly = true;
      return;
    }
    ordemInput.readOnly = false;
    ordemNumeroInput.readOnly = false;
    wireOrdemTrio('filtroApOrdemNumero', 'filtroApOrdem', null, function(){
      var ordensFiltradas = clienteRestrito ? state.ordens.filter(function(o){ return o.cliente===clienteRestrito; }) : state.ordens;
      var equipAtualId = resolverEquipFiltro('filtroApEquip');
      if(equipAtualId){
        ordensFiltradas = ordensFiltradas.filter(function(o){ return state.apropriacoes.some(function(a){ return a.equipamentoId===equipAtualId && a.ordemId===o.id; }); });
      }
      return ordensFiltradas.slice().sort(function(a,b){ var c=a.cliente.localeCompare(b.cliente,'pt-BR'); return c!==0?c:a.nome.localeCompare(b.nome,'pt-BR'); });
    }, renderApropriacoesTable);
  }

  // Valor exibido de cada coluna do Histórico de Apropriações, por linha — usado tanto pra
  // montar a lista de opções do filtro estilo Excel quanto pra aplicar o filtro selecionado.
  function valoresColunaApropriacao(a){
    var eq = getEquip(a.equipamentoId);
    var ord = getOrdem(a.ordemId);
    var refeicaoTxt = a.tipoIntervalo==='Sem intervalo' ? 'Sem intervalo' : (a.intervaloInicio&&a.intervaloFim ? a.intervaloInicio+'–'+a.intervaloFim : '—');
    var paradasManutencao = (a.paradas||[]).filter(function(p){ return isMotivoManutencao(p.motivo); });
    var pmInicial = paradasManutencao.length ? paradasManutencao[0].inicio : null;
    var pmFinal = paradasManutencao.length ? paradasManutencao[paradasManutencao.length-1].termino : null;
    var pmTotal = horasManutencao(a);
    return {
      pd: a.numeroPD||'—',
      cliente: (ord?((clienteNumero(ord.cliente)?clienteNumero(ord.cliente)+' ':'')+ord.cliente):'—'),
      nordem: (ord&&ord.numero)?ord.numero:'—',
      descordem: ord?ord.nome:'—',
      equip: eq?eq.codigo:'—',
      data: a.data ? brDate(a.data) : '—',
      inicio: a.entrada||'—',
      termino: a.saida||'—',
      refeicao: refeicaoTxt,
      horas: brNum(a.horasOperador,2),
      hi: brNum(a.horimetroInicialEfetivo!==undefined?a.horimetroInicialEfetivo:a.horimetroInicial,1),
      hf: brNum(a.horimetroFinalEfetivo!==undefined?a.horimetroFinalEfetivo:a.horimetroFinal,1),
      ht: brNum(a.horasHorimetro,2),
      pmi: pmInicial||'—',
      pmf: pmFinal||'—',
      pmt: pmTotal>0?brNum(pmTotal,2):'—',
      funcionario: a.operador||'—',
      obs: a.observacao||'—'
    };
  }

  /* ============ FILTRO DE COLUNA ESTILO EXCEL (genérico, reusado em várias tabelas) ============
     Cada tabela que quiser esse filtro registra via registrarFiltroTabela(id, getItens, valoresFn,
     rerenderFn) — getItens devolve a lista completa (não filtrada) de onde tirar os valores
     distintos, valoresFn(item) devolve {coluna: valorExibido} pra cada linha, rerenderFn é a
     função de render da própria tabela (chamada depois de aplicar/limpar um filtro). No render da
     tabela, aplique com: lista = aplicaColFiltrosTabela('id', lista); e chame
     marcarBotoesFiltroAtivos('id'); depois de montar as linhas. */
  var colFiltrosPorTabela = {}; // { tabelaId: { col: Set(valores selecionados) } }
  var cfpTabelaAberta = null, cfpColunaAberta = null;
  var REGISTROS_FILTRO_TABELA = {};

  function registrarFiltroTabela(tabelaId, getItens, valoresFn, rerenderFn){
    REGISTROS_FILTRO_TABELA[tabelaId] = {getItens:getItens, valores:valoresFn, rerender:rerenderFn};
  }
  function aplicaColFiltrosTabela(tabelaId, lista){
    var filtros = colFiltrosPorTabela[tabelaId];
    if(!filtros || !Object.keys(filtros).length) return lista;
    var valoresFn = REGISTROS_FILTRO_TABELA[tabelaId].valores;
    return lista.filter(function(item){
      var valores = valoresFn(item);
      for(var col in filtros){ if(!filtros[col].has(valores[col])) return false; }
      return true;
    });
  }
  function marcarBotoesFiltroAtivos(tabelaId){
    var filtros = colFiltrosPorTabela[tabelaId] || {};
    document.querySelectorAll('.th-filtro-btn[data-tabela="'+tabelaId+'"]').forEach(function(btn){
      btn.classList.toggle('ativo', !!filtros[btn.getAttribute('data-col')]);
    });
  }
  function fecharColFiltroPopover(){
    document.getElementById('colFiltroPopover').style.display = 'none';
    cfpTabelaAberta = null; cfpColunaAberta = null;
  }
  function abrirColFiltroPopover(tabelaId, col, label, btnEl){
    cfpTabelaAberta = tabelaId; cfpColunaAberta = col;
    var reg = REGISTROS_FILTRO_TABELA[tabelaId];
    var pop = document.getElementById('colFiltroPopover');
    document.getElementById('cfpHeader').textContent = 'Filtrar: ' + label;
    var todosValores = Array.from(new Set(reg.getItens().map(function(item){ return reg.valores(item)[col]; }))).sort(function(a,b){ return String(a).localeCompare(String(b),'pt-BR',{numeric:true}); });
    if(!colFiltrosPorTabela[tabelaId]) colFiltrosPorTabela[tabelaId] = {};
    var selecionados = colFiltrosPorTabela[tabelaId][col] || new Set(todosValores);
    function renderLista(termoBusca){
      var lista = document.getElementById('cfpLista');
      var termo = (termoBusca||'').toLowerCase();
      var visiveis = todosValores.filter(function(v){ return String(v).toLowerCase().indexOf(termo)>-1; });
      if(visiveis.length===0){ lista.innerHTML = '<div class="cfp-vazio">Nenhum valor encontrado.</div>'; return; }
      lista.innerHTML = visiveis.map(function(v, idx){
        var checked = selecionados.has(v) ? 'checked' : '';
        return '<label class="cfp-item"><input type="checkbox" data-valor-idx="'+idx+'" '+checked+'> '+esc(String(v))+'</label>';
      }).join('');
      lista.querySelectorAll('input[type="checkbox"]').forEach(function(cb, idx){
        cb.addEventListener('change', function(){
          var v = visiveis[idx];
          if(cb.checked) selecionados.add(v); else selecionados.delete(v);
        });
      });
    }
    renderLista('');
    document.getElementById('cfpBusca').value = '';
    document.getElementById('cfpBusca').oninput = function(){ renderLista(this.value); };
    document.getElementById('cfpSelTodos').onclick = function(){ todosValores.forEach(function(v){ selecionados.add(v); }); renderLista(document.getElementById('cfpBusca').value); };
    document.getElementById('cfpLimparSel').onclick = function(){ selecionados.clear(); renderLista(document.getElementById('cfpBusca').value); };
    document.getElementById('cfpCancelar').onclick = fecharColFiltroPopover;
    document.getElementById('cfpAplicar').onclick = function(){
      if(selecionados.size >= todosValores.length) delete colFiltrosPorTabela[tabelaId][col];
      else colFiltrosPorTabela[tabelaId][col] = selecionados;
      fecharColFiltroPopover();
      reg.rerender();
    };
    pop.style.top = '-9999px';
    pop.style.display = 'flex';
    var r = btnEl.getBoundingClientRect();
    var popW = 240;
    var popH = pop.getBoundingClientRect().height;
    var left = Math.min(r.left, window.innerWidth - popW - 12);
    pop.style.left = Math.max(8, left) + 'px';
    var top = r.bottom + 4;
    if(top + popH > window.innerHeight - 8) top = Math.max(8, r.top - popH - 4);
    pop.style.top = top + 'px';
  }

  document.addEventListener('click', function(e){
    var btn = e.target.closest('.th-filtro-btn');
    if(btn){
      e.stopPropagation();
      var tabelaId = btn.getAttribute('data-tabela'), col = btn.getAttribute('data-col');
      if(cfpTabelaAberta===tabelaId && cfpColunaAberta===col){ fecharColFiltroPopover(); return; }
      abrirColFiltroPopover(tabelaId, col, btn.getAttribute('data-label'), btn);
      return;
    }
    var pop = document.getElementById('colFiltroPopover');
    if(pop.style.display==='none') return;
    if(e.target.closest('#colFiltroPopover')) return;
    fecharColFiltroPopover();
  });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') fecharColFiltroPopover(); });

  // Lançamentos em andamento (rascunhos) não entram na tabela/exportação/contas do Histórico —
  // aparecem só neste painel à parte, pra não arriscar dado incompleto entrando em Consolidado,
  // Faturamento ou Dashboard antes de concluído.
  function renderApRascunhosPanel(){
    var painel = document.getElementById('apRascunhosPanel');
    if(!painel) return;
    var clienteRestrito = (state.perfil==='campo' && state.operadorClienteRestrito) ? state.operadorClienteRestrito : null;
    var restrito = (state.perfil==='campo' && state.operadorOrdemId && !clienteRestrito);
    var lista = state.apropriacoesRascunhos.filter(function(a){
      if(clienteRestrito){
        var ord = getOrdem(a.ordemId);
        if(!ord || ord.cliente!==clienteRestrito) return false;
      } else if(restrito && a.ordemId!==state.operadorOrdemId){
        return false;
      }
      return true;
    }).sort(function(a,b){ return a.data < b.data ? 1 : -1; });
    if(lista.length===0){ painel.innerHTML = ''; return; }
    painel.innerHTML = '<div class="card" style="background:#FFF3CD;border-color:#F1DDA0;">' +
      '<h2 style="margin:0 0 10px;">Lançamentos em andamento ('+lista.length+')</h2>' +
      lista.map(function(a){
        var eq = getEquip(a.equipamentoId);
        var ord = getOrdem(a.ordemId);
        return '<div class="consol-line" style="border-top:1px solid #F1DDA0;padding-top:8px;margin-top:8px;">' +
          '<span>'+esc(a.operador||'—')+' · '+brDate(a.data)+' · '+esc(eq?eq.codigo:'—')+' · '+esc(ord?ordemLabel(ord):'—')+' · rodada '+(a.rodadas||1)+' de até 4</span>' +
          '<b><button type="button" class="btn-ghost ap-rascunho-continuar" data-id="'+a.id+'" style="padding:2px 8px;">Continuar</button></b>' +
        '</div>';
      }).join('') +
    '</div>';
    painel.querySelectorAll('.ap-rascunho-continuar').forEach(function(btn){
      btn.addEventListener('click', function(){
        var rascunho = state.apropriacoesRascunhos.filter(function(a){ return a.id===btn.getAttribute('data-id'); })[0];
        if(!rascunho) return;
        switchView('apropriacao');
        renderApropriacaoForm(rascunho, true);
      });
    });
  }

  function renderApropriacoesTable(){
    renderApRascunhosPanel();
    recalcularHorimetrosEfetivos();
    populateApFilters();
    var resumoEl = document.getElementById('historicoAlertaResumo');
    if(resumoEl){
      var apropsComAlerta = state.apropriacoes.filter(function(a){ return typeof a.saltoHorimetro==='number' || typeof a.excedeuJornada==='number'; });
      var totalAlertas = apropsComAlerta.length;
      if(totalAlertas>0){
        var codigosEquip = Array.from(new Set(apropsComAlerta.map(function(a){
          var eq = getEquip(a.equipamentoId);
          return eq ? eq.codigo : null;
        }).filter(Boolean))).sort();
        var listaEquip = codigosEquip.length
          ? codigosEquip.map(function(c){ return '<span class="plate" style="background:rgba(255,255,255,0.2);color:#fff;">'+esc(c)+'</span>'; }).join(' ')
          : '<span class="muted-tag" style="color:#fff;">(equipamento removido)</span>';
        resumoEl.innerHTML = '<div style="background:#B42318;color:#fff;padding:10px 16px;border-radius:8px;font-weight:700;font-size:13px;margin-bottom:14px;">' +
          '⚠ '+totalAlertas+' lançamento(s) com salto de horímetro (&gt;13h) e/ou jornada acima de 12h aguardando revisão da Controladoria — procure pela marcação vermelha na tabela.' +
          '<div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap;align-items:center;font-weight:400;">Equipamento(s): '+listaEquip+'</div>' +
        '</div>';
      } else {
        resumoEl.innerHTML = '';
      }
    }
    var clienteRestrito = (state.perfil==='campo' && state.operadorClienteRestrito) ? state.operadorClienteRestrito : null;
    var restrito = (state.perfil==='campo' && state.operadorOrdemId && !clienteRestrito);
    var ordemIdsCliente = clienteRestrito ? state.ordens.filter(function(o){ return o.cliente===clienteRestrito; }).map(function(o){ return o.id; }) : null;
    var equipId = resolverEquipFiltro('filtroApEquip');
    var ordemId = restrito ? state.operadorOrdemId : resolverOrdemFiltro('filtroApOrdem');
    var operadorFiltro = document.getElementById('filtroApOperador').value.trim();
    var pdFiltro = normalizarEspacos(document.getElementById('filtroApPD').value).toLowerCase();
    var de = document.getElementById('filtroApDe').value;
    var ate = document.getElementById('filtroApAte').value;
    var list = state.apropriacoes.filter(function(a){
      if(ordemIdsCliente && ordemIdsCliente.indexOf(a.ordemId)===-1) return false;
      if(equipId && a.equipamentoId!==equipId) return false;
      if(ordemId && a.ordemId!==ordemId) return false;
      if(operadorFiltro && a.operador!==operadorFiltro) return false;
      if(pdFiltro && (a.numeroPD||'').toLowerCase().indexOf(pdFiltro)===-1) return false;
      if(de && a.data < de) return false;
      if(ate && a.data > ate) return false;
      return true;
    }).sort(function(a,b){ return a.data < b.data ? 1 : -1; });

    list = aplicaColFiltrosTabela('apropriacoes', list);
    marcarBotoesFiltroAtivos('apropriacoes');

    var body = document.getElementById('apropriacoesBody');
    var foot = document.getElementById('apropriacoesFoot');
    var topoTotal = document.getElementById('apropriacoesTopoTotal');
    var totalCols = isControladoriaLevel() ? 19 : 18;
    if(list.length===0){
      body.innerHTML = '<tr class="empty-row"><td colspan="'+totalCols+'">Nenhum lançamento encontrado para os filtros selecionados.</td></tr>';
      foot.innerHTML = '';
      topoTotal.innerHTML = '';
      return;
    }
    body.innerHTML = list.map(function(a){
      var eq = getEquip(a.equipamentoId);
      var ord = getOrdem(a.ordemId);
      var refeicaoTxt = a.tipoIntervalo==='Sem intervalo' ? 'Sem intervalo' : (a.intervaloInicio&&a.intervaloFim ? a.intervaloInicio+'–'+a.intervaloFim : '—');
      var paradasManutencao = (a.paradas||[]).filter(function(p){ return isMotivoManutencao(p.motivo); });
      var pmInicial = paradasManutencao.length ? paradasManutencao[0].inicio : null;
      var pmFinal = paradasManutencao.length ? paradasManutencao[paradasManutencao.length-1].termino : null;
      var pmTotal = horasManutencao(a);
      var acoesTd = isControladoriaLevel()
        ? '<td><button class="btn btn-ghost btn-sm" data-det-ap="'+a.id+'" title="Detalhes"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8Z"/><circle cx="12" cy="12" r="3"/></svg></button>' +
          '<button class="btn btn-ghost btn-sm" data-edit-ap="'+a.id+'" title="Editar"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg></button>' +
          '<button class="btn btn-danger-ghost btn-sm" data-del-ap="'+a.id+'" title="Remover"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg></button></td>'
        : '';
      var temAlertaHorimetro = typeof a.saltoHorimetro==='number';
      var temAlertaJornada = typeof a.excedeuJornada==='number';
      var temAlerta = temAlertaHorimetro || temAlertaJornada;
      var textoAlerta = [];
      if(temAlertaHorimetro) textoAlerta.push('Salto de '+brNum(a.saltoHorimetro,1)+'h no horímetro desde o lançamento anterior');
      if(temAlertaJornada) textoAlerta.push('Jornada '+brNum(a.excedeuJornada,1)+'h acima do limite de 12h');
      var rotuloAlerta = temAlertaHorimetro && temAlertaJornada
        ? '⚠ +'+brNum(a.saltoHorimetro,1)+'h / +'+brNum(a.excedeuJornada,1)+'h'
        : (temAlertaHorimetro ? '⚠ +'+brNum(a.saltoHorimetro,1)+'h' : '⚠ +'+brNum(a.excedeuJornada,1)+'h');
      var alertaBadge = temAlerta ? (isControladoriaLevel()
        ? '<button data-resolver-alerta="'+a.id+'" style="display:inline-block;background:#B42318;color:#fff;font-weight:700;font-size:10.5px;padding:2px 6px;border-radius:4px;margin-left:6px;white-space:nowrap;border:none;cursor:pointer;" title="'+esc(textoAlerta.join(' · '))+' — clique para marcar como revisado.">'+rotuloAlerta+'</button>'
        : '<span style="display:inline-block;background:#B42318;color:#fff;font-weight:700;font-size:10.5px;padding:2px 6px;border-radius:4px;margin-left:6px;white-space:nowrap;" title="'+esc(textoAlerta.join(' · '))+'">'+rotuloAlerta+'</span>') : '';
      return '<tr'+(temAlerta?' style="background:#FEF1F1;"':'')+'>' +
        '<td>'+esc(a.numeroPD||'—')+alertaBadge+'</td>' +
        '<td>'+(ord?(clienteNumero(ord.cliente)?esc(clienteNumero(ord.cliente))+' ':''):'')+(ord?esc(ord.cliente):'—')+'</td>' +
        '<td>'+(ord&&ord.numero?esc(ord.numero):'—')+'</td>' +
        '<td>'+(ord?esc(ord.nome):'<span class="muted-tag">(removida)</span>')+'</td>' +
        '<td>'+(eq?'<span class="plate">'+esc(eq.codigo)+'</span>':'<span class="muted-tag">(removido)</span>')+'</td>' +
        '<td>'+brDate(a.data)+(a.dataFim && a.dataFim!==a.data ? '<br><span class="muted-tag">→ '+brDate(a.dataFim)+'</span>' : '')+'</td>' +
        '<td>'+esc(a.entrada||'—')+'</td>' +
        '<td>'+esc(a.saida||'—')+'</td>' +
        '<td>'+esc(refeicaoTxt)+'</td>' +
        '<td class="num">'+brNum(a.horasOperador,2)+'</td>' +
        '<td class="num">'+brNum(a.horimetroInicialEfetivo!==undefined?a.horimetroInicialEfetivo:a.horimetroInicial,1)+(a.horimetroInicial===0&&a.horimetroInicialEfetivo!==0?' <span class="muted-tag" title="Herdado do lançamento anterior">†</span>':'')+'</td>' +
        '<td class="num">'+brNum(a.horimetroFinalEfetivo!==undefined?a.horimetroFinalEfetivo:a.horimetroFinal,1)+(a.horimetroFinal===0&&a.horimetroFinalEfetivo!==0?' <span class="muted-tag" title="Herdado do lançamento anterior">†</span>':'')+'</td>' +
        '<td class="num">'+brNum(a.horasHorimetro,2)+'</td>' +
        '<td class="num">'+(pmInicial||'—')+'</td><td class="num">'+(pmFinal||'—')+'</td><td class="num">'+(pmTotal>0?brNum(pmTotal,2):'—')+'</td>' +
        '<td>'+esc(a.operador||'—')+'</td>' +
        '<td>'+esc(a.observacao||'—')+'</td>' +
        acoesTd +
      '</tr>';
    }).join('');
    var totalOperador = list.reduce(function(s,a){ return s+a.horasOperador; },0);
    var totalHorimetro = horimetroAgregado(list);
    var totalPM = list.reduce(function(s,a){ return s+horasManutencao(a); },0);
    var limites = horimetroLimitesLista(list);
    var totalRowHtml = '<tr style="font-weight:700;background:#F7FAFC;">' +
      '<td colspan="9">Total do período filtrado'+(limites.inicial===null?' <span class="muted-tag" style="font-weight:400;">(selecione um equipamento para ver o horímetro inicial/final)</span>':'')+'</td>' +
      '<td class="num">'+brNum(totalOperador,2)+'</td>' +
      '<td class="num">'+(limites.inicial!==null?brNum(limites.inicial,1):'—')+'</td>' +
      '<td class="num">'+(limites.final!==null?brNum(limites.final,1):'—')+'</td>' +
      '<td class="num">'+brNum(totalHorimetro,2)+'</td>' +
      '<td class="num">—</td><td class="num">—</td><td class="num">'+brNum(totalPM,2)+'</td>' +
      '<td colspan="2"></td>' + (isControladoriaLevel() ? '<td></td>' : '') + '</tr>';
    foot.innerHTML = totalRowHtml;
    topoTotal.innerHTML = totalRowHtml;
    body.querySelectorAll('[data-del-ap]').forEach(function(btn){ btn.onclick = function(){ deleteApropriacao(btn.getAttribute('data-del-ap')); }; });
    body.querySelectorAll('[data-resolver-alerta]').forEach(function(btn){
      btn.onclick = function(){
        var id = btn.getAttribute('data-resolver-alerta');
        confirmModal('Marcar alerta como revisado', 'Confirma que já revisou o(s) alerta(s) deste lançamento (salto de horímetro e/ou jornada acima de 12h)? O alerta some da lista depois de confirmado.', async function(){
          state.apropriacoes = state.apropriacoes.map(function(a){ return a.id===id ? Object.assign({}, a, {saltoHorimetro: null, excedeuJornada: null}) : a; });
          await saveList('apropriacoes_v7', state.apropriacoes);
          toast('Alerta marcado como revisado.');
          renderApropriacoesTable();
        });
      };
    });
    body.querySelectorAll('[data-det-ap]').forEach(function(btn){
      btn.onclick = function(){
        var ap = state.apropriacoes.filter(function(a){ return a.id===btn.getAttribute('data-det-ap'); })[0];
        if(ap) openDetalheApropriacao(ap);
      };
    });
    body.querySelectorAll('[data-edit-ap]').forEach(function(btn){
      btn.onclick = function(){ editarApropriacao(btn.getAttribute('data-edit-ap')); };
    });
  }

  /* ============ RENDER: DASHBOARD ============ */
  function isCurrentMonth(iso){
    var now = new Date();
    var ym = now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
    return iso.indexOf(ym)===0;
  }

  function renderKpiRowStatus(){
    var total = state.equipamentos.length;
    var tiposDistintos = new Set(state.equipamentos.map(function(e){ return e.tipo; })).size;
    var lista = dashboardApropriacoesFiltradas();
    var equipAtivos = new Set(lista.map(function(a){ return a.equipamentoId; })).size;
    var totalClientes = CLIENTES.length;
    var clientesAtendidos = new Set(lista.map(function(a){ var o=getOrdem(a.ordemId); return o?o.cliente:null; }).filter(Boolean)).size;
    function kpi(label, value){
      return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value">'+value+'</div></div>';
    }
    function kpiFracao(label, valor, totalRef){
      var pct = totalRef>0 ? Math.round(valor/totalRef*100) : 0;
      return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div>' +
        '<div class="kpi-value">'+valor+' <span class="muted-tag" style="font-size:13px;font-weight:400;">/ '+totalRef+'</span></div>' +
        '<div class="kpi-gauge"><div class="kpi-gauge-fill" style="width:'+pct+'%;background:'+effColor(pct)+';"></div></div>' +
      '</div>';
    }
    document.getElementById('kpiRow').innerHTML =
      kpi('Total de equipamentos', total) +
      kpi('Tipos distintos', tiposDistintos) +
      kpiFracao('Equipamentos com lançamento no período', equipAtivos, total) +
      kpiFracao('Clientes atendidos no período', clientesAtendidos, totalClientes);
  }

  function renderKpiRowHoras(){
    var doMes = dashboardApropriacoesFiltradas();
    var totalOperador = doMes.reduce(function(s,a){ return s+a.horasOperador; },0);
    var totalHorimetro = horimetroAgregado(doMes);
    var totalParada = doMes.reduce(function(s,a){ return s+paradasTotal(a); },0);
    var totalProducao = dashboardProducaoToneladas().reduce(function(s,p){ return s+(p.valor||0); },0);
    var totalNaoApontado = totalOperador - totalHorimetro - totalParada;
    var eficiencia = totalOperador>0 ? Math.round(totalHorimetro/totalOperador*100) : 0;
    function kpi(label, value, pct, color){
      return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value">'+value+'</div>' +
        (pct!==null ? ('<div class="kpi-gauge"><div class="kpi-gauge-fill" style="width:'+Math.min(pct,100)+'%;background:'+color+';"></div></div><div class="kpi-ticks">'+Array(11).fill('<span></span>').join('')+'</div>') : '') +
      '</div>';
    }
    document.getElementById('kpiRowHoras').innerHTML =
      kpi('Horas de horímetro', brNum(totalHorimetro,1), null, '') +
      kpi('Horas programadas', brNum(totalOperador,1), null, '') +
      kpi('Horas de parada', brNum(totalParada,1), null, '') +
      kpi('Diferença não apontada', brNum(totalNaoApontado,1), null, '') +
      kpi('Produção (t)', brNum(totalProducao,1), null, '') +
      kpi('Eficiência (horímetro / programado)', eficiencia+'%', eficiencia, effColor(eficiencia));
  }

  var chartInstances = {};

  // Gráfico de barras horizontais em SVG puro — sem dependência externa.
  function svgColunaMetaChart(valores, meta, color, sufixo){
    var n = valores.length;
    if(n===0) return '<div class="empty-state" style="padding:20px;">Sem dados para exibir.</div>';
    var max = Math.max.apply(null, valores.concat([meta||0])) * 1.18 || 1;
    var chartH = 220, chartW = Math.max(n*24, 380), padL = 50, padB = 22, padT = 16;
    var totalW = padL + chartW + 46, totalH = chartH + padT + padB;
    var gap = chartW / n;
    var barW = Math.max(gap*0.6, 3);
    var bars = valores.map(function(v, i){
      var x = padL + i*gap + (gap-barW)/2;
      var h = (v/max)*chartH;
      var y = padT + (chartH - h);
      return '<g>' +
        (v>0 ? '<rect x="'+x+'" y="'+y+'" width="'+barW+'" height="'+h+'" fill="'+color+'" rx="2"><title>Dia '+String(i+1).padStart(2,'0')+': '+brNum(v,2)+' '+sufixo+'</title></rect>' : '') +
      '</g>';
    }).join('');
    var labels = valores.map(function(v,i){
      var x = padL + i*gap + gap/2;
      if(n>20 && (i+1)%2===0) return '';
      return '<text x="'+x+'" y="'+(padT+chartH+15)+'" font-size="9" fill="#8895A3" font-family="Arial" text-anchor="middle">'+String(i+1).padStart(2,'0')+'</text>';
    }).join('');
    var metaLine = '';
    if(meta>0){
      var yMeta = padT + (chartH - (meta/max)*chartH);
      metaLine = '<line x1="'+padL+'" y1="'+yMeta+'" x2="'+(padL+chartW)+'" y2="'+yMeta+'" stroke="#16232F" stroke-width="1.5" stroke-dasharray="6,4"/>' +
        '<text x="'+(padL+chartW+4)+'" y="'+(yMeta+4)+'" font-size="10" fill="#16232F" font-family="Arial">Meta</text>';
    }
    var axisY = '<line x1="'+padL+'" y1="'+padT+'" x2="'+padL+'" y2="'+(padT+chartH)+'" stroke="#D7DEE5"/>';
    var axisX = '<line x1="'+padL+'" y1="'+(padT+chartH)+'" x2="'+(padL+chartW)+'" y2="'+(padT+chartH)+'" stroke="#D7DEE5"/>';
    var maxLabel = '<text x="'+(padL-6)+'" y="'+(padT+5)+'" font-size="9.5" fill="#8895A3" font-family="Arial" text-anchor="end">'+brNum(max,0)+'</text>';
    var zeroLabel = '<text x="'+(padL-6)+'" y="'+(padT+chartH+3)+'" font-size="9.5" fill="#8895A3" font-family="Arial" text-anchor="end">0</text>';
    return '<svg viewBox="0 0 '+totalW+' '+totalH+'" width="100%" height="260" preserveAspectRatio="xMinYMin meet">'+axisY+axisX+maxLabel+zeroLabel+bars+labels+metaLine+'</svg>';
  }

  function svgBarChartHtml(entries, color, valueFmt){
    if(!entries || entries.length===0) return '<div class="empty-state" style="padding:20px;">Sem dados para exibir.</div>';
    valueFmt = valueFmt || function(v){ return brNum(v,1); };
    var max = Math.max.apply(null, entries.map(function(e){ return e.value; })) || 1;
    // leftW se ajusta ao maior rótulo (em vez de truncar em 18 caracteres) — largura aproximada
    // de ~7px por caractere em Arial 11.5px, com um teto generoso pra não esticar demais o
    // gráfico em casos de nome extremo.
    var maiorLabel = entries.reduce(function(m,e){ return Math.max(m, String(e.label).length); }, 0);
    var rowH = 24, gap = 8, leftW = Math.max(90, Math.min(280, 24 + maiorLabel*7)), chartW = 300, rightW = 70;
    var totalW = leftW + chartW + rightW;
    var totalH = entries.length*(rowH+gap);
    var rows = entries.map(function(e, i){
      var y = i*(rowH+gap);
      var barW = Math.max((e.value/max)*chartW, 2);
      var zebra = i%2===1 ? '<rect x="0" y="'+(y-gap/2)+'" width="'+totalW+'" height="'+(rowH+gap)+'" fill="#F7F9FB"/>' : '';
      return '<g>' +
        zebra +
        '<text x="'+(leftW-8)+'" y="'+(y+rowH*0.68)+'" font-size="11.5" fill="#5C6B78" font-family="Arial" text-anchor="end">'+esc(e.label)+'</text>' +
        '<rect x="'+leftW+'" y="'+y+'" width="'+chartW+'" height="'+rowH+'" rx="4" fill="#EDF1F4"/>' +
        '<rect x="'+leftW+'" y="'+y+'" width="'+barW+'" height="'+rowH+'" rx="4" fill="'+color+'"><title>'+esc(e.label)+': '+esc(valueFmt(e.value))+'</title></rect>' +
        '<text x="'+(leftW+barW+8)+'" y="'+(y+rowH*0.68)+'" font-size="11.5" fill="#16232F" font-family="ui-monospace,monospace">'+esc(valueFmt(e.value))+'</text>' +
      '</g>';
    }).join('');
    // height="100%" esticava o gráfico inteiro (inclusive a espessura das barras) pra preencher
    // sempre os 220px do card, mesmo com poucos itens — deixando as barras "grossas" quando só
    // tinha 1-3 clientes/motivos. Fixando a altura real do SVG em totalH, a barra sempre fica
    // com a espessura nativa (rowH), e o card (com max-height no lugar de height fixo) que se
    // ajusta ao conteúdo — com rolagem só quando tem muitos itens.
    return '<svg viewBox="0 0 '+totalW+' '+totalH+'" width="100%" height="'+totalH+'" preserveAspectRatio="xMinYMin meet">'+rows+'</svg>';
  }

  function renderClientBars(){
    var porCliente = {};
    dashboardApropriacoesFiltradas().forEach(function(a){
      var ord = getOrdem(a.ordemId);
      if(!ord) return;
      if(!porCliente[ord.cliente]) porCliente[ord.cliente] = [];
      porCliente[ord.cliente].push(a);
    });
    var entries = Object.keys(porCliente).map(function(k){ return {label:k, value:horimetroAgregado(porCliente[k])}; }).sort(function(a,b){ return b.value-a.value; }).slice(0,10);
    document.getElementById('clientChart').innerHTML = svgBarChartHtml(entries, '#2E75B6', function(v){ return brNum(v,1)+'h'; });
  }

  function clienteResumoLinhas(){
    var porCliente = {};
    dashboardApropriacoesFiltradas().forEach(function(a){
      var ord = getOrdem(a.ordemId);
      if(!ord) return;
      if(!porCliente[ord.cliente]) porCliente[ord.cliente] = [];
      porCliente[ord.cliente].push(a);
    });
    return Object.keys(porCliente).map(function(cliente){
      var lista = porCliente[cliente];
      return {
        cliente: cliente,
        dias: new Set(lista.map(function(a){ return a.data; })).size,
        equipamentos: new Set(lista.map(function(a){ return a.equipamentoId; })).size,
        operadores: new Set(lista.map(function(a){ return a.operador; }).filter(Boolean)).size,
        horimetro: horimetroAgregado(lista),
        operadorHoras: lista.reduce(function(s,a){ return s+a.horasOperador; },0)
      };
    }).sort(function(a,b){ return b.horimetro-a.horimetro; });
  }

  function renderClienteResumo(){
    var body = document.getElementById('clienteResumoBody');
    if(!body) return;
    var linhas = clienteResumoLinhas();

    function topo(campo){
      return linhas.slice().sort(function(a,b){ return b[campo]-a[campo]; }).slice(0,10).map(function(l){ return {label:l.cliente, value:l[campo]}; });
    }
    document.getElementById('clienteChartDias').innerHTML = svgBarChartHtml(topo('dias'), '#4C9F70', function(v){ return v+' dias'; });
    document.getElementById('clienteChartEquip').innerHTML = svgBarChartHtml(topo('equipamentos'), '#8B6FB0', function(v){ return String(v); });
    document.getElementById('clienteChartOperadores').innerHTML = svgBarChartHtml(topo('operadores'), '#3D8FA6', function(v){ return String(v); });
    document.getElementById('clienteChartHorasOp').innerHTML = svgBarChartHtml(topo('operadorHoras'), '#E8833A', function(v){ return brNum(v,1)+'h'; });

    if(linhas.length===0){
      body.innerHTML = '<tr class="empty-row"><td colspan="6">Nenhum lançamento encontrado para os filtros selecionados.</td></tr>';
      return;
    }
    body.innerHTML = linhas.map(function(l){
      return '<tr><td>'+(clienteNumero(l.cliente)?esc(clienteNumero(l.cliente))+' ':'')+esc(l.cliente)+'</td>' +
        '<td class="num">'+l.dias+'</td><td class="num">'+l.equipamentos+'</td><td class="num">'+l.operadores+'</td>' +
        '<td class="num">'+brNum(l.horimetro,2)+'</td><td class="num">'+brNum(l.operadorHoras,2)+'</td></tr>';
    }).join('');
  }

  // Soma as horas de manutenção agrupadas pelas 3 categorias (Corretiva/Preventiva/Inspeção),
  // usada no Dashboard e nos Indicadores pra dar visão separada, não só o total genérico.
  function horasPorTipoManutencao(lista){
    var somas = {'Manutenção Corretiva':0, 'Manutenção Preventiva':0, 'Manutenção de Inspeção':0};
    var contagens = {'Manutenção Corretiva':0, 'Manutenção Preventiva':0, 'Manutenção de Inspeção':0};
    (lista||[]).forEach(function(a){
      (a.paradas||[]).forEach(function(p){
        var tipo = tipoManutencaoDoMotivo(p.motivo);
        if(tipo && somas[tipo]!==undefined){ somas[tipo] += (p.horas||0); contagens[tipo]++; }
      });
    });
    return {somas:somas, contagens:contagens};
  }

  function renderParadaChart(){
    var map = {};
    state.motivosParada.forEach(function(m){ map[m.descricao]=0; });
    dashboardApropriacoesFiltradas().forEach(function(a){ (a.paradas||[]).forEach(function(p){ map[p.motivo] = (map[p.motivo]||0) + p.horas; }); });
    var entries = Object.keys(map).map(function(k){ return {label:k, value:map[k]}; }).filter(function(e){ return e.value>0; }).sort(function(a,b){ return b.value-a.value; });
    document.getElementById('paradaChart').innerHTML = svgBarChartHtml(entries, '#E0972A', function(v){ return brNum(v,1)+'h'; });
  }

  function renderManutencaoPorTipo(targetId, lista){
    var el = document.getElementById(targetId);
    if(!el) return;
    var r = horasPorTipoManutencao(lista);
    function kpi(label, horas, paradas){
      return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value">'+brNum(horas,1)+'h</div>'+
        '<div class="muted-tag" style="margin-top:2px;">'+paradas+' parada'+(paradas===1?'':'s')+'</div></div>';
    }
    el.innerHTML =
      kpi('Corretiva', r.somas['Manutenção Corretiva'], r.contagens['Manutenção Corretiva']) +
      kpi('Preventiva', r.somas['Manutenção Preventiva'], r.contagens['Manutenção Preventiva']) +
      kpi('Inspeção', r.somas['Manutenção de Inspeção'], r.contagens['Manutenção de Inspeção']);
  }

  function renderTendenciaChart(){
    var doMes = dashboardApropriacoesFiltradas();
    var producaoDoMes = dashboardProducaoToneladas();
    var porDia = {};
    doMes.forEach(function(a){
      if(!porDia[a.data]) porDia[a.data] = {horimetro:[], producao:0};
      porDia[a.data].horimetro.push(a);
    });
    producaoDoMes.forEach(function(p){
      if(!porDia[p.data]) porDia[p.data] = {horimetro:[], producao:0};
      porDia[p.data].producao += (p.valor||0);
    });
    var dias = Object.keys(porDia).sort();
    var el = document.getElementById('tendenciaChart');
    if(dias.length===0){ el.innerHTML = '<div class="empty-state" style="padding:20px;">Nenhum lançamento no período selecionado.</div>'; return; }
    var horimetroSerie = dias.map(function(d){ return Math.round(horimetroAgregado(porDia[d].horimetro)*10)/10; });
    var producaoSerie = dias.map(function(d){ return Math.round(porDia[d].producao*10)/10; });
    var w = 480, h = 170, padL = 34, padR = 10, padT = 10, padB = 24;
    var innerW = w-padL-padR, innerH = h-padT-padB;
    var maxH = Math.max.apply(null, horimetroSerie.concat([1]));
    var maxP = Math.max.apply(null, producaoSerie.concat([1]));
    function pathFor(serie, max){
      return serie.map(function(v,i){
        var x = padL + (serie.length>1 ? i/(serie.length-1)*innerW : innerW/2);
        var y = padT + innerH - (v/max*innerH);
        return (i===0?'M':'L')+x.toFixed(1)+','+y.toFixed(1);
      }).join(' ');
    }
    function areaPathFor(serie, max){
      var baseY = (padT+innerH).toFixed(1);
      var lastX = (padL + (serie.length>1 ? innerW : innerW/2)).toFixed(1);
      var firstX = (padL + (serie.length>1 ? 0 : innerW/2)).toFixed(1);
      return pathFor(serie, max)+' L'+lastX+','+baseY+' L'+firstX+','+baseY+' Z';
    }
    var pathH = pathFor(horimetroSerie, maxH);
    var pathP = pathFor(producaoSerie, maxP);
    var areaH = areaPathFor(horimetroSerie, maxH);
    var areaP = areaPathFor(producaoSerie, maxP);
    var gridLines = [0.25,0.5,0.75].map(function(f){
      var y = (padT + innerH*f).toFixed(1);
      return '<line x1="'+padL+'" y1="'+y+'" x2="'+(padL+innerW)+'" y2="'+y+'" stroke="#EEF1F4" stroke-width="1"/>';
    }).join('');
    var pointsH = horimetroSerie.map(function(v,i){
      var x = padL + (horimetroSerie.length>1 ? i/(horimetroSerie.length-1)*innerW : innerW/2);
      var y = padT + innerH - (v/maxH*innerH);
      return '<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="2.6" fill="#2E75B6"><title>'+brDate(dias[i])+': '+brNum(v,1)+'h</title></circle>';
    }).join('');
    var pointsP = producaoSerie.map(function(v,i){
      var x = padL + (producaoSerie.length>1 ? i/(producaoSerie.length-1)*innerW : innerW/2);
      var y = padT + innerH - (v/maxP*innerH);
      return '<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="2.6" fill="#A67900"><title>'+brDate(dias[i])+': '+brNum(v,1)+'t</title></circle>';
    }).join('');
    var xLabels = dias.map(function(d,i){
      if(dias.length>10 && i%Math.ceil(dias.length/8)!==0) return '';
      var x = padL + (dias.length>1 ? i/(dias.length-1)*innerW : innerW/2);
      return '<text x="'+x.toFixed(1)+'" y="'+(h-6)+'" font-size="9" fill="#5C6B78" text-anchor="middle" font-family="Arial">'+brDate(dias[i]).slice(0,5)+'</text>';
    }).join('');
    el.innerHTML =
      '<div class="legend" style="margin-bottom:6px;"><div class="legend-item"><span class="led" style="background:#2E75B6;"></span>Horas de horímetro</div><div class="legend-item"><span class="led" style="background:#A67900;"></span>Produção (t)</div></div>' +
      '<svg viewBox="0 0 '+w+' '+h+'" width="100%" height="140" preserveAspectRatio="xMinYMin meet">' +
        '<defs>' +
          '<linearGradient id="tendGradH" x1="0" y1="0" x2="0" y2="1">' +
            '<stop offset="0%" stop-color="#2E75B6" stop-opacity="0.25"/><stop offset="100%" stop-color="#2E75B6" stop-opacity="0"/>' +
          '</linearGradient>' +
          '<linearGradient id="tendGradP" x1="0" y1="0" x2="0" y2="1">' +
            '<stop offset="0%" stop-color="#A67900" stop-opacity="0.18"/><stop offset="100%" stop-color="#A67900" stop-opacity="0"/>' +
          '</linearGradient>' +
        '</defs>' +
        gridLines +
        '<line x1="'+padL+'" y1="'+padT+'" x2="'+padL+'" y2="'+(padT+innerH)+'" stroke="#DCE3EA"/>' +
        '<line x1="'+padL+'" y1="'+(padT+innerH)+'" x2="'+(padL+innerW)+'" y2="'+(padT+innerH)+'" stroke="#DCE3EA"/>' +
        '<path d="'+areaH+'" fill="url(#tendGradH)" stroke="none"/>' +
        '<path d="'+areaP+'" fill="url(#tendGradP)" stroke="none"/>' +
        '<path d="'+pathH+'" fill="none" stroke="#2E75B6" stroke-width="2"/>' + pointsH +
        '<path d="'+pathP+'" fill="none" stroke="#A67900" stroke-width="2" stroke-dasharray="4 3"/>' + pointsP +
        xLabels +
      '</svg>' +
      '<div class="muted-tag" style="margin-top:4px;">Cada série usa sua própria escala (horas x toneladas) para comparar a tendência.</div>';
  }

  // Duas linhas na MESMA escala (ambas contam "quantidade de equipamentos") -- diferente do
  // gráfico de horímetro/produção acima, que precisa de escalas separadas por medir unidades
  // diferentes. Aqui dá pra comparar direto: quantos equipamentos trabalharam vs quantos tiveram
  // parada de manutenção, dia a dia.
  function renderEquipAtivoManutChart(){
    var doMes = dashboardApropriacoesFiltradas();
    var porDia = {};
    doMes.forEach(function(a){
      if(!a.equipamentoId) return;
      if(!porDia[a.data]) porDia[a.data] = {ativos:new Set(), manutencao:new Set()};
      porDia[a.data].ativos.add(a.equipamentoId);
      var temManut = (a.paradas||[]).some(function(p){ return isMotivoManutencao(p.motivo) && p.horas>0; });
      if(temManut) porDia[a.data].manutencao.add(a.equipamentoId);
    });
    var dias = Object.keys(porDia).sort();
    var el = document.getElementById('equipAtivoManutChart');
    if(!el) return;
    if(dias.length===0){ el.innerHTML = '<div class="empty-state" style="padding:20px;">Nenhum lançamento no período selecionado.</div>'; return; }
    var ativosSerie = dias.map(function(d){ return porDia[d].ativos.size; });
    var manutSerie = dias.map(function(d){ return porDia[d].manutencao.size; });
    var w = 480, h = 170, padL = 30, padR = 10, padT = 10, padB = 24;
    var innerW = w-padL-padR, innerH = h-padT-padB;
    var max = Math.max.apply(null, ativosSerie.concat(manutSerie).concat([1]));
    function pathFor(serie){
      return serie.map(function(v,i){
        var x = padL + (serie.length>1 ? i/(serie.length-1)*innerW : innerW/2);
        var y = padT + innerH - (v/max*innerH);
        return (i===0?'M':'L')+x.toFixed(1)+','+y.toFixed(1);
      }).join(' ');
    }
    function areaPathFor(serie){
      var baseY = (padT+innerH).toFixed(1);
      var lastX = (padL + (serie.length>1 ? innerW : innerW/2)).toFixed(1);
      var firstX = (padL + (serie.length>1 ? 0 : innerW/2)).toFixed(1);
      return pathFor(serie)+' L'+lastX+','+baseY+' L'+firstX+','+baseY+' Z';
    }
    var pathAtivos = pathFor(ativosSerie), pathManut = pathFor(manutSerie);
    var areaAtivos = areaPathFor(ativosSerie), areaManut = areaPathFor(manutSerie);
    var gridLines = [0.25,0.5,0.75].map(function(f){
      var y = (padT + innerH*f).toFixed(1);
      return '<line x1="'+padL+'" y1="'+y+'" x2="'+(padL+innerW)+'" y2="'+y+'" stroke="#EEF1F4" stroke-width="1"/>';
    }).join('');
    var pointsAtivos = ativosSerie.map(function(v,i){
      var x = padL + (ativosSerie.length>1 ? i/(ativosSerie.length-1)*innerW : innerW/2);
      var y = padT + innerH - (v/max*innerH);
      return '<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="2.6" fill="#2E75B6"><title>'+brDate(dias[i])+': '+v+' equipamento(s) ativo(s)</title></circle>';
    }).join('');
    var pointsManut = manutSerie.map(function(v,i){
      var x = padL + (manutSerie.length>1 ? i/(manutSerie.length-1)*innerW : innerW/2);
      var y = padT + innerH - (v/max*innerH);
      return '<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="2.6" fill="#C0392B"><title>'+brDate(dias[i])+': '+v+' equipamento(s) em manutenção</title></circle>';
    }).join('');
    var xLabels = dias.map(function(d,i){
      if(dias.length>10 && i%Math.ceil(dias.length/8)!==0) return '';
      var x = padL + (dias.length>1 ? i/(dias.length-1)*innerW : innerW/2);
      return '<text x="'+x.toFixed(1)+'" y="'+(h-6)+'" font-size="9" fill="#5C6B78" text-anchor="middle" font-family="Arial">'+brDate(dias[i]).slice(0,5)+'</text>';
    }).join('');
    el.innerHTML =
      '<div class="legend" style="margin-bottom:6px;"><div class="legend-item"><span class="led" style="background:#2E75B6;"></span>Equipamentos ativos</div><div class="legend-item"><span class="led" style="background:#C0392B;"></span>Em manutenção</div></div>' +
      '<svg viewBox="0 0 '+w+' '+h+'" width="100%" height="140" preserveAspectRatio="xMinYMin meet">' +
        '<defs>' +
          '<linearGradient id="eqamGradAtivo" x1="0" y1="0" x2="0" y2="1">' +
            '<stop offset="0%" stop-color="#2E75B6" stop-opacity="0.22"/><stop offset="100%" stop-color="#2E75B6" stop-opacity="0"/>' +
          '</linearGradient>' +
          '<linearGradient id="eqamGradManut" x1="0" y1="0" x2="0" y2="1">' +
            '<stop offset="0%" stop-color="#C0392B" stop-opacity="0.18"/><stop offset="100%" stop-color="#C0392B" stop-opacity="0"/>' +
          '</linearGradient>' +
        '</defs>' +
        gridLines +
        '<line x1="'+padL+'" y1="'+padT+'" x2="'+padL+'" y2="'+(padT+innerH)+'" stroke="#DCE3EA"/>' +
        '<line x1="'+padL+'" y1="'+(padT+innerH)+'" x2="'+(padL+innerW)+'" y2="'+(padT+innerH)+'" stroke="#DCE3EA"/>' +
        '<path d="'+areaAtivos+'" fill="url(#eqamGradAtivo)" stroke="none"/>' +
        '<path d="'+areaManut+'" fill="url(#eqamGradManut)" stroke="none"/>' +
        '<path d="'+pathAtivos+'" fill="none" stroke="#2E75B6" stroke-width="2"/>' + pointsAtivos +
        '<path d="'+pathManut+'" fill="none" stroke="#C0392B" stroke-width="2" stroke-dasharray="4 3"/>' + pointsManut +
        xLabels +
      '</svg>' +
      '<div class="muted-tag" style="margin-top:4px;">Mesma escala (quantidade de equipamentos) — comparação direta dia a dia.</div>';
  }

  // Lista, ao lado do gráfico acima, quais equipamentos tiveram parada de manutenção no período
  // filtrado e o total de horas paradas de cada um (soma de todos os lançamentos do período,
  // não só do último) -- identifica quem está puxando a linha vermelha do gráfico pra cima.
  function renderEquipManutPeriodoLista(){
    var el = document.getElementById('equipManutPeriodoLista');
    if(!el) return;
    var porEquip = {};
    dashboardApropriacoesFiltradas().forEach(function(a){
      if(!a.equipamentoId) return;
      var horasManut = (a.paradas||[]).filter(function(p){ return isMotivoManutencao(p.motivo) && p.horas>0; }).reduce(function(s,p){ return s+p.horas; },0);
      if(horasManut<=0) return;
      if(!porEquip[a.equipamentoId]) porEquip[a.equipamentoId] = {horas:0, ultimaData:a.data, ordemId:a.ordemId};
      porEquip[a.equipamentoId].horas += horasManut;
      if(a.data>=porEquip[a.equipamentoId].ultimaData){ porEquip[a.equipamentoId].ultimaData = a.data; porEquip[a.equipamentoId].ordemId = a.ordemId; }
    });
    var linhas = Object.keys(porEquip).map(function(eid){
      var g = porEquip[eid];
      return {equipamentoId:eid, horas:g.horas, ultimaData:g.ultimaData, ordemId:g.ordemId};
    }).sort(function(a,b){ return b.horas-a.horas; });

    if(linhas.length===0){
      el.innerHTML = '<div class="empty-state" style="padding:20px;">Nenhuma parada de manutenção no período selecionado.</div>';
      return;
    }
    el.innerHTML = '<div class="legend">' + linhas.map(function(l){
      var eq = getEquip(l.equipamentoId), ord = getOrdem(l.ordemId);
      return '<div class="legend-item" style="border-left:3px solid #C0392B;padding-left:8px;">' +
        '<span class="plate">'+(eq?esc(eq.codigo):'—')+'</span>' +
        '<span class="muted-tag">'+(ord?esc(ord.nome):'—')+' · último em '+brDate(l.ultimaData)+'</span>' +
        '<span class="n" style="color:#C0392B;">'+brNum(l.horas,1)+' h</span></div>';
    }).join('') + '</div>';
  }

  // Três linhas na MESMA escala (todas em horas): Programada, Horímetro e a diferença "não
  // apontada" (Programada - Horímetro - Parada, igual à métrica já usada no KPI "Horas não
  // apontadas") -- essa terceira pode ficar negativa (horímetro+parada > programada), por isso
  // o eixo aqui tem um mínimo próprio (não fixo em zero) com uma linha de base em y=0.
  function renderProgHorNaoApChart(){
    var doMes = dashboardApropriacoesFiltradas();
    var porDia = {};
    doMes.forEach(function(a){
      if(!porDia[a.data]) porDia[a.data] = {lista:[], programada:0, parada:0};
      porDia[a.data].lista.push(a);
      porDia[a.data].programada += a.horasOperador;
      porDia[a.data].parada += paradasTotal(a);
    });
    var dias = Object.keys(porDia).sort();
    var el = document.getElementById('progHorNaoApChart');
    if(!el) return;
    if(dias.length===0){ el.innerHTML = '<div class="empty-state" style="padding:20px;">Nenhum lançamento no período selecionado.</div>'; return; }
    var progSerie = dias.map(function(d){ return Math.round(porDia[d].programada*10)/10; });
    var horSerie = dias.map(function(d){ return Math.round(horimetroAgregado(porDia[d].lista)*10)/10; });
    var naoApSerie = dias.map(function(d,i){ return Math.round((progSerie[i]-horSerie[i]-porDia[d].parada)*10)/10; });

    var w = 480, h = 170, padL = 34, padR = 10, padT = 10, padB = 24;
    var innerW = w-padL-padR, innerH = h-padT-padB;
    var todosValores = progSerie.concat(horSerie).concat(naoApSerie);
    var maxV = Math.max.apply(null, todosValores.concat([1]));
    var minV = Math.min(0, Math.min.apply(null, todosValores));
    var range = (maxV-minV) || 1;
    function yFor(v){ return padT + innerH - ((v-minV)/range*innerH); }
    function pathFor(serie){
      return serie.map(function(v,i){
        var x = padL + (serie.length>1 ? i/(serie.length-1)*innerW : innerW/2);
        return (i===0?'M':'L')+x.toFixed(1)+','+yFor(v).toFixed(1);
      }).join(' ');
    }
    var baseY = yFor(0).toFixed(1);
    function areaPathFor(serie){
      var lastX = (padL + (serie.length>1 ? innerW : innerW/2)).toFixed(1);
      var firstX = (padL + (serie.length>1 ? 0 : innerW/2)).toFixed(1);
      return pathFor(serie)+' L'+lastX+','+baseY+' L'+firstX+','+baseY+' Z';
    }
    function pontosFor(serie, cor, sufixo){
      return serie.map(function(v,i){
        var x = padL + (serie.length>1 ? i/(serie.length-1)*innerW : innerW/2);
        return '<circle cx="'+x.toFixed(1)+'" cy="'+yFor(v).toFixed(1)+'" r="2.4" fill="'+cor+'"><title>'+brDate(dias[i])+': '+brNum(v,1)+sufixo+'</title></circle>';
      }).join('');
    }
    var gridLines = [0.25,0.5,0.75].map(function(f){
      var y = (padT + innerH*f).toFixed(1);
      return '<line x1="'+padL+'" y1="'+y+'" x2="'+(padL+innerW)+'" y2="'+y+'" stroke="#EEF1F4" stroke-width="1"/>';
    }).join('');
    var xLabels = dias.map(function(d,i){
      if(dias.length>10 && i%Math.ceil(dias.length/8)!==0) return '';
      var x = padL + (dias.length>1 ? i/(dias.length-1)*innerW : innerW/2);
      return '<text x="'+x.toFixed(1)+'" y="'+(h-6)+'" font-size="9" fill="#5C6B78" text-anchor="middle" font-family="Arial">'+brDate(dias[i]).slice(0,5)+'</text>';
    }).join('');
    el.innerHTML =
      '<div class="legend" style="margin-bottom:6px;">' +
        '<div class="legend-item"><span class="led" style="background:#2E75B6;"></span>Horas programadas</div>' +
        '<div class="legend-item"><span class="led" style="background:#E8833A;"></span>Horas de horímetro</div>' +
        '<div class="legend-item"><span class="led" style="background:#6B7A99;"></span>Diferença não apontada</div>' +
      '</div>' +
      '<svg viewBox="0 0 '+w+' '+h+'" width="100%" height="140" preserveAspectRatio="xMinYMin meet">' +
        '<defs>' +
          '<linearGradient id="pnaGradProg" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#2E75B6" stop-opacity="0.18"/><stop offset="100%" stop-color="#2E75B6" stop-opacity="0"/></linearGradient>' +
          '<linearGradient id="pnaGradHor" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#E8833A" stop-opacity="0.18"/><stop offset="100%" stop-color="#E8833A" stop-opacity="0"/></linearGradient>' +
        '</defs>' +
        gridLines +
        '<line x1="'+padL+'" y1="'+padT+'" x2="'+padL+'" y2="'+(padT+innerH)+'" stroke="#DCE3EA"/>' +
        '<line x1="'+padL+'" y1="'+baseY+'" x2="'+(padL+innerW)+'" y2="'+baseY+'" stroke="#DCE3EA"/>' +
        '<path d="'+areaPathFor(progSerie)+'" fill="url(#pnaGradProg)" stroke="none"/>' +
        '<path d="'+areaPathFor(horSerie)+'" fill="url(#pnaGradHor)" stroke="none"/>' +
        '<path d="'+pathFor(progSerie)+'" fill="none" stroke="#2E75B6" stroke-width="2"/>' + pontosFor(progSerie,'#2E75B6','h') +
        '<path d="'+pathFor(horSerie)+'" fill="none" stroke="#E8833A" stroke-width="2"/>' + pontosFor(horSerie,'#E8833A','h') +
        '<path d="'+pathFor(naoApSerie)+'" fill="none" stroke="#6B7A99" stroke-width="2" stroke-dasharray="4 3"/>' + pontosFor(naoApSerie,'#6B7A99','h') +
        xLabels +
      '</svg>' +
      '<div class="muted-tag" style="margin-top:4px;">Diferença não apontada = Programada − Horímetro − Parada (pode ficar negativa).</div>';
  }

  // Tabela ao lado do gráfico acima: quanto cada categoria pesa sobre o total de horas
  // programadas no período (Horímetro + Parada + Não apontada somam ~100% da Programada).
  function renderPesoHorasTabela(){
    var body = document.getElementById('pesoHorasBody');
    if(!body) return;
    var lista = dashboardApropriacoesFiltradas();
    var totalProgramada = lista.reduce(function(s,a){ return s+a.horasOperador; },0);
    var totalHorimetro = horimetroAgregado(lista);
    var totalParada = lista.reduce(function(s,a){ return s+paradasTotal(a); },0);
    var totalNaoApontado = totalProgramada - totalHorimetro - totalParada;
    if(totalProgramada<=0){
      body.innerHTML = '<tr class="empty-row"><td colspan="3">Nenhum lançamento encontrado para os filtros selecionados.</td></tr>';
      return;
    }
    function linha(cor, label, horas){
      var pct = Math.round(horas/totalProgramada*1000)/10;
      return '<tr><td><span class="led" style="background:'+cor+';display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px;"></span>'+esc(label)+'</td>' +
        '<td class="num">'+brNum(horas,1)+'</td>' +
        '<td class="num">'+gaugeMedidor(pct, 56)+'</td></tr>';
    }
    body.innerHTML =
      linha('#E8833A', 'Horímetro', totalHorimetro) +
      linha('#B23B3B', 'Parada', totalParada) +
      linha('#6B7A99', 'Não apontada', totalNaoApontado) +
      '<tr style="font-weight:700;background:var(--bg-soft);"><td>Total programado</td><td class="num">'+brNum(totalProgramada,1)+'</td><td class="num">100%</td></tr>';
  }

  function renderReceitaOrdemChart(){
    var doMes = dashboardApropriacoesFiltradas();
    var de = document.getElementById('dashDe').value;
    var ate = document.getElementById('dashAte').value;
    var ordensEnvolvidas = Array.from(new Set(doMes.map(function(a){ return a.ordemId; })));
    var porOrdem = {};
    ordensEnvolvidas.forEach(function(oid){
      var linhasBoletim = calcularBoletim(oid, de || '0001-01-01', ate || '9999-12-31');
      porOrdem[oid] = linhasBoletim.reduce(function(s,l){ return s+l.valorAtual; },0);
    });
    state.tarifasHora.forEach(function(t){
      var lanc = doMes.filter(function(a){ return a.ordemId===t.ordemId; });
      var horasEf = lanc.reduce(function(s,a){ return s+horasEfetivasMedicao(a, t.baseCalculo); },0);
      porOrdem[t.ordemId] = (porOrdem[t.ordemId]||0) + horasEf*t.valorHora;
    });
    var entries = Object.keys(porOrdem).map(function(oid){
      var ord = getOrdem(oid);
      return {label: ord?ord.nome:'(removida)', value: porOrdem[oid]};
    }).filter(function(e){ return e.value>0; }).sort(function(a,b){ return b.value-a.value; }).slice(0,10);
    document.getElementById('receitaOrdemChart').innerHTML = svgBarChartHtml(entries, '#1F4E79', function(v){ return 'R$ '+brNum(v,2); });
  }

  function renderUltimasAlocacoes(){
    var el = document.getElementById('ultimasAlocacoes');
    var list = dashboardApropriacoesFiltradas().slice().sort(function(a,b){ return a.data<b.data?1:-1; }).slice(0,6);
    if(list.length===0){ el.innerHTML = '<div class="empty-state" style="padding:20px;">Nenhum lançamento ainda.</div>'; return; }
    el.innerHTML = '<div class="legend">' + list.map(function(a){
      var eq = getEquip(a.equipamentoId), ord = getOrdem(a.ordemId);
      return '<div class="legend-item"><span class="plate">'+(eq?esc(eq.codigo):'—')+'</span>' +
        '<span class="muted-tag">'+(ord?esc(ord.nome):'—')+' · '+brDate(a.data)+(a.dataFim && a.dataFim!==a.data ? '→'+brDate(a.dataFim):'')+'</span>' +
        '<span class="n">'+brNum(a.horasHorimetro,1)+' h</span></div>';
    }).join('') + '</div>';
  }

  function renderEquipamentosManutencao(){
    var el = document.getElementById('equipamentosManutencao');
    if(!el) return;
    var porEquip = {};
    dashboardApropriacoesFiltradas().forEach(function(a){
      if(!a.equipamentoId) return;
      if(!porEquip[a.equipamentoId] || a.data > porEquip[a.equipamentoId].data){
        porEquip[a.equipamentoId] = a;
      }
    });
    var emManutencao = Object.values(porEquip).filter(function(a){
      return (a.paradas||[]).some(function(p){ return isMotivoManutencao(p.motivo) && p.horas>0; });
    }).sort(function(a,b){ return a.data<b.data?1:-1; });

    if(emManutencao.length===0){
      el.innerHTML = '<div class="empty-state" style="padding:20px;">Nenhum equipamento com parada de manutenção no último lançamento.</div>';
      return;
    }
    el.innerHTML = '<div class="legend">' + emManutencao.map(function(a){
      var eq = getEquip(a.equipamentoId), ord = getOrdem(a.ordemId);
      var horasManut = (a.paradas||[]).filter(function(p){ return isMotivoManutencao(p.motivo); }).reduce(function(s,p){ return s+(p.horas||0); },0);
      var motivos = (a.paradas||[]).filter(function(p){ return isMotivoManutencao(p.motivo) && p.horas>0; }).map(function(p){ return esc(p.motivo); }).join(', ');
      return '<div class="legend-item" style="border-left:3px solid #C0392B;padding-left:8px;">' +
        '<span class="plate">'+(eq?esc(eq.codigo):'—')+'</span>' +
        '<span class="muted-tag">'+(ord?esc(ord.nome):'—')+' · último lançamento em '+brDate(a.data)+(motivos?' · '+motivos:'')+'</span>' +
        '<span class="n" style="color:#C0392B;">'+brNum(horasManut,1)+' h parado</span></div>';
    }).join('') + '</div>';
  }

  function statusPredominante(list){
    var counts = {};
    list.forEach(function(e){ counts[e.status] = (counts[e.status]||0)+1; });
    var best = null, bestN = -1;
    Object.keys(counts).forEach(function(k){ if(counts[k]>bestN){ bestN=counts[k]; best=k; } });
    return best;
  }

  function valoresColunaObraSummary(r){
    return {
      cliente: (clienteNumero(r.cliente)?clienteNumero(r.cliente)+' ':'')+r.cliente,
      ordem: (r.numero?r.numero+' ':'')+r.ordem,
      equipamentos: String(r.qtd),
      horimetro: brNum(r.horimetro,2),
      programada: brNum(r.operador,2),
      parada: brNum(r.parada,2),
      eficiencia: r.eff+'%'
    };
  }
  var obraSummaryRowsCache = [];
  function renderObraSummary(){
    var groups = {};
    dashboardApropriacoesFiltradas().forEach(function(a){
      var ord = getOrdem(a.ordemId);
      if(!ord) return;
      if(!groups[ord.id]) groups[ord.id] = {ordem:ord, equipIds:{}, lista:[], operador:0, parada:0};
      groups[ord.id].equipIds[a.equipamentoId] = true;
      groups[ord.id].lista.push(a);
      groups[ord.id].operador += a.horasOperador;
      groups[ord.id].parada += paradasTotal(a);
    });
    var rows = Object.values(groups).map(function(g){
      var horimetro = horimetroAgregado(g.lista);
      var eff = g.operador>0 ? Math.round(horimetro/g.operador*100) : 0;
      return {cliente:g.ordem.cliente, ordem:g.ordem.nome, numero:g.ordem.numero, qtd:Object.keys(g.equipIds).length, horimetro:horimetro, operador:g.operador, parada:g.parada, eff:eff};
    }).sort(function(a,b){ return b.horimetro-a.horimetro; });
    obraSummaryRowsCache = rows.slice();

    var kpiRow = document.getElementById('obraSummaryKpiRow');
    var body = document.getElementById('obraSummaryBody');
    if(rows.length===0){
      if(kpiRow) kpiRow.innerHTML = '';
      body.innerHTML = '<tr class="empty-row"><td colspan="7">Nenhum lançamento encontrado para os filtros selecionados.</td></tr>';
      marcarBotoesFiltroAtivos('obraSummary');
      return;
    }
    rows = aplicaColFiltrosTabela('obraSummary', rows);
    marcarBotoesFiltroAtivos('obraSummary');

    if(kpiRow){
      if(rows.length===0){
        kpiRow.innerHTML = '';
      } else {
        var totalHorimetroKpi = rows.reduce(function(s,r){ return s+r.horimetro; },0);
        var totalProgramadaKpi = rows.reduce(function(s,r){ return s+r.operador; },0);
        var effGeral = totalProgramadaKpi>0 ? Math.round(totalHorimetroKpi/totalProgramadaKpi*100) : 0;
        var okCount = rows.filter(function(r){ return r.eff>=85; }).length;
        var warnCount = rows.filter(function(r){ return r.eff>=60 && r.eff<85; }).length;
        var badCount = rows.filter(function(r){ return r.eff<60; }).length;
        kpiRow.innerHTML =
          '<div class="kpi-card" style="display:flex;align-items:center;gap:14px;">' +
            gaugeMedidor(effGeral, 92) +
            '<div><div class="kpi-label">Eficiência geral</div><div class="kpi-value">'+effGeral+'%</div><div class="muted-tag">todas as ordens no período</div></div>' +
          '</div>' +
          '<div class="kpi-card"><div class="kpi-label">Ordens em dia (≥85%)</div><div class="kpi-value" style="color:'+effColor(100)+';">'+okCount+'</div></div>' +
          '<div class="kpi-card"><div class="kpi-label">Ordens de atenção (60–84%)</div><div class="kpi-value" style="color:'+effColor(70)+';">'+warnCount+'</div></div>' +
          '<div class="kpi-card"><div class="kpi-label">Ordens críticas (&lt;60%)</div><div class="kpi-value" style="color:'+effColor(0)+';">'+badCount+'</div></div>';
      }
    }

    if(rows.length===0){
      body.innerHTML = '<tr class="empty-row"><td colspan="7">Nenhum lançamento encontrado para os filtros selecionados.</td></tr>';
      return;
    }
    body.innerHTML = rows.map(function(r){
      return '<tr><td>'+(clienteNumero(r.cliente)?esc(clienteNumero(r.cliente))+' ':'')+esc(r.cliente)+'</td><td>'+(r.numero?esc(r.numero)+' ':'')+esc(r.ordem)+'</td>' +
        '<td class="num">'+r.qtd+'</td><td class="num">'+brNum(r.horimetro,2)+'</td>' +
        '<td class="num">'+brNum(r.operador,2)+'</td><td class="num">'+brNum(r.parada,2)+'</td>' +
        '<td class="num">'+gaugeMedidor(r.eff, 56)+'</td></tr>';
    }).join('');
  }

  function initDashboardPeriodo(){
    // Sem período padrão — o Dashboard começa mostrando todos os dados, igual ao modelo de referência.
    // O usuário escolhe um período manualmente ou usa um dos atalhos (Mês atual / Últimos 30 dias / Ano atual).
    var ordensBase = state.ordens.slice().sort(function(a,b){ var c=a.cliente.localeCompare(b.cliente,'pt-BR'); return c!==0?c:a.nome.localeCompare(b.nome,'pt-BR'); });
    wireOrdemTrio('dashOrdemNumero', 'dashOrdem', 'dashNCliente', function(){ return ordensBase; }, renderDashboard);
    var equipsOrd = state.equipamentos.slice().sort(function(a,b){ return a.codigo.localeCompare(b.codigo,'pt-BR'); });
    wireComboBox('dashEquip', 'dashEquipList', function(){ return equipsOrd.map(function(e){ return e.codigo; }); }, null, null, 'Todos os equipamentos');
    wireComboBox('dashOperador', 'dashOperadorList', function(){
      var nomes = new Set();
      state.operadores.forEach(function(o){ nomes.add(o.nome); });
      state.apropriacoes.forEach(function(a){ if(a.operador) nomes.add(a.operador); });
      return Array.from(nomes).sort(function(a,b){ return a.localeCompare(b,'pt-BR'); });
    }, null, null, 'Todos os operadores');
  }
  function dashboardApropriacoesFiltradas(){
    var de = document.getElementById('dashDe').value;
    var ate = document.getElementById('dashAte').value;
    var cliente = clienteDoNumeroField('dashNCliente');
    var ordemId = resolverOrdemFiltro('dashOrdem');
    var equipId = resolverEquipFiltro('dashEquip');
    var operador = document.getElementById('dashOperador').value.trim();
    var ordensValidas = null;
    if(cliente || ordemId){
      ordensValidas = {};
      state.ordens.forEach(function(o){ if((!cliente||o.cliente===cliente) && (!ordemId||o.id===ordemId)) ordensValidas[o.id]=true; });
    }
    return state.apropriacoes.filter(function(a){
      if(de && a.data<de) return false;
      if(ate && a.data>ate) return false;
      if(ordensValidas && !ordensValidas[a.ordemId]) return false;
      if(equipId && a.equipamentoId!==equipId) return false;
      if(operador && a.operador!==operador) return false;
      return true;
    });
  }
  // Produção (toneladas) é lançada por Ordem+dia em state.producoes (tela Produção), não dentro
  // da apropriação -- por isso usa seu próprio filtro (sem Equipamento/Operador, que não existem
  // nesse registro), espelhando o período/Ordem/Cliente já aplicados no Dashboard.
  function dashboardProducaoToneladas(){
    var de = document.getElementById('dashDe').value;
    var ate = document.getElementById('dashAte').value;
    var cliente = clienteDoNumeroField('dashNCliente');
    var ordemId = resolverOrdemFiltro('dashOrdem');
    var ordensValidas = null;
    if(cliente || ordemId){
      ordensValidas = {};
      state.ordens.forEach(function(o){ if((!cliente||o.cliente===cliente) && (!ordemId||o.id===ordemId)) ordensValidas[o.id]=true; });
    }
    return state.producoes.filter(function(p){
      if(p.tipo!=='pesagem') return false;
      if(de && p.data<de) return false;
      if(ate && p.data>ate) return false;
      if(ordensValidas && !ordensValidas[p.ordemId]) return false;
      return true;
    });
  }
  function atualizarStatusFiltrosDashboard(){
    var el = document.getElementById('dashFiltrosStatus');
    if(!el) return;
    var de = document.getElementById('dashDe').value;
    var ate = document.getElementById('dashAte').value;
    var cliente = clienteDoNumeroField('dashNCliente');
    var ordem = document.getElementById('dashOrdem').value.trim() || document.getElementById('dashOrdemNumero').value.trim();
    var equip = document.getElementById('dashEquip').value.trim();
    var operador = document.getElementById('dashOperador').value.trim();
    var temFiltro = de || ate || cliente || ordem || equip || operador;
    var qtd = dashboardApropriacoesFiltradas().length;
    el.textContent = (temFiltro ? 'Filtros aplicados' : 'Sem filtros aplicados — mostrando dados completos.') + ' · '+qtd+' lançamentos';
  }

  function renderDashHero(){
    var el = document.getElementById('dashHeroSub');
    if(!el) return;
    var total = state.equipamentos.length;
    var doMes = dashboardApropriacoesFiltradas();
    var horasMes = horimetroAgregado(doMes);
    var clientesAtivos = new Set(doMes.map(function(a){ var o=getOrdem(a.ordemId); return o?o.cliente:null; }).filter(Boolean)).size;
    var temPeriodo = document.getElementById('dashDe').value || document.getElementById('dashAte').value;
    el.textContent = total+' equipamentos · '+brNum(horasMes,0)+'h horímetro em '+clientesAtivos+' clientes'+(temPeriodo?'.':' (sem filtro de período).');
  }

  function renderDashboard(){
    recalcularHorimetrosEfetivos();
    initDashboardPeriodo();
    renderDashHero();
    renderKpiRowStatus();
    renderKpiRowHoras();
    renderClientBars();
    renderClienteResumo();
    renderTendenciaChart();
    renderProgHorNaoApChart();
    renderPesoHorasTabela();
    renderEquipAtivoManutChart();
    renderEquipManutPeriodoLista();
    renderParadaChart();
    renderUltimasAlocacoes(); renderEquipamentosManutencao();
    renderReceitaOrdemChart();
    renderValorProducaoMes();
    renderObraSummary();
    renderIndicadoresProjecao();
    renderIndicadores();
    atualizarStatusFiltrosDashboard();
  }

  function renderValorProducaoMes(targetId){
    var el = document.getElementById(targetId||'valorProducaoMes');
    if(!el) return;
    var de = document.getElementById('dashDe').value || '0001-01-01';
    var ate = document.getElementById('dashAte').value || '9999-12-31';
    var doMesAp = dashboardApropriacoesFiltradas();
    var ordensEnvolvidas = Array.from(new Set(doMesAp.map(function(a){ return a.ordemId; })));
    var porOrdem = {};
    ordensEnvolvidas.forEach(function(oid){
      var toneladas = state.producoes.filter(function(p){
        return p.ordemId===oid && p.tipo==='pesagem' && p.data>=de && p.data<=ate;
      }).reduce(function(s,p){ return s+(p.valor||0); },0);
      var linhasBoletim = calcularBoletim(oid, de, ate);
      var valor = linhasBoletim.reduce(function(s,l){ return s+l.valorAtual; },0);
      if(toneladas>0 || valor>0) porOrdem[oid] = {toneladas:toneladas, valor:valor};
    });
    var totalValor = Object.values(porOrdem).reduce(function(s,x){ return s+x.valor; },0);
    var linhas = Object.keys(porOrdem).map(function(oid){
      var ord = getOrdem(oid);
      return {cliente: ord?ord.cliente:'—', ordem: ord?ordemLabel(ord):'(removida)', toneladas: porOrdem[oid].toneladas, valor: porOrdem[oid].valor};
    }).sort(function(a,b){ return b.valor-a.valor; });
    if(linhas.length===0){
      el.innerHTML = '<div class="empty-state" style="padding:20px;">Nenhuma produção com tarifa cadastrada lançada no período selecionado.</div>';
      return;
    }
    el.innerHTML = '<div class="kpi-row" style="margin-bottom:14px;"><div class="kpi-card"><div class="kpi-label">Valor total no período</div><div class="kpi-value">R$ '+brNum(totalValor,2)+'</div></div></div>'+
      '<div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Ordem</th><th class="num">Produção (t)</th><th class="num">Valor (R$)</th></tr></thead><tbody>'+
      linhas.map(function(l){ return '<tr><td>'+esc(l.cliente)+'</td><td>'+esc(l.ordem)+'</td><td class="num">'+brNum(l.toneladas,2)+'</td><td class="num">'+brNum(l.valor,2)+'</td></tr>'; }).join('')+
      '</tbody></table></div>';
  }

  function renderIndicadoresProjecao(){
    var doMes = dashboardApropriacoesFiltradas();
    var ind = calcularIndicadores(doMes);
    var el = document.getElementById('indicadoresProjecao');
    if(!el) return;
    function mini(label, value, pct, color){
      return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value">'+value+'</div>' +
        (pct!==null ? ('<div class="kpi-gauge"><div class="kpi-gauge-fill" style="width:'+Math.min(pct,100)+'%;background:'+color+';"></div></div>') : '') +
      '</div>';
    }
    el.innerHTML =
      mini('Disponibilidade Mecânica', ind.dm+'%', ind.dm, effColor(ind.dm)) +
      mini('Índice de Utilização', ind.ut+'%', ind.ut, effColor(ind.ut)) +
      mini('Eficiência Operacional', ind.oee+'%', ind.oee, effColor(ind.oee));
  }

  /* ============ RENDER: CONSOLIDADO ============ */
  function populateConsFilters(){
    var ordensBase = state.ordens.slice().sort(function(a,b){ var c=a.cliente.localeCompare(b.cliente,'pt-BR'); return c!==0?c:a.nome.localeCompare(b.nome,'pt-BR'); });
    wireOrdemTrio('consOrdemNumero', 'consOrdem', 'consNCliente', function(){ return ordensBase; }, renderConsolidado, null, 'consCliente');
    wireComboBox('consOperador', 'consOperadorList', function(){
      var nomes = new Set();
      state.operadores.forEach(function(o){ nomes.add(o.nome); });
      state.apropriacoes.forEach(function(a){ if(a.operador) nomes.add(a.operador); });
      return Array.from(nomes).sort(function(a,b){ return a.localeCompare(b,'pt-BR'); });
    }, null, null, 'Todos os operadores');
    var equipsOrdenados = state.equipamentos.slice().sort(function(a,b){return a.codigo.localeCompare(b.codigo,'pt-BR');});
    wireComboBox('consEquip', 'consEquipList', function(){ return equipsOrdenados.map(function(e){ return e.codigo; }); }, null, null, 'Todos os equipamentos');
  }
  function resolverOrdemFiltro(inputId){
    var texto = document.getElementById(inputId).value.trim();
    if(texto){
      var ord = state.ordens.filter(function(o){ return ordemLabel(o)===texto; })[0];
      if(ord) return ord.id;
    }
    // Se o campo "Ordem" (nome) está vazio ou não bate com nada, tenta pelo campo irmão
    // "Nº Ordem" (mesmo id + "Numero") -- cobre o caso de digitar só o número e sair do
    // campo sem clicar na sugestão da lista, que antes deixava o filtro sem efeito.
    var numeroEl = document.getElementById(inputId+'Numero');
    if(numeroEl){
      var numeroTexto = numeroEl.value.trim();
      if(numeroTexto){
        var ordPorNumero = state.ordens.filter(function(o){ return (o.numero||'')===numeroTexto; })[0];
        if(ordPorNumero) return ordPorNumero.id;
      }
    }
    return null;
  }
  function resolverEquipFiltro(inputId){
    var texto = document.getElementById(inputId).value.trim();
    if(!texto) return null;
    var eq = state.equipamentos.filter(function(e){ return e.codigo===texto; })[0];
    return eq ? eq.id : null;
  }

  function valoresColunaConsolidado(r){
    var eq = getEquip(r.equipamentoId);
    var ord = getOrdem(r.ordemId);
    var eff = r.operador>0 ? Math.round(r.horimetro/r.operador*100) : 0;
    return {
      cliente: ord?((clienteNumero(ord.cliente)?clienteNumero(ord.cliente)+' ':'')+ord.cliente):'—',
      ordem: ord?((ord.numero?ord.numero+' ':'')+ord.nome):'—',
      equipamento: eq?eq.codigo:'(removido)',
      tipo: eq?eq.tipo:'—',
      hProgramada: brNum(r.operador,2),
      hInicial: r.hInicial!==null?brNum(r.hInicial,1):'—',
      hFinal: r.hFinal!==null?brNum(r.hFinal,1):'—',
      hHorimetro: brNum(r.horimetro,2),
      hParada: brNum(r.parada,2),
      diasTrabalhados: String(r.diasTrabalhados),
      eficiencia: eff+'%'
    };
  }
  function valoresColunaConsolidadoOperador(l){
    return { operador: l.nome, dias: String(l.dias), equipamentosDistintos: String(l.equipamentos), hProgramada: brNum(l.horas,1) };
  }
  var consolidadoRowsCache = [], consolidadoOperadorRowsCache = [];

  function renderConsolidado(){
    recalcularHorimetrosEfetivos();
    populateConsFilters();
    var cliente = clienteDoNumeroField('consNCliente');
    var ordemId = resolverOrdemFiltro('consOrdem');
    var operadorFiltro = document.getElementById('consOperador').value.trim();
    var equipId = resolverEquipFiltro('consEquip');
    var de = document.getElementById('consDe').value;
    var ate = document.getElementById('consAte').value;
    var ordensValidas = {};
    state.ordens.forEach(function(o){ if((!cliente||o.cliente===cliente) && (!ordemId||o.id===ordemId)) ordensValidas[o.id]=true; });

    var groups = {};
    var listaFiltrada = [];
    state.apropriacoes.forEach(function(a){
      if(!ordensValidas[a.ordemId]) return;
      if(operadorFiltro && a.operador!==operadorFiltro) return;
      if(equipId && a.equipamentoId!==equipId) return;
      if(de && a.data<de) return;
      if(ate && a.data>ate) return;
      listaFiltrada.push(a);
      var key = a.ordemId+'||'+a.equipamentoId;
      if(!groups[key]) groups[key] = {ordemId:a.ordemId, equipamentoId:a.equipamentoId, lista:[], operador:0, parada:0};
      groups[key].lista.push(a);
      groups[key].operador += a.horasOperador;
      groups[key].parada += paradasTotal(a);
    });
    var rows = Object.values(groups).map(function(g){
      var limites = horimetroLimitesLista(g.lista);
      var diasTrabalhados = new Set(g.lista.map(function(a){ return a.data; })).size;
      return {ordemId:g.ordemId, equipamentoId:g.equipamentoId, horimetro:horimetroDoEquipamento(g.lista), operador:g.operador, parada:g.parada, hInicial:limites.inicial, hFinal:limites.final, diasTrabalhados:diasTrabalhados};
    }).sort(function(a,b){ return b.horimetro-a.horimetro; });
    consolidadoRowsCache = rows.slice();

    var body = document.getElementById('consBody');
    var topoTotalCons = document.getElementById('consTopoTotal');
    var bodyOperador = document.getElementById('consOperadorBody');
    if(rows.length===0){
      document.getElementById('consKpiRow').innerHTML = '';
      body.innerHTML = '<tr class="empty-row"><td colspan="12">Nenhum lançamento para os filtros selecionados.</td></tr>';
      topoTotalCons.innerHTML = '';
      bodyOperador.innerHTML = '<tr class="empty-row"><td colspan="4">Nenhum lançamento para os filtros selecionados.</td></tr>';
      document.getElementById('consOperadorNote').style.display = 'none';
      marcarBotoesFiltroAtivos('consolidado');
      return;
    }

    rows = aplicaColFiltrosTabela('consolidado', rows);
    marcarBotoesFiltroAtivos('consolidado');

    var totalHorimetro = rows.reduce(function(s,r){ return s+r.horimetro; },0);
    var totalOperador = rows.reduce(function(s,r){ return s+r.operador; },0);
    var eficiencia = totalOperador>0 ? Math.round(totalHorimetro/totalOperador*100) : 0;
    var distinctEquip = new Set(rows.map(function(r){ return r.equipamentoId; })).size;
    function kpi(label, value, pct, color){
      return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value">'+value+'</div>' +
        (pct!==null ? ('<div class="kpi-gauge"><div class="kpi-gauge-fill" style="width:'+Math.min(pct,100)+'%;background:'+color+';"></div></div>') : '') +
      '</div>';
    }
    document.getElementById('consKpiRow').innerHTML =
      kpi('Equipamentos alocados', distinctEquip, null, '') +
      kpi('Horas de horímetro', brNum(totalHorimetro,1), null, '') +
      kpi('Horas programadas', brNum(totalOperador,1), null, '') +
      kpi('Eficiência', eficiencia+'%', eficiencia, effColor(eficiencia));

    if(rows.length===0){
      body.innerHTML = '<tr class="empty-row"><td colspan="12">Nenhum lançamento para os filtros de coluna selecionados.</td></tr>';
      topoTotalCons.innerHTML = '';
    } else {
      var totalParadaCons = rows.reduce(function(s,r){ return s+r.parada; },0);
      var totalDiasCons = rows.reduce(function(s,r){ return s+r.diasTrabalhados; },0);
      topoTotalCons.innerHTML = '<tr style="font-weight:700;background:#F7FAFC;">' +
        '<td colspan="4">Total do período filtrado</td>' +
        '<td class="num">'+brNum(totalOperador,2)+'</td>' +
        '<td class="num">—</td><td class="num">—</td>' +
        '<td class="num">'+brNum(totalHorimetro,2)+'</td>' +
        '<td class="num">'+brNum(totalParadaCons,2)+'</td><td class="num">'+totalDiasCons+'</td>' +
        '<td class="num">'+gaugeMedidor(eficiencia, 56)+'</td></tr>';
      body.innerHTML = rows.map(function(r){
        var eq = getEquip(r.equipamentoId);
        var ord = getOrdem(r.ordemId);
        var eff = r.operador>0 ? Math.round(r.horimetro/r.operador*100) : 0;
        return '<tr><td>'+(ord?(clienteNumero(ord.cliente)?esc(clienteNumero(ord.cliente))+' ':''):'')+(ord?esc(ord.cliente):'—')+'</td><td>'+(ord&&ord.numero?esc(ord.numero)+' ':'')+(ord?esc(ord.nome):'—')+'</td>' +
          '<td>'+(eq?'<span class="plate">'+esc(eq.codigo)+'</span>':'<span class="muted-tag">(removido)</span>')+'</td>' +
          '<td>'+(eq?esc(eq.tipo):'—')+'</td>' +
          '<td class="num">'+brNum(r.operador,2)+'</td>' +
          '<td class="num">'+(r.hInicial!==null?brNum(r.hInicial,1):'—')+'</td>' +
          '<td class="num">'+(r.hFinal!==null?brNum(r.hFinal,1):'—')+'</td>' +
          '<td class="num">'+brNum(r.horimetro,2)+'</td>' +
          '<td class="num">'+brNum(r.parada,2)+'</td><td class="num">'+r.diasTrabalhados+'</td>' +
          '<td class="num">'+gaugeMedidor(eff, 56)+'</td></tr>';
      }).join('');
    }

    var porOperador = {};
    var porOperadorDia = {};
    var temSobreposicao = false;
    listaFiltrada.forEach(function(a){
      if(!a.operador) return;
      if(!porOperador[a.operador]) porOperador[a.operador] = {dias:new Set(), equipamentos:new Set(), horasProgramada:0};
      porOperador[a.operador].dias.add(a.data);
      porOperador[a.operador].equipamentos.add(a.equipamentoId);
      porOperador[a.operador].horasProgramada += a.horasOperador;
      var chaveDia = a.operador+'||'+a.data;
      if(!porOperadorDia[chaveDia]) porOperadorDia[chaveDia] = new Set();
      porOperadorDia[chaveDia].add(a.equipamentoId);
      if(porOperadorDia[chaveDia].size>1) temSobreposicao = true;
    });
    document.getElementById('consOperadorNote').style.display = temSobreposicao ? 'block' : 'none';
    var linhasOperador = Object.keys(porOperador).map(function(nome){
      var p = porOperador[nome];
      return {nome:nome, dias:p.dias.size, equipamentos:p.equipamentos.size, horas:p.horasProgramada};
    }).sort(function(a,b){ return b.dias-a.dias; });
    consolidadoOperadorRowsCache = linhasOperador.slice();
    linhasOperador = aplicaColFiltrosTabela('consolidadoOperador', linhasOperador);
    marcarBotoesFiltroAtivos('consolidadoOperador');
    if(linhasOperador.length===0){
      bodyOperador.innerHTML = '<tr class="empty-row"><td colspan="4">Nenhum operador no período/filtro selecionado.</td></tr>';
    } else {
      bodyOperador.innerHTML = linhasOperador.map(function(l){
        return '<tr><td>'+esc(l.nome)+'</td><td class="num">'+l.dias+'</td><td class="num">'+l.equipamentos+'</td><td class="num">'+brNum(l.horas,1)+'</td></tr>';
      }).join('');
    }
  }

  /* ============ INDICADORES ============ */
  function populateIndFilters(){
    var ordensBase = state.ordens.slice().sort(function(a,b){ var c=a.cliente.localeCompare(b.cliente,'pt-BR'); return c!==0?c:a.nome.localeCompare(b.nome,'pt-BR'); });
    wireOrdemTrio('indOrdemNumero', 'indOrdem', 'indNCliente', function(){ return ordensBase; }, renderIndicadores);
    var equipsOrdenados = state.equipamentos.slice().sort(function(a,b){ return a.codigo.localeCompare(b.codigo,'pt-BR'); });
    wireComboBox('indEquip', 'indEquipList', function(){ return equipsOrdenados.map(function(e){ return e.codigo; }); }, null, null, 'Todos os equipamentos');
  }

  function indicadoresFiltrarLista(){
    var cliente = clienteDoNumeroField('indNCliente');
    var ordemId = resolverOrdemFiltro('indOrdem');
    var equipId = resolverEquipFiltro('indEquip');
    var de = document.getElementById('dashDe').value;
    var ate = document.getElementById('dashAte').value;
    var ordensValidas = {};
    state.ordens.forEach(function(o){ if((!cliente||o.cliente===cliente) && (!ordemId||o.id===ordemId)) ordensValidas[o.id]=true; });
    return state.apropriacoes.filter(function(a){
      if(!ordensValidas[a.ordemId]) return false;
      if(equipId && a.equipamentoId!==equipId) return false;
      if(de && a.data<de) return false;
      if(ate && a.data>ate) return false;
      return true;
    });
  }

  function renderIndicadoresKpiRow(containerId, ind){
    function kpi(label, value, pct, color){
      return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value">'+value+'</div>' +
        (pct!==null ? ('<div class="kpi-gauge"><div class="kpi-gauge-fill" style="width:'+Math.min(pct,100)+'%;background:'+color+';"></div></div>') : '') +
      '</div>';
    }
    document.getElementById(containerId).innerHTML =
      kpi('Disponibilidade Mecânica', ind.dm+'%', ind.dm, effColor(ind.dm)) +
      kpi('Índice de Utilização', ind.ut+'%', ind.ut, effColor(ind.ut)) +
      kpiCardArco('Eficiência Operacional', ind.oee) +
      kpi('MTBF', ind.mtbf===null?'—':brNum(ind.mtbf,1)+' h', null, '') +
      kpi('MTTR', ind.mttr===null?'—':brNum(ind.mttr,1)+' h', null, '') +
      kpi('Horas não apontadas', brNum(ind.naoApontado,1), null, '');
  }

  function valoresColunaIndicadoresEquip(l){
    var eq = getEquip(l.equipamentoId);
    var ind = l.ind;
    return {
      equipamento: eq?eq.codigo:'—',
      tipo: eq?eq.tipo:'—',
      programada: brNum(ind.totalProgramada,1),
      horimetro: brNum(ind.totalHorimetro,1),
      manutencao: brNum(ind.totalManutencao,1),
      numParadas: String(ind.numParadasManut),
      dm: ind.dm+'%',
      ut: ind.ut+'%',
      oee: ind.oee+'%'
    };
  }
  var indicadoresEquipRowsCache = [];
  function renderIndicadores(){
    recalcularHorimetrosEfetivos();
    populateIndFilters();
    var lista = indicadoresFiltrarLista();
    var geral = calcularIndicadores(lista);
    renderIndicadoresKpiRow('indKpiRow', geral);
    renderManutencaoPorTipo('indKpiManutencaoTipos', lista);

    var porEquip = {};
    lista.forEach(function(a){
      if(!porEquip[a.equipamentoId]) porEquip[a.equipamentoId] = [];
      porEquip[a.equipamentoId].push(a);
    });
    var linhas = Object.keys(porEquip).map(function(eid){
      var ind = calcularIndicadores(porEquip[eid]);
      return {equipamentoId: eid, ind: ind};
    }).sort(function(a,b){ return b.ind.totalProgramada - a.ind.totalProgramada; });
    indicadoresEquipRowsCache = linhas.slice();

    var body = document.getElementById('indicadoresBody');
    if(linhas.length===0){
      body.innerHTML = '<tr class="empty-row"><td colspan="9">Nenhum lançamento para os filtros selecionados.</td></tr>';
      marcarBotoesFiltroAtivos('indicadoresEquip');
    } else {
      linhas = aplicaColFiltrosTabela('indicadoresEquip', linhas);
      marcarBotoesFiltroAtivos('indicadoresEquip');
    }
    if(linhas.length===0 && Object.keys(porEquip).length>0){
      body.innerHTML = '<tr class="empty-row"><td colspan="9">Nenhum lançamento encontrado para os filtros de coluna selecionados.</td></tr>';
    } else if(linhas.length>0){
      body.innerHTML = linhas.map(function(l){
        var eq = getEquip(l.equipamentoId);
        var ind = l.ind;
        return '<tr>' +
          '<td>'+(eq?'<span class="plate">'+esc(eq.codigo)+'</span>':'<span class="muted-tag">(removido)</span>')+'</td>' +
          '<td>'+(eq?esc(eq.tipo):'—')+'</td>' +
          '<td class="num">'+brNum(ind.totalProgramada,1)+'</td>' +
          '<td class="num">'+brNum(ind.totalHorimetro,1)+'</td>' +
          '<td class="num">'+brNum(ind.totalManutencao,1)+'</td>' +
          '<td class="num">'+ind.numParadasManut+'</td>' +
          '<td class="num">'+gaugeMedidor(ind.dm, 48)+'</td>' +
          '<td class="num">'+gaugeMedidor(ind.ut, 48)+'</td>' +
          '<td class="num">'+gaugeMedidor(ind.oee, 48)+'</td>' +
        '</tr>';
      }).join('');
    }
    renderIndicadoresPorTipo(lista, geral);
    renderIndicadoresFinanceiros(lista);
    populateRentFiltros();
    renderRentabilidade();
  }

  function renderIndicadoresPorTipo(lista, geral){
    var kpiEl = document.getElementById('indTipoKpiRow');
    if(!kpiEl) return;
    function kpi(label, value, cls){ return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value'+(cls?' '+cls:'')+'">'+value+'</div></div>'; }
    kpiEl.innerHTML =
      kpiCardArco('Disponibilidade total (todas as perdas)', geral.disponibilidadeTotal) +
      kpi('Perda operacional', geral.indicePerdaOperacional+'%') +
      kpi('Paradas de segurança (ocorrências)', geral.numParadasSeguranca, geral.numParadasSeguranca>0?'diff-bad':'diff-ok') +
      kpi('Horas de segurança', brNum(geral.totalSeguranca,1));

    var porTipo = horasPorTipoParada(lista);
    var total = Object.keys(porTipo).reduce(function(s,k){ return s+porTipo[k]; },0);
    var entries = Object.keys(porTipo).map(function(k){ return {tipo:k, horas:porTipo[k]}; })
      .filter(function(e){ return e.horas>0; }).sort(function(a,b){ return b.horas-a.horas; });
    var bodyPareto = document.getElementById('indParetoBody');
    if(bodyPareto){
      if(entries.length===0){
        bodyPareto.innerHTML = '<tr class="empty-row"><td colspan="3">Nenhuma parada no período/filtro selecionado.</td></tr>';
      } else {
        bodyPareto.innerHTML = entries.map(function(e){
          var pct = total>0 ? Math.round(e.horas/total*1000)/10 : 0;
          return '<tr><td>'+esc(e.tipo)+'</td><td class="num">'+brNum(e.horas,1)+'</td><td class="num">'+gaugeMedidor(pct, 56)+'</td></tr>';
        }).join('');
      }
    }

    // Top 5 equipamentos que mais contribuíram pras horas de parada acima (mesmo total do Pareto,
    // só que quebrado por equipamento em vez de por tipo — identifica quem está puxando o índice).
    var bodyTop5 = document.getElementById('indParetoTop5Body');
    if(bodyTop5){
      var porEquipParada = {};
      lista.forEach(function(a){
        if(!a.equipamentoId) return;
        (a.paradas||[]).forEach(function(p){
          if(!(p.horas>0)) return;
          if(!porEquipParada[a.equipamentoId]) porEquipParada[a.equipamentoId] = {total:0, porTipo:{}};
          var g = porEquipParada[a.equipamentoId];
          g.total += p.horas;
          var tipo = tipoDeParada(p.motivo);
          g.porTipo[tipo] = (g.porTipo[tipo]||0) + p.horas;
        });
      });
      var top5 = Object.keys(porEquipParada).map(function(eid){
        var g = porEquipParada[eid];
        var tipoPredominante = Object.keys(g.porTipo).reduce(function(best,t){ return (best===null || g.porTipo[t]>g.porTipo[best]) ? t : best; }, null);
        return {equipamentoId:eid, horas:g.total, tipo:tipoPredominante};
      }).sort(function(a,b){ return b.horas-a.horas; }).slice(0,5);
      if(top5.length===0){
        bodyTop5.innerHTML = '<tr class="empty-row"><td colspan="4">Nenhuma parada no período/filtro selecionado.</td></tr>';
      } else {
        bodyTop5.innerHTML = top5.map(function(e){
          var eq = getEquip(e.equipamentoId);
          var pct = total>0 ? Math.round(e.horas/total*1000)/10 : 0;
          return '<tr><td>'+(eq?'<span class="plate">'+esc(eq.codigo)+'</span>':'<span class="muted-tag">(removido)</span>')+'</td>' +
            '<td>'+esc(e.tipo||'—')+'</td>' +
            '<td class="num">'+brNum(e.horas,1)+'</td><td class="num">'+gaugeMedidor(pct, 56)+'</td></tr>';
        }).join('');
      }
    }
  }

  function renderIndicadoresFinanceiros(lista){
    var porEquipFin = {};
    lista.forEach(function(a){
      if(!porEquipFin[a.equipamentoId]) porEquipFin[a.equipamentoId] = [];
      porEquipFin[a.equipamentoId].push(a);
    });

    // Receita e produção agora vêm de Produção/Tarifa (por ordem) — não existe mais um valor
    // "de produção" lançado direto na Apropriação. Como Produção é por ordem (não por equipamento),
    // rateamos a receita/toneladas de cada ordem entre os equipamentos pela participação de cada um
    // no horímetro total daquela ordem, no período filtrado.
    var datas = lista.map(function(a){ return a.data; });
    var de = datas.length ? datas.reduce(function(x,y){ return x<y?x:y; }) : '0001-01-01';
    var ate = datas.length ? datas.reduce(function(x,y){ return x>y?x:y; }) : '9999-12-31';
    var ordensNaLista = Array.from(new Set(lista.map(function(a){ return a.ordemId; })));
    var receitaProducaoPorOrdem = {}, toneladasPorOrdem = {}, horimetroTotalPorOrdem = {};
    ordensNaLista.forEach(function(oid){
      var linhasBoletim = calcularBoletim(oid, de, ate);
      receitaProducaoPorOrdem[oid] = linhasBoletim.reduce(function(s,l){ return s+l.valorAtual; },0);
      toneladasPorOrdem[oid] = state.producoes.filter(function(p){
        return p.ordemId===oid && p.tipo==='pesagem' && p.data>=de && p.data<=ate;
      }).reduce(function(s,p){ return s+(p.valor||0); },0);
      horimetroTotalPorOrdem[oid] = horimetroAgregado(lista.filter(function(a){ return a.ordemId===oid; }));
    });

    var totalToneladas = 0, receitaProducaoTotal = 0, receitaMedicaoTotal = 0;
    var linhasEquip = Object.keys(porEquipFin).map(function(eid){
      var l = porEquipFin[eid];
      var horasHorimetro = horimetroDoEquipamento(l);
      var ordensDoEquip = Array.from(new Set(l.map(function(a){ return a.ordemId; })));
      var toneladas = 0, receitaProducao = 0;
      ordensDoEquip.forEach(function(oid){
        var horimEquipNaOrdem = horimetroDoEquipamento(l.filter(function(a){ return a.ordemId===oid; }));
        var totalHorimOrdem = horimetroTotalPorOrdem[oid] || 0;
        var participacao = totalHorimOrdem>0 ? horimEquipNaOrdem/totalHorimOrdem : 0;
        toneladas += (toneladasPorOrdem[oid]||0) * participacao;
        receitaProducao += (receitaProducaoPorOrdem[oid]||0) * participacao;
      });
      var tarifasDoEquip = state.tarifasHora.filter(function(t){ return ordensDoEquip.indexOf(t.ordemId)>-1; });
      var receitaMedicao = tarifasDoEquip.reduce(function(s,t){
        var lancTarifa = l.filter(function(a){ return a.ordemId===t.ordemId; });
        var horasEf = lancTarifa.reduce(function(ss,a){ return ss+horasEfetivasMedicao(a, t.baseCalculo); },0);
        return s + horasEf*t.valorHora;
      },0);
      var receitaTotal = receitaProducao+receitaMedicao;
      totalToneladas += toneladas; receitaProducaoTotal += receitaProducao; receitaMedicaoTotal += receitaMedicao;
      return {equipamentoId:eid, toneladas:toneladas, horasHorimetro:horasHorimetro, receitaProducao:receitaProducao, receitaMedicao:receitaMedicao, receitaTotal:receitaTotal};
    }).sort(function(a,b){ return b.receitaTotal-a.receitaTotal; }).slice(0,10);

    var totalHorimetroGeral = horimetroAgregado(lista);
    var receitaTotalGeral = receitaProducaoTotal + receitaMedicaoTotal;
    var receitaPorHora = totalHorimetroGeral>0 ? receitaTotalGeral/totalHorimetroGeral : 0;
    var receitaPorTonelada = totalToneladas>0 ? receitaProducaoTotal/totalToneladas : 0;
    var produtividadeFisica = totalHorimetroGeral>0 ? totalToneladas/totalHorimetroGeral : 0;

    function kpi(label, value, cls){ return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value'+(cls?' '+cls:'')+'">'+value+'</div></div>'; }
    document.getElementById('indFinKpiRow').innerHTML =
      kpi('Receita total (produção+medição)', 'R$ '+brNum(receitaTotalGeral,2)) +
      kpi('Receita por hora de horímetro', 'R$ '+brNum(receitaPorHora,2)) +
      kpi('Receita por tonelada', 'R$ '+brNum(receitaPorTonelada,2)) +
      kpi('Produtividade física (t/h)', brNum(produtividadeFisica,3));

    var bodyFin = document.getElementById('indFinBody');
    if(linhasEquip.length===0){
      bodyFin.innerHTML = '<tr class="empty-row"><td colspan="6">Nenhuma receita (produção ou medição) no período/filtro selecionado.</td></tr>';
      return;
    }
    bodyFin.innerHTML = linhasEquip.map(function(l){
      var eq = getEquip(l.equipamentoId);
      var rPorHora = l.horasHorimetro>0 ? l.receitaTotal/l.horasHorimetro : 0;
      return '<tr><td>'+(eq?'<span class="plate">'+esc(eq.codigo)+'</span>':'<span class="muted-tag">(removido)</span>')+'</td>'+
        '<td class="num">'+brNum(l.toneladas,2)+'</td><td class="num">'+brNum(l.horasHorimetro,1)+'</td>'+
        '<td class="num">'+brNum(l.receitaProducao,2)+'</td><td class="num">'+brNum(l.receitaMedicao,2)+'</td>'+
        '<td class="num">'+brNum(l.receitaTotal,2)+'</td>'+
        '<td class="num">'+brNum(rPorHora,2)+'</td></tr>';
    }).join('');
  }

  /* ============ RENTABILIDADE POR ORDEM (opcional, com custo manual) ============ */
  function populateRentFiltros(){
    var ordensBase = state.ordens.slice().sort(function(a,b){ var c=a.cliente.localeCompare(b.cliente,'pt-BR'); return c!==0?c:a.nome.localeCompare(b.nome,'pt-BR'); });
    wireComboBox('rentOrdem', 'rentOrdemList', function(){ return ordensBase.map(function(o){ return ordemLabel(o); }); }, ordensBase.map(function(o){ return o.cliente; }), function(){ renderRentabilidade(); });
    document.getElementById('rentOrdem').addEventListener('change', renderRentabilidade);
    if(!document.getElementById('rentMes').value){
      var d = new Date();
      document.getElementById('rentMes').value = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
    }
  }
  function calcularReceitaOrdemNoMes(ordemId, mesRef){
    var ano = parseInt(mesRef.slice(0,4),10), mes = parseInt(mesRef.slice(5,7),10);
    var de = mesRef+'-01';
    var ate = mesRef+'-'+String(diasNoMes(ano,mes)).padStart(2,'0');
    var linhasBoletim = calcularBoletim(ordemId, de, ate);
    var receitaBoletim = linhasBoletim.reduce(function(s,l){ return s+l.valorAtual; },0);
    var tarifasHoraDaOrdem = state.tarifasHora.filter(function(t){ return t.ordemId===ordemId; });
    var apropDoMes = state.apropriacoes.filter(function(a){ return a.ordemId===ordemId && a.data>=de && a.data<=ate; });
    var receitaHora = tarifasHoraDaOrdem.reduce(function(s,t){
      var horasEf = apropDoMes.reduce(function(ss,a){ return ss+horasEfetivasMedicao(a, t.baseCalculo); },0);
      return s + horasEf*t.valorHora;
    },0);
    return receitaBoletim + receitaHora;
  }
  function renderRentabilidade(){
    var ordemTexto = document.getElementById('rentOrdem').value.trim();
    var ordem = state.ordens.filter(function(o){ return ordemLabel(o)===ordemTexto; })[0];
    var mesRef = document.getElementById('rentMes').value;
    var el = document.getElementById('rentConteudo');
    if(!ordem || !mesRef){
      el.innerHTML = '<div class="empty-state" style="padding:20px;">Selecione uma ordem e um mês de referência.</div>';
      return;
    }
    var receita = calcularReceitaOrdemNoMes(ordem.id, mesRef);
    var custoAtual = state.custosOrdem.filter(function(c){ return c.ordemId===ordem.id && c.mesRef===mesRef; })[0] || {maoObra:0, combustivel:0, manutencao:0, outros:0};
    var custoTotal = (custoAtual.maoObra||0)+(custoAtual.combustivel||0)+(custoAtual.manutencao||0)+(custoAtual.outros||0);
    var temCusto = custoTotal>0;
    var margem = receita - custoTotal;
    var margemPct = receita>0 ? (margem/receita*100) : 0;

    el.innerHTML =
      '<div class="kpi-row" style="margin-top:14px;">' +
        '<div class="kpi-card"><div class="kpi-label">Receita no mês (R$)</div><div class="kpi-value">'+brNum(receita,2)+'</div></div>' +
        (temCusto ? '<div class="kpi-card"><div class="kpi-label">Custo total (R$)</div><div class="kpi-value">'+brNum(custoTotal,2)+'</div></div>' +
        '<div class="kpi-card"><div class="kpi-label">Margem (R$)</div><div class="kpi-value '+(margem>=0?'diff-ok':'diff-bad')+'">'+brNum(margem,2)+'</div></div>' +
        '<div class="kpi-card"><div class="kpi-label">Margem (%)</div><div class="kpi-value '+(margemPct>=0?'diff-ok':'diff-bad')+'">'+brNum(margemPct,1)+'%</div></div>' : '') +
      '</div>' +
      '<div class="card">' +
        '<h2>Custos do mês (digitado manualmente)</h2>' +
        '<div class="field-row">' +
          '<div class="field"><label>Mão de obra (R$)</label><input type="number" step="0.01" id="rentCustoMaoObra" value="'+(custoAtual.maoObra||0)+'"></div>' +
          '<div class="field"><label>Combustível (R$)</label><input type="number" step="0.01" id="rentCustoCombustivel" value="'+(custoAtual.combustivel||0)+'"></div>' +
          '<div class="field"><label>Manutenção (R$)</label><input type="number" step="0.01" id="rentCustoManutencao" value="'+(custoAtual.manutencao||0)+'"></div>' +
          '<div class="field"><label>Outros (R$)</label><input type="number" step="0.01" id="rentCustoOutros" value="'+(custoAtual.outros||0)+'"></div>' +
        '</div>' +
      '</div>';

    async function salvarCusto(){
      var novo = {
        maoObra: parseFloat(document.getElementById('rentCustoMaoObra').value)||0,
        combustivel: parseFloat(document.getElementById('rentCustoCombustivel').value)||0,
        manutencao: parseFloat(document.getElementById('rentCustoManutencao').value)||0,
        outros: parseFloat(document.getElementById('rentCustoOutros').value)||0,
      };
      var existente = state.custosOrdem.filter(function(c){ return c.ordemId===ordem.id && c.mesRef===mesRef; })[0];
      if(existente){ Object.assign(existente, novo); }
      else { state.custosOrdem.push(Object.assign({id:uid(), ordemId:ordem.id, mesRef:mesRef}, novo)); }
      await saveList('custos_ordem_v1', state.custosOrdem);
      toast('Custo salvo.');
      renderRentabilidade();
    }
    ['rentCustoMaoObra','rentCustoCombustivel','rentCustoManutencao','rentCustoOutros'].forEach(function(id){
      document.getElementById(id).addEventListener('change', salvarCusto);
    });
  }

  /* ============ MEDIÇÃO (tarifas por hora) ============ */
  function populateMedFilters(){
    var ordensBase = state.ordens.slice().sort(function(a,b){ var c=a.cliente.localeCompare(b.cliente,'pt-BR'); return c!==0?c:a.nome.localeCompare(b.nome,'pt-BR'); });
    wireOrdemTrio('medOrdemNumero', 'medOrdem', 'medNCliente', function(){ return ordensBase; }, renderMedicao);
    var equipsOrdenados = state.equipamentos.slice().sort(function(a,b){return a.codigo.localeCompare(b.codigo,'pt-BR');});
    wireComboBox('medEquip', 'medEquipList', function(){ return equipsOrdenados.map(function(e){ return e.codigo; }); }, null, null, 'Todos os equipamentos');
    if(!document.getElementById('medDe').value && !document.getElementById('medAte').value){
      var d = new Date();
      document.getElementById('medDe').value = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01';
    }
  }

  function openTarifaHoraModal(existing){
    var isEdit = !!existing;
    var t = existing || {ordemId:'', servico:'', valorHora:'', horasMinimasMes:176, baseCalculo:'operador'};
    var ordensOrdenadas = state.ordens.slice().sort(function(a,b){
      var c = a.cliente.localeCompare(b.cliente,'pt-BR');
      return c!==0 ? c : a.nome.localeCompare(b.nome,'pt-BR');
    });
    var ordemValorInicial = t.ordemId ? ordemLabel(getOrdem(t.ordemId)) : '';
    var baseOptions = Object.keys(BASE_CALCULO_LABELS).map(function(k){ return '<option value="'+k+'"'+(k===t.baseCalculo?' selected':'')+'>'+esc(BASE_CALCULO_LABELS[k])+'</option>'; }).join('');
    openModal('<h3>'+(isEdit?'Editar tarifa por hora':'Nova tarifa por hora')+'</h3>'+
      '<div id="thFormError"></div>'+
      '<p style="font-size:12.5px;color:var(--text-muted);">A tarifa por hora é vinculada só à Ordem e ao Serviço — não a um equipamento específico, já que os equipamentos fazem rodízio dentro da mesma ordem. As horas de todos os equipamentos apontados nessa ordem no período são somadas automaticamente no Boletim de Medição.</p>'+
      '<div class="field"><label>Ordem</label><div class="combo-wrap"><input type="text" id="fThOrdem" autocomplete="off" value="'+esc(ordemValorInicial)+'" placeholder="Digite ou selecione a ordem…"><div class="combo-list" id="fThOrdemList"></div></div></div>'+
      '<div class="field"><label>Serviço</label><input type="text" id="fThServico" value="'+esc(t.servico)+'" placeholder="Ex: Peneiramento"></div>'+
      '<div class="field"><label>Base de cálculo da hora</label><select id="fThBase">'+baseOptions+'</select></div>'+
      '<div class="field-row">'+
        '<div class="field"><label>Valor por hora (R$)</label><input type="number" step="0.01" id="fThValor" value="'+esc(t.valorHora)+'" placeholder="0,00"></div>'+
        '<div class="field"><label>Horas mínimas/mês</label><input type="number" step="1" id="fThMinimas" value="'+esc(t.horasMinimasMes)+'" placeholder="Ex: 176"></div>'+
      '</div>'+
      '<div class="modal-actions"><button class="btn btn-outline" id="thCancel">Cancelar</button><button class="btn btn-primary" id="thSave">Salvar</button></div>');
    wireComboBox('fThOrdem', 'fThOrdemList', function(){ return ordensOrdenadas.map(function(o){ return ordemLabel(o); }); }, ordensOrdenadas.map(function(o){ return o.cliente; }));
    document.getElementById('thCancel').onclick = closeModal;
    document.getElementById('thSave').onclick = async function(){
      var ordemTexto = document.getElementById('fThOrdem').value.trim();
      var ordemObj = state.ordens.filter(function(o){ return ordemLabel(o)===ordemTexto; })[0];
      var ordemId = ordemObj ? ordemObj.id : null;
      var servico = document.getElementById('fThServico').value.trim();
      var baseCalculo = document.getElementById('fThBase').value;
      var valorHora = parseFloat(document.getElementById('fThValor').value);
      var horasMinimasMes = parseFloat(document.getElementById('fThMinimas').value) || 0;
      var errBox = document.getElementById('thFormError');
      if(!ordemId){ errBox.innerHTML = '<div class="form-error">Ordem não reconhecida — digite o nome ou escolha uma da lista.</div>'; return; }
      if(!servico){ errBox.innerHTML = '<div class="form-error">Informe o serviço.</div>'; return; }
      if(isNaN(valorHora) || valorHora<=0){ errBox.innerHTML = '<div class="form-error">Informe um valor por hora válido.</div>'; return; }
      var dup = state.tarifasHora.some(function(x){ return x.ordemId===ordemId && x.servico.toLowerCase()===servico.toLowerCase() && (!isEdit||x.id!==t.id); });
      if(dup){ errBox.innerHTML = '<div class="form-error">Já existe uma tarifa para esse serviço nessa ordem.</div>'; return; }
      var record = {id:isEdit?t.id:uid(), ordemId:ordemId, servico:servico, valorHora:valorHora, horasMinimasMes:horasMinimasMes, baseCalculo:baseCalculo, codigoTarifa:(isEdit?t.codigoTarifa:null)||gerarCodigoTarifa(ordemObj, 'hora', servico)};
      if(isEdit){ state.tarifasHora = state.tarifasHora.map(function(x){ return x.id===record.id?record:x; }); }
      else { state.tarifasHora.push(record); }
      var ok = await saveList('tarifas_hora_v2', state.tarifasHora);
      closeModal();
      toast(ok?'Tarifa salva.':'Salva localmente — problema ao sincronizar.');
      renderMedicao();
    };
  }
  function deleteTarifaHora(id){
    confirmModal('Remover tarifa', 'Remover esta tarifa por hora? Isso não altera lançamentos já feitos, só deixa de calcular medição para esse serviço/ordem daqui em diante.', async function(){
      state.tarifasHora = state.tarifasHora.filter(function(x){ return x.id!==id; });
      await saveList('tarifas_hora_v2', state.tarifasHora);
      toast('Tarifa removida.');
      renderMedicao();
    });
  }

  function valoresColunaTarifaHora(t){
    var ord = getOrdem(t.ordemId);
    return {
      codigo: t.codigoTarifa||'—', ordem: ord?ordemLabel(ord):'(removida)', servico: t.servico||'—',
      base: BASE_CALCULO_LABELS[t.baseCalculo]||BASE_CALCULO_LABELS.operador,
      valor: brNum(t.valorHora,2), horasMin: brNum(t.horasMinimasMes,0)
    };
  }
  function renderTarifasHoraTabela(){
    var html;
    var lista = aplicaColFiltrosTabela('tarifasHora', state.tarifasHora);
    marcarBotoesFiltroAtivos('tarifasHora');
    if(lista.length===0){
      html = '<tr class="empty-row"><td colspan="6">Nenhuma tarifa por hora cadastrada.</td></tr>';
    } else {
      html = lista.map(function(t){
        var ord = getOrdem(t.ordemId);
        return '<tr><td><span class="plate">'+esc(t.codigoTarifa||'—')+'</span></td><td>'+(ord?esc(ordemLabel(ord)):'<span class="muted-tag">(removida)</span>')+'</td><td>'+esc(t.servico)+'</td>'+
          '<td class="muted-tag">'+esc(BASE_CALCULO_LABELS[t.baseCalculo]||BASE_CALCULO_LABELS.operador)+'</td>'+
          '<td class="num">'+brNum(t.valorHora,2)+'</td><td class="num">'+brNum(t.horasMinimasMes,0)+'</td>'+
          '<td><button class="btn btn-ghost btn-sm" data-edit-th="'+t.id+'" title="Editar"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg></button><button class="btn btn-danger-ghost btn-sm" data-del-th="'+t.id+'" title="Remover"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg></button></td></tr>';
      }).join('');
    }
    ['tarifasHoraBody'].forEach(function(bodyId){
      var body = document.getElementById(bodyId);
      if(!body) return;
      body.innerHTML = html;
      body.querySelectorAll('[data-edit-th]').forEach(function(b){ b.onclick=function(){ openTarifaHoraModal(getTarifaHora(b.getAttribute('data-edit-th'))); }; });
      body.querySelectorAll('[data-del-th]').forEach(function(b){ b.onclick=function(){ deleteTarifaHora(b.getAttribute('data-del-th')); }; });
    });
  }

  /* ---- Tarifas de Produção (por tonelada, vinculadas à ordem) ---- */
  function getTarifaProducao(id){ for(var i=0;i<state.tarifasProducao.length;i++){ if(state.tarifasProducao[i].id===id) return state.tarifasProducao[i]; } return null; }
  // Retorna a versão da tarifa (por ordem+serviço) vigente numa data específica — permite que preços
  // reajustados no cadastro não alterem retroativamente medições já feitas em meses anteriores.
  function tarifaVigenteNaData(ordemId, servico, data){
    var candidatas = state.tarifasProducao.filter(function(t){
      return t.ordemId===ordemId && t.servico===servico &&
        (!t.vigenciaInicio || t.vigenciaInicio<=data) &&
        (!t.vigenciaFim || t.vigenciaFim>=data);
    });
    if(candidatas.length===0) return null;
    candidatas.sort(function(a,b){ return (b.vigenciaInicio||'').localeCompare(a.vigenciaInicio||''); });
    return candidatas[0];
  }

  function openTarifaProducaoModal(existing){
    var isEdit = !!existing;
    var t = existing || {ordemId:'', servico:'', apelido:'', meta:'', unidade:'TON', valor:''};
    var ordensOrdenadas = state.ordens.slice().sort(function(a,b){
      var c = a.cliente.localeCompare(b.cliente,'pt-BR');
      return c!==0 ? c : a.nome.localeCompare(b.nome,'pt-BR');
    });
    var ordemValorInicial = t.ordemId ? ordemLabel(getOrdem(t.ordemId)) : '';
    openModal('<h3>'+(isEdit?'Editar tarifa de produção':'Nova tarifa de produção')+'</h3>'+
      '<div id="tpFormError"></div>'+
      '<div class="field"><label>Ordem</label><div class="combo-wrap"><input type="text" id="fTpOrdem" autocomplete="off" value="'+esc(ordemValorInicial)+'" placeholder="Digite ou selecione a ordem…"><div class="combo-list" id="fTpOrdemList"></div></div></div>'+
      '<div class="field"><label>Descrição completa (aparece em Tarifa/Medição)</label><div class="combo-wrap"><input type="text" id="fTpServico" autocomplete="off" value="'+esc(t.servico)+'" placeholder="Ex: PROCESSAMENTO E CARREGAMENTO DE VAGÕES MACAÉ/RJ - (2000 X 2000)"><div class="combo-list" id="fTpServicoList"></div></div></div>'+
      '<div class="field"><label>Apelido (aparece em Produção — mantenha curto)</label><input type="text" id="fTpApelido" value="'+esc(t.apelido||'')+'" placeholder="Ex: Sucata"></div>'+
      '<div class="field-row">'+
        '<div class="field"><label>Unidade</label><input type="text" id="fTpUnidade" value="'+esc(t.unidade)+'" placeholder="Ex: TON"></div>'+
        '<div class="field"><label>Meta mensal</label><input type="number" step="0.01" id="fTpMeta" value="'+esc(t.meta||'')+'" placeholder="Ex: 3000"></div>'+
        '<div class="field"><label>Valor (R$)</label><input type="number" step="0.01" id="fTpValor" value="'+esc(t.valor)+'" placeholder="0,00"></div>'+
      '</div>'+
      (isEdit ? '<div id="tpVigenciaWrap" style="display:none;"><div class="field"><label>Novo valor vigente a partir de</label><input type="date" id="fTpVigencia" value="'+todayISO()+'"></div><div class="shared-note" style="display:block;margin-bottom:12px;">O valor antigo é preservado com sua vigência original — medições de meses anteriores continuam usando o preço que estava em vigor na época, sem alteração retroativa.</div></div>' : '<input type="hidden" id="fTpVigencia" value="">')+
      '<div class="modal-actions"><button class="btn btn-outline" id="tpCancel">Cancelar</button><button class="btn btn-primary" id="tpSave">Salvar</button></div>');
    wireComboBox('fTpOrdem', 'fTpOrdemList', function(){ return ordensOrdenadas.map(function(o){ return ordemLabel(o); }); }, ordensOrdenadas.map(function(o){ return o.cliente; }));
    wireComboBox('fTpServico', 'fTpServicoList', function(){
      var ordemTexto = document.getElementById('fTpOrdem').value.trim();
      var ordemSel = state.ordens.filter(function(o){ return ordemLabel(o)===ordemTexto; })[0];
      if(!ordemSel) return [];
      return state.tarifasProducao.filter(function(x){ return x.ordemId===ordemSel.id && tipoRealTarifaProducao(x)==='pesagem'; }).map(function(x){ return x.servico; });
    });
    document.getElementById('tpCancel').onclick = closeModal;
    if(isEdit){
      document.getElementById('fTpValor').addEventListener('input', function(){
        var mudou = parseFloat(this.value) !== t.valor;
        document.getElementById('tpVigenciaWrap').style.display = mudou ? 'block' : 'none';
      });
    }
    document.getElementById('tpSave').onclick = async function(){
      var ordemTexto = document.getElementById('fTpOrdem').value.trim();
      var ordemObj = state.ordens.filter(function(o){ return ordemLabel(o)===ordemTexto; })[0];
      var ordemId = ordemObj ? ordemObj.id : null;
      var servico = document.getElementById('fTpServico').value.trim();
      var apelido = normalizarTituloCase(document.getElementById('fTpApelido').value);
      var meta = parseFloat(document.getElementById('fTpMeta').value) || 0;
      var unidade = document.getElementById('fTpUnidade').value.trim() || 'TON';
      var valor = parseFloat(document.getElementById('fTpValor').value);
      var vigenciaCampo = document.getElementById('fTpVigencia').value;
      var vigenciaNova = vigenciaCampo || todayISO();
      var errBox = document.getElementById('tpFormError');
      if(!ordemId){ errBox.innerHTML = '<div class="form-error">Ordem não reconhecida — digite o nome ou escolha uma da lista.</div>'; return; }
      if(!servico){ errBox.innerHTML = '<div class="form-error">Informe a descrição completa do serviço.</div>'; return; }
      if(!apelido){ errBox.innerHTML = '<div class="form-error">Informe o apelido (descrição curta pra Produção).</div>'; return; }
      if(isNaN(valor) || valor<=0){ errBox.innerHTML = '<div class="form-error">Informe um valor válido.</div>'; return; }
      var codigoTarifaFinal = (isEdit && t.codigoTarifa) || gerarCodigoTarifa(ordemObj, tipoRealTarifaProducao({unidade:unidade}), servico);
      if(isEdit && valor!==t.valor){
        // Preço mudou: fecha a vigência do registro antigo no dia anterior e cria uma nova versão.
        var diaAnterior = new Date(vigenciaNova+'T00:00:00'); diaAnterior.setDate(diaAnterior.getDate()-1);
        var vigenciaFimAntiga = diaAnterior.toISOString().slice(0,10);
        state.tarifasProducao = state.tarifasProducao.map(function(x){
          return x.id===t.id ? Object.assign({}, x, {vigenciaFim: vigenciaFimAntiga}) : x;
        });
        state.tarifasProducao.push({id:uid(), ordemId:ordemId, servico:servico, apelido:apelido, meta:meta, servicoCodigo:(t.servicoCodigo||codigoTarifaFinal), unidade:unidade, valor:valor, vigenciaInicio:vigenciaNova, vigenciaFim:null, codigoTarifa:codigoTarifaFinal});
      } else {
        // Tarifa nova (não é troca de preço numa já existente): sem data de vigência informada, vale
        // desde sempre — assim ela também se aplica a produção já lançada antes do cadastro da tarifa.
        var record = {id:isEdit?t.id:uid(), ordemId:ordemId, servico:servico, apelido:apelido, meta:meta, servicoCodigo:(isEdit&&t.servicoCodigo)||codigoTarifaFinal, unidade:unidade, valor:valor, vigenciaInicio: isEdit?(t.vigenciaInicio||null):(vigenciaCampo||null), vigenciaFim: isEdit?(t.vigenciaFim||null):null, codigoTarifa:codigoTarifaFinal};
        if(isEdit){ state.tarifasProducao = state.tarifasProducao.map(function(x){ return x.id===record.id?record:x; }); }
        else { state.tarifasProducao.push(record); }
      }
      var ok = await saveList('tarifas_producao_v3', state.tarifasProducao);
      closeModal();
      toast(ok?'Tarifa salva.':'Salva localmente — problema ao sincronizar.');
      renderTarifasProducaoTabela();
    };
  }
  function deleteTarifaProducao(id){
    confirmModal('Remover tarifa', 'Remover esta tarifa de produção? Isso não altera lançamentos já feitos, só deixa de calcular valor de produção para essa ordem/serviço daqui em diante.', async function(){
      state.tarifasProducao = state.tarifasProducao.filter(function(x){ return x.id!==id; });
      await saveList('tarifas_producao_v3', state.tarifasProducao);
      toast('Tarifa removida.');
      renderTarifasProducaoTabela();
    });
  }
  function vigenciaTarifaTextoSimples(t){
    if(t.vigenciaFim) return (t.vigenciaInicio?brDate(t.vigenciaInicio):'—')+' a '+brDate(t.vigenciaFim)+' (histórico)';
    return t.vigenciaInicio ? 'desde '+brDate(t.vigenciaInicio) : 'sempre';
  }
  function valoresColunaTarifaProducao(t){
    var ord = getOrdem(t.ordemId);
    return { codigo: t.codigoTarifa||'—', ordem: ord?ordemLabel(ord):'(removida)', servico: t.servico||'—', unidade: t.unidade||'—', valor: brNum(t.valor,2), vigencia: vigenciaTarifaTextoSimples(t) };
  }
  function renderTarifasProducaoTabela(){
    var body = document.getElementById('tarifasProducaoBody');
    if(!body) return;
    var buscaNumero = (document.getElementById('filtroTarifaOrdemNumero')||{}).value || '';
    var buscaNome = (document.getElementById('filtroTarifaOrdemNome')||{}).value || '';
    var buscaServico = (document.getElementById('filtroTarifaServico')||{}).value || '';
    buscaNumero = buscaNumero.trim().toLowerCase();
    buscaNome = buscaNome.trim().toLowerCase();
    buscaServico = buscaServico.trim().toLowerCase();
    var lista = state.tarifasProducao.filter(function(t){
      var ord = getOrdem(t.ordemId);
      if(buscaNumero && !(ord && (ord.numero||'').toLowerCase().indexOf(buscaNumero)>-1)) return false;
      if(buscaNome && !(ord && ord.nome.toLowerCase().indexOf(buscaNome)>-1)) return false;
      if(buscaServico && (t.servico||'').toLowerCase().indexOf(buscaServico)===-1) return false;
      return true;
    });
    lista = aplicaColFiltrosTabela('tarifasProducao', lista);
    marcarBotoesFiltroAtivos('tarifasProducao');
    if(lista.length===0){ body.innerHTML='<tr class="empty-row"><td colspan="7">Nenhuma tarifa de produção encontrada.</td></tr>'; return; }
    var ordenadas = lista.slice().sort(function(a,b){
      var c = (a.ordemId||'').localeCompare(b.ordemId||''); if(c!==0) return c;
      c = (a.servico||'').localeCompare(b.servico||'','pt-BR'); if(c!==0) return c;
      return (b.vigenciaInicio||'').localeCompare(a.vigenciaInicio||'');
    });
    body.innerHTML = ordenadas.map(function(t){
      var ord = getOrdem(t.ordemId);
      var vigenciaTxt = t.vigenciaFim
        ? (t.vigenciaInicio?brDate(t.vigenciaInicio):'—')+' a '+brDate(t.vigenciaFim)+' <span class="muted-tag">(histórico)</span>'
        : (t.vigenciaInicio ? 'desde '+brDate(t.vigenciaInicio) : 'sempre');
      return '<tr><td><span class="plate">'+esc(t.codigoTarifa||'—')+'</span></td><td>'+(ord?esc(ordemLabel(ord)):'<span class="muted-tag">(removida)</span>')+'</td><td>'+esc(t.servico)+'</td>'+
        '<td>'+esc(t.unidade)+'</td><td class="num">'+brNum(t.valor,2)+'</td><td>'+vigenciaTxt+'</td>'+
        '<td><button class="btn btn-ghost btn-sm" data-edit-tp="'+t.id+'" title="Editar"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg></button><button class="btn btn-danger-ghost btn-sm" data-del-tp="'+t.id+'" title="Remover"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg></button></td></tr>';
    }).join('');
    body.querySelectorAll('[data-edit-tp]').forEach(function(b){ b.onclick=function(){ openTarifaProducaoModal(getTarifaProducao(b.getAttribute('data-edit-tp'))); }; });
    body.querySelectorAll('[data-del-tp]').forEach(function(b){ b.onclick=function(){ deleteTarifaProducao(b.getAttribute('data-del-tp')); }; });
  }

  /* ---- Tarifas por Verba (valor fixo por evento, ex.: mobilização/desmobilização) ---- */
  function getTarifaVerba(id){ for(var i=0;i<state.tarifasVerba.length;i++){ if(state.tarifasVerba[i].id===id) return state.tarifasVerba[i]; } return null; }
  function tarifaVerbaVigenteNaData(ordemId, servico, data){
    var candidatas = state.tarifasVerba.filter(function(t){
      return t.ordemId===ordemId && t.servico===servico &&
        (!t.vigenciaInicio || t.vigenciaInicio<=data) &&
        (!t.vigenciaFim || t.vigenciaFim>=data);
    });
    if(candidatas.length===0) return null;
    candidatas.sort(function(a,b){ return (b.vigenciaInicio||'').localeCompare(a.vigenciaInicio||''); });
    return candidatas[0];
  }
  function tarifasVerbaDaOrdem(ordemId){
    return state.tarifasVerba.filter(function(t){ return t.ordemId===ordemId; });
  }

