  function renderProducao(){
    populateProdFilters();
    var ordemTexto = document.getElementById('prodOrdem').value.trim();
    var ordem = state.ordens.filter(function(o){ return ordemLabel(o)===ordemTexto; })[0];
    if(ordem && state.perfil==='campo' && state.operadorClienteRestrito && ordem.cliente!==state.operadorClienteRestrito){
      ordem = null; // ordem digitada não pertence ao cliente ao qual esse operador está restrito
    }
    var el = document.getElementById('prodConteudo');
    if(!ordem){
      var clienteSel = clienteDoNumeroField('prodNCliente') || document.getElementById('prodCliente').value.trim();
      if(clienteSel && CLIENTES.indexOf(clienteSel)===-1) clienteSel = null;
      if(clienteSel){
        var ordensDoCliente = state.ordens.filter(function(o){
          return o.cliente===clienteSel && ((o.materiaisPesagem||[]).length || (o.materiaisHora||[]).length || (o.materiaisVerba||[]).length);
        });
        if(ordensDoCliente.length>1){
          montarBlocoProducaoCliente(ordensDoCliente, 'prodConteudo');
          return;
        }
        if(ordensDoCliente.length===1){ ordem = ordensDoCliente[0]; }
      }
    }
    if(!ordem){
      montarBlocoProducaoTotal('prodConteudo');
      return;
    }
    montarBlocoProducao(ordem, 'prodConteudo');
  }

  // Visão total: quando nenhuma Ordem/Cliente está selecionado, mostra a produção por tonelada
  // agregada de TODOS os clientes no mês de referência, em vez de só pedir pra escolher uma Ordem.
  function montarBlocoProducaoTotal(containerId){
    var el = document.getElementById(containerId);
    var mesRef = document.getElementById('prodMes').value || (new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0'));

    var porCliente = {};
    state.ordens.forEach(function(o){
      var materiais = colunasProducaoDaOrdem(o.id, mesRef).pesagem;
      if(materiais.length===0) return;
      var metaOrdem = materiais.reduce(function(s,m){ return s+(m.meta||0); },0);
      // Só soma produção lançada sob um material que AINDA está cadastrado como Tarifa dessa
      // ordem (mesmo casamento por nome usado no Boletim de Medição) -- evita somar lançamentos
      // órfãos de um material renomeado/removido, que inflavam o total sem bater com nenhuma meta.
      var producaoOrdem = state.producoes.filter(function(p){
        if(p.ordemId!==o.id || p.tipo!=='pesagem' || p.data.indexOf(mesRef)!==0) return false;
        return materiais.some(function(m){ return mesmoServico(m.nome, p.material); });
      }).reduce(function(s,p){ return s+(p.valor||0); },0);
      if(!porCliente[o.cliente]) porCliente[o.cliente] = {meta:0, producao:0, ordens:0};
      porCliente[o.cliente].meta += metaOrdem;
      porCliente[o.cliente].producao += producaoOrdem;
      porCliente[o.cliente].ordens += 1;
    });

    var linhas = Object.keys(porCliente).map(function(c){
      var g = porCliente[c];
      return {cliente:c, meta:g.meta, producao:g.producao, ordens:g.ordens};
    }).sort(function(a,b){ return b.producao-a.producao; });

    if(linhas.length===0){
      el.innerHTML = '<div class="empty-state" style="padding:24px;">Nenhum cliente com serviço de Pesagem (tonelada) cadastrado ainda. Selecione uma Ordem ou Cliente acima pra lançar, ou cadastre tarifas de Produção primeiro.</div>';
      return;
    }

    var metaGeral = linhas.reduce(function(s,l){ return s+l.meta; },0);
    var producaoGeral = linhas.reduce(function(s,l){ return s+l.producao; },0);
    var pctGeral = metaGeral>0 ? Math.round(producaoGeral/metaGeral*1000)/10 : null;

    function kpi(label, value){ return '<div class="kpi-card"><div class="kpi-label">'+esc(label)+'</div><div class="kpi-value">'+value+'</div></div>'; }
    var kpiHtml = '<div class="kpi-row" style="margin-bottom:16px;">' +
      kpi('Meta mensal total (ton)', brNum(metaGeral,2)) +
      kpi('Produção total no mês (ton)', brNum(producaoGeral,2)) +
      (pctGeral!==null ? kpiCardArco('% da meta atingido', pctGeral) : kpi('% da meta atingido', '—')) +
      kpi('Clientes com produção', linhas.filter(function(l){ return l.producao>0; }).length+' / '+linhas.length) +
    '</div>';

    var chartEntries = linhas.slice(0,10).map(function(l){ return {label:l.cliente, value:l.producao}; });

    var tabelaHtml = '<div class="table-wrap"><table><thead><tr><th>Cliente</th><th class="num">Ordens</th><th class="num">Meta (ton)</th><th class="num">Produção (ton)</th><th class="num">% da meta</th></tr></thead><tbody>' +
      linhas.map(function(l){
        return '<tr><td>'+(clienteNumero(l.cliente)?esc(clienteNumero(l.cliente))+' ':'')+esc(l.cliente)+'</td>' +
          '<td class="num">'+l.ordens+'</td><td class="num">'+brNum(l.meta,2)+'</td><td class="num">'+brNum(l.producao,2)+'</td>' +
          celulaPctMeta(l.producao, l.meta) + '</tr>';
      }).join('') +
    '</tbody></table></div>';

    el.innerHTML =
      '<div class="shared-note" style="display:block;margin-bottom:16px;"><b>Visão total</b> — produção por tonelada de todos os clientes em '+mesRef+'. Selecione uma Ordem ou Cliente acima pra lançar/editar valores de um cliente específico.</div>' +
      kpiHtml +
      '<div class="grid-2">' +
        '<div class="card"><h2>Produção por cliente (top 10)</h2><div id="prodTotalChart" style="max-height:260px;overflow:auto;"></div></div>' +
        '<div class="card"><h2>Ranking por cliente</h2>'+tabelaHtml+'</div>' +
      '</div>';

    document.getElementById('prodTotalChart').innerHTML = svgBarChartHtml(chartEntries, '#E8833A', function(v){ return brNum(v,1)+'t'; });
  }

