  // Ajusta o "zoom" do conteúdo visível antes de imprimir, pra caber melhor numa única página A4
  // paisagem. Usa a propriedade zoom (não transform) porque só o zoom muda o tamanho real considerado
  // na paginação da impressão — transform:scale só muda a aparência, sem reduzir o número de páginas.
  function imprimirEmUmaPagina(){
    var view = document.querySelector('.view.active');
    if(!view){ window.print(); return; }
    view.style.zoom = '';
    requestAnimationFrame(function(){
      var alturaDisponivelPx = 620; // altura útil conservadora de A4 paisagem com margem de 8mm
      var alturaConteudo = view.scrollHeight;
      var escala = alturaConteudo>alturaDisponivelPx ? Math.max(0.28, alturaDisponivelPx/alturaConteudo) : 1;
      if(escala<1){ view.style.zoom = escala; }
      function restaurar(){
        view.style.zoom = '';
        window.removeEventListener('afterprint', restaurar);
      }
      window.addEventListener('afterprint', restaurar);
      requestAnimationFrame(function(){
        requestAnimationFrame(function(){
          window.print();
          setTimeout(restaurar, 1000);
        });
      });
    });
  }
  document.getElementById('dashImprimirBtn').addEventListener('click', imprimirEmUmaPagina);
