  function applyPerfil(perfil){
    state.perfil = perfil;
    var labels = {campo:'Campo', limitado:'Acesso limitado', admin:'Administrador'};
    var nomeTag = state.usuarioLogado ? ' · '+state.usuarioLogado.nome : '';
    document.getElementById('perfilLabel').textContent = 'Perfil: '+(labels[perfil]||perfil)+nomeTag;
    // Esconde do menu lateral qualquer tela que essa pessoa não tenha
    // permissão de ver — "Backup e Limpeza" continua exclusiva de
    // administrador (não é liberável por checkbox); as demais seguem
    // podeVerTela(), que já olha pras telas marcadas em "Gerenciar Acessos".
    document.querySelectorAll('.nav-item[data-view]').forEach(function(el){
      var view = el.dataset.view;
      if(view === 'manutencao'){ el.style.display = (perfil==='admin') ? '' : 'none'; return; }
      el.style.display = podeVerTela(view) ? '' : 'none';
    });
    var ordemPreferencia = perfil==='campo'
      ? ['apropriacao','historico','producao']
      : ['dashboard','apropriacao','historico','producao','cadastro','consolidado','medicao'];
    var primeiraPermitida = ordemPreferencia.filter(podeVerTela)[0] || 'apropriacao';
    switchView(primeiraPermitida);
  }

